    "    // so its rhythm is the standard's (the PlayStation 2 row), not the console's\n"
    "    if (isShow(LR_CABLE)) { b = vec4(0.5, 0.75, 0.75, 0.875); c = 0.0; }\n"
    "    t.lineFrac = mix(b.x, b.y, t.pal);\n"
    "    t.fieldStep = mix(b.z, b.w, t.pal);\n"
    "    // 24 is a multiple of every field cycle above (1, 2, 3, 4, 8), so the phase never drifts\n"
    "    float fc = LR_STEADY > 0.5 ? 0.0 : float(frameCount % 24u);\n"
    "    // NES and SNES (NTSC, not interlaced): 1364 master clocks per line, 227 1/3 cycles, so a\n"
    "    // 262-line frame moves the phase by 1/3 cycle. But every other frame is 4 clocks short (the\n"
    "    // NES skips a dot, the SNES shortens one line), which moves it by 2/3 instead, so the phase\n"
    "    // only alternates between two values, 2/3 cycle apart: the dots jitter instead of crawling.\n"
    "    // (A 3-frame crawl only happens in the few NES games that blank the start of the frame.)\n"
    "    t.altStep = (id < 1.5 && t.pal < 0.5 && t.interlace < 0.5) ? 2.0 / 3.0 : 0.0;\n"
    "    t.framePhase = t.altStep > 0.0 ? t.altStep * mod(fc, 2.0) : fract(fc * t.fieldStep);\n"
    "    t.vsw = mod(fc * c, 2.0);\n"
    "    t.vswStep = c;\n"
    "    return t;\n"
    "}\n"
    "\n"
    "// Frame pixels and rows per console pixel and line, for effects sized on the glass (glow,\n"
    "// misconvergence). Only the Amiga needs it: its emulators send hires frames (2 pixels per lores\n"
    "// pixel) and draw every line twice or weave two fields. Other consoles keep (1, 1).\n"
    "vec2 consoleUnit(Timing t) { return isAmiga(t) ? vec2(t.hres, t.interlace > 0.5 ? 2.0 : 1.0) : vec2(1.0); }\n"
    "\n"
    "// y is a source row; rows of one upscaled block belong to the same native line\n"
    "float nativeLine(float y, Timing t) { return floor(y / t.scale); }\n"
    "float physLine(float y, Timing t) { float l = nativeLine(y, t); return t.interlace > 0.5 ? floor(l * 0.5) : l; }\n"
    "bool oddField(float y, Timing t) { return t.interlace > 0.5 && mod(nativeLine(y, t), 2.0) > 0.5; }\n"
    "\n"
    "// Subcarrier phase at time tUs (microseconds from the start of the active line) on line y,\n"
    "// off cycles later in the frame sequence (see steadyFrames)\n"
    "float phaseAtOff(float tUs, float y, Timing t, float off)\n"
    "{\n"
    "    float fo = oddField(y, t) ? t.fieldStep : 0.0;\n"
    "    return TAU * fract(fract(t.fsc * tUs) + fract(t.lineFrac * physLine(y, t)) + fo + t.framePhase + off);\n"
    "}\n"
    "float phaseAt(float tUs, float y, Timing t) { return phaseAtOff(tUs, y, t, 0.0); }\n"
    "\n"
    "// PAL alternates the sign of V on every line; vsw: the V-switch offset of the frame\n"
    "float vSignW(float y, Timing t, float vsw)\n"
    "{\n"
    "    if (t.pal < 0.5) return 1.0;\n"
    "    float pl = physLine(y, t) + vsw + (oddField(y, t) ? 1.0 : 0.0);\n"
    "    return mod(pl, 2.0) < 0.5 ? 1.0 : -1.0;\n"
    "}\n"
    "float vSign(float y, Timing t) { return vSignW(y, t, t.vsw); }\n"
    "\n"
    "// No flicker: the frames the eye blends together.\n"
    "// Most consoles shift the colour subcarrier from one frame to the next (a 2-frame cycle on the\n"
    "// PlayStation, up to 8 in PAL), so the cross-colour and the dots along coloured edges move. At\n"
    "// 50 or 60 frames a second the eye sees their average, in which they largely cancel. A single\n"
    "// frozen frame would show all of them at full strength, more than anyone ever saw. So with No\n"
    "// flicker on, the encoder makes the signal for two or three frames of the cycle and the decoder\n"
    "// averages what they show: the three frames of a 3-frame cycle, otherwise the first frame and\n"
    "// the one half a subcarrier cycle on (every 2, 4 and 8-frame cycle reaches it), which cancels the\n"
    "// same artefacts. The NES and SNES alternate between two phases 2/3 cycle apart: their average\n"
    "// only halves the artefacts, as on the real console. With No flicker off, one frame: the moving\n"
    "// original.\n"
    "// Returns the number of frames (1 to 3); off: their phase offsets (cycles), vsw: their PAL\n"
    "// V-switch offsets.\n"
    "int steadyFrames(Timing t, out vec3 off, out vec3 vsw)\n"
    "{\n"
    "    off = vec3(0.0);\n"
    "    vsw = vec3(t.vsw, 0.0, 0.0);\n"
    "    if (LR_STEADY < 0.5) return 1;\n"
    "    if (t.altStep > 0.0)\n"
    "    {\n"
    "        off.y = t.altStep;\n"
    "        return 2;\n"
    "    }\n"
    "    float s = t.fieldStep;\n"
    "    if (abs(s - 1.0 / 3.0) < 0.01 || abs(s - 2.0 / 3.0) < 0.01)\n"
    "    {\n"
    "        off = vec3(0.0, fract(s), fract(2.0 * s));\n"
    "        vsw = vec3(0.0, mod(t.vswStep, 2.0), mod(2.0 * t.vswStep, 2.0));\n"
    "        return 3;\n"
    "    }\n"
    "    for (float k = 1.0; k <= 8.0; k += 1.0)\n"
    "    {\n"
    "        if (abs(fract(k * s) - 0.5) < 0.01)\n"
    "        {\n"
    "            off.y = 0.5;\n"
    "            vsw.y = mod(k * t.vswStep, 2.0);\n"
    "            return 2;\n"
    "        }\n"
    "    }\n"
    "    // no phase change, but a PAL V-switch that flips every frame (odd line count per field)\n"
    "    if (t.pal > 0.5 && t.vswStep > 0.5)\n"
    "    {\n"
    "        vsw.y = 1.0;\n"
    "        return 2;\n"
    "    }\n"
    "    return 1;\n"
    "}\n"
    "\n"
    "// ---------------------------------------------------------------------------\n"
    "// Monitor in millimetres: PC monitors (31 kHz modes) always, and 15 kHz monitors such as\n"
    "// the Commodore 1084S when \"15 kHz monitor in mm\" is on. The tube is described like on its\n"
    "// spec sheet (size, mask pitch, beam spot on dark and on white), so every video mode follows\n"
    "// from the same tube: 320x200 doubled to 400 lines or 1024x768 on a PC monitor, PAL or NTSC\n"
    "// on the 1084S (NTSC lines sit further apart, so they show more).\n"
    "// Typical mid-90s 15-inch PC monitor: 13.8-14 inch viewable, 0.28 mm dot pitch, a spot of\n"
    "// about 0.45 mm on white (sharp at 800x600, soft at 1024x768), dynamic focus keeping the\n"
    "// corners below 1.5 x the centre spot.\n"
    "// ---------------------------------------------------------------------------\n"
    "\n"
    "const float FWHM_TO_SIGMA = 0.4246609;   // Gaussian: sigma = FWHM / (2 sqrt(2 ln 2))\n"
    "\n"
    "bool isPC(float scan) { return scan > 0.5 && scan < 1.5; }\n"
    "\n"
    "// the tube is described in mm\n"
    "bool inMM(float scan) { return isPC(scan) || (scan < 0.5 && LR_MON_MM > 0.5); }\n"
    "\n"
    "// Viewable tube face in mm: one inch less than the nominal size, 4:3\n"
    "vec2 monTubeMM()\n"
    "{\n"
    "    float d = (LR_MON_SIZE - 1.0) * 25.4;\n"
    "    return vec2(0.8 * d, 0.6 * d);\n"
    "}\n"
    "\n"
    "// The share of the scan that shows on the tube, across and down: less than 1 when overscan is\n"
    "// positive (the picture runs past the edges), more when it is negative (a black border).\n"
    "// Overscan sets both; Overscan height is added to it for the height alone.\n"
    "vec2 monShown() { return vec2(1.0 - LR_OVERSCAN, 1.0 - LR_OVERSCAN - LR_OVERSCAN_V); }\n"
    "\n"
    "// The full scan (active line x active lines) in mm: smaller than the tube face when\n"
    "// overscan is negative (black border), larger when it is positive\n"
    "vec2 monScanMM() { return monTubeMM() / monShown(); }\n"
    "\n"
    "// The spot grows toward the corners (deflection defocus); c is the position on the tube, -1..1\n"
    "float monCornerGrowth(vec2 c) { return 1.0 + (LR_MON_CORNER - 1.0) * 0.5 * dot(c, c); }\n"
    "\n"
    "// Share of the active line that the source covers. A 15 kHz monitor in mm shows the whole\n"
    "// active line (52.6 us NTSC, 52 us PAL), so a 320-pixel Amiga line (45 us) leaves side\n"
    "// borders, like the real 1084S. PC monitors and the TV model fill the width.\n"
    "float activeShare(Timing t, vec2 orig)\n"
    "{\n"
    "    if (!(t.scan < 0.5 && LR_MON_MM > 0.5)) return 1.0;\n"
    "    return min(orig.x / t.pclk / (t.pal > 0.5 ? 52.0 : 52.6), 1.0);\n"
    "}\n"
    "\n"
    "// Standard normal density and cumulative distribution\n"
    "// (erf after Abramowitz & Stegun 7.1.26, error below 1.5e-7)\n"
    "vec3 gaussPdf(vec3 z) { return 0.39894228 * exp(-0.5 * z * z); }\n"
    "vec3 gaussCdf(vec3 z)\n"
    "{\n"
    "    vec3 x = abs(z) * 0.70710678;\n"
    "    vec3 t = 1.0 / (1.0 + 0.3275911 * x);\n"
    "    vec3 p = ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t;\n"
    "    return 0.5 + 0.5 * sign(z) * (1.0 - p * exp(-x * x));\n"
    "}\n"
    "\n"
    "// ---------------------------------------------------------------------------\n"
    "// Colour of the TV: its chroma decoder and its phosphors\n"
    "// ---------------------------------------------------------------------------\n"
    "\n"
    "// Chroma decoder: 1 = by the standard. American and Japanese TVs demodulated R-Y and G-Y\n"
    "// on shifted axes with their own gains (\"red push\", warmer skin tones). PAL TVs, broadcast\n"
    "// monitors and RGB inputs use the standard axes. A TV show reaches the TV as composite.\n"
    "float decoderType(Timing t, float cable)\n"
    "{\n"
    "    if (LR_DEMOD > 0.5) return LR_DEMOD;\n"
    "    return (t.pal < 0.5 && (cable < 2.5 || isShow(cable))) ? 2.0 : 1.0;\n"
    "}\n"
    "\n"
    "// R, G, B from Y and the demodulated U, V (U = 0.492 (B-Y), V = 0.877 (R-Y)).\n"
    "// Consumer axes and gains from the Sony CXA2025AS datasheet, relative to B-Y:\n"
    "// US mode R-Y 112 deg x0.83, G-Y 252 deg x0.30; Japanese mode R-Y 95 deg x0.78, G-Y 240 deg x0.30.\n"
    "vec3 decodeRGB(float Y, vec2 uv, float dec)\n"
    "{\n"
    "    if (dec < 1.5)\n"
    "        return vec3(Y + 1.13983 * uv.y, Y - 0.39465 * uv.x - 0.58060 * uv.y, Y + 2.03211 * uv.x);\n"
    "    bool us = dec < 2.5;\n"
    "    float ar = radians(us ? 112.0 : 95.0), gr = us ? 0.83 : 0.78;\n"
    "    float ag = radians(us ? 252.0 : 240.0), gg = 0.30;\n"
    "    float ry = (uv.x * cos(ar) + uv.y * sin(ar)) * gr / 0.492;\n"
    "    float gy = (uv.x * cos(ag) + uv.y * sin(ag)) * gg / 0.492;\n"
    "    return vec3(Y + ry, Y + gy, Y + uv.x / 0.492);\n"
    "}\n"
    "\n"
    "// Phosphors: 1 sRGB / Rec.709, 2 SMPTE-C (NTSC sets), 3 EBU (PAL sets, broadcast monitors),\n"
    "// 4 Japanese P22 (Sony Trinitron and Japanese sets, arcade monitors).\n"
    "float phosphorSet(Timing t)\n"
    "{\n"
    "    if (LR_PHOS > 0.5) return LR_PHOS;\n"
    "    if (t.scan > 0.5 && t.scan < 1.5) return 1.0;   // PC monitors: sRGB was defined from them\n"
    "    if (t.id > 7.5) return 4.0;                       // arcade monitors\n"
    "    return t.pal > 0.5 ? 3.0 : 2.0;\n"
    "}\n"
    "\n"
    "// Linear phosphor RGB -> linear Rec.709 RGB, white (D65) kept. Primaries (x, y):\n"
    "// SMPTE-C R .630 .340 G .310 .595 B .155 .070; EBU R .640 .330 G .290 .600 B .150 .060;\n"
    "// Japanese P22 R .625 .350 G .280 .605 B .152 .062 (Sony KV-20M20 and others, via Dogway's grade).\n"
    "mat3 phosphorMatrix(float p)\n"
    "{\n"
    "    if (p < 2.5) return mat3(0.939542, 0.017772, -0.001622, 0.050181, 0.965793, -0.004370, 0.010277, 0.016435, 1.005991);\n"
    "    if (p < 3.5) return mat3(1.044043, 0.0, 0.0, -0.044043, 1.0, 0.011793, 0.0, 0.0, 0.988207);\n"
    "    return mat3(1.081942, 0.038032, -0.007481, -0.088427, 0.959991, 0.015170, 0.006485, 0.001977, 0.992311);\n"
    "}\n"
    "\n"
    "#if defined(VERTEX)\n"
    "uniform mat4 MVPMatrix;\n"
    "in vec4 VertexCoord;\n"
    "in vec2 TexCoord;\n"
    "out vec2 vTexCoord;\n"
    "flat out vec3 vWhite;\n"
    "flat out vec4 vTiming;   // scan mode, PAL, interlaced, internal resolution\n"
    "flat out float vPhos;    // phosphor set\n"
    "flat out float vShare;   // share of the active line the source covers\n"
    "flat out float vAmiga;\n"
    "\n"
    "// Blackbody colour of the TV's white, relative to D65\n"
    "vec3 kelvinRGB(float T)\n"
    "{\n"
    "    float t = T / 100.0;\n"
    "    float r = t <= 66.0 ? 255.0 : 329.698727446 * pow(t - 60.0, -0.1332047592);\n"
    "    float g = t <= 66.0 ? 99.4708025861 * log(t) - 161.1195681661 : 288.1221695283 * pow(t - 60.0, -0.0755148492);\n"
    "    float b = t >= 66.0 ? 255.0 : (t <= 19.0 ? 0.0 : 138.5177312231 * log(t - 10.0) - 305.0447927307);\n"
    "    return clamp(vec3(r, g, b), 1.0, 255.0) / 255.0;\n"
    "}\n"
    "\n"
    "void lr_main()\n"
    "{\n"
    "    gl_Position = MVPMatrix * VertexCoord;\n"
    "    vTexCoord = TexCoord;\n"
    "    // keep white equally bright and only shift its tint\n"
    "    vec3 c = pow(kelvinRGB(LR_WHITE) / kelvinRGB(6500.0), vec3(2.2));\n"
    "    vWhite = c / dot(c, vec3(0.2126, 0.7152, 0.0722));\n"
    "    Timing T = getTiming(LR_OriginalSize.xy, LR_FrameCount);\n"
    "    vTiming = vec4(T.scan, T.pal, T.interlace, T.scale);\n"
    "    vPhos = phosphorSet(T);\n"
    "    vShare = activeShare(T, LR_OriginalSize.xy);\n"
    "    vAmiga = isAmiga(T) ? 1.0 : 0.0;\n"
    "    // the white is set on the phosphor drives so that it ends up at the chosen colour temperature\n"
    "    if (vPhos > 1.5) vWhite = inverse(phosphorMatrix(vPhos)) * vWhite;\n"
    "}\n"
    "\n"
    "flat out vec4 lrParams[8];\n"
    "\n"
    "void main()\n"
    "{\n"
    "    // the adjustable values: blue channel of the first pass's first row\n"
    "    LR_NORM = texelFetch(LR_Signal, ivec2(0, 0), 0).b;\n"
    "    LR_STEADY = texelFetch(LR_Signal, ivec2(5, 0), 0).b;\n"
    "    LR_CONV = texelFetch(LR_Signal, ivec2(7, 0), 0).b;\n"
    "    LR_MASK_TYPE = texelFetch(LR_Signal, ivec2(8, 0), 0).b;\n"
    "    LR_MASK_STR = texelFetch(LR_Signal, ivec2(9, 0), 0).b;\n"
    "    LR_WHITE = texelFetch(LR_Signal, ivec2(10, 0), 0).b;\n"
    "    LR_PHOS = texelFetch(LR_Signal, ivec2(11, 0), 0).b;\n"
    "    LR_CURV_X = texelFetch(LR_Signal, ivec2(12, 0), 0).b;\n"
    "    LR_CURV_Y = texelFetch(LR_Signal, ivec2(13, 0), 0).b;\n"
    "    LR_BEND = texelFetch(LR_Signal, ivec2(14, 0), 0).b;\n"
    "    LR_CORNER = texelFetch(LR_Signal, ivec2(15, 0), 0).b;\n"
    "    LR_GLOW = texelFetch(LR_Signal, ivec2(16, 0), 0).b;\n"
    "    LR_VIGNETTE = texelFetch(LR_Signal, ivec2(18, 0), 0).b;\n"
    "    LR_OVERSCAN = texelFetch(LR_Signal, ivec2(19, 0), 0).b;\n"
    "    LR_OVERSCAN_V = texelFetch(LR_Signal, ivec2(20, 0), 0).b;\n"
    "    LR_LIN_X = texelFetch(LR_Signal, ivec2(21, 0), 0).b;\n"
    "    LR_LIN_Y = texelFetch(LR_Signal, ivec2(22, 0), 0).b;\n"
    "    LR_AMBIENT = texelFetch(LR_Signal, ivec2(23, 0), 0).b;\n"
    "    LR_MON_SIZE = texelFetch(LR_Signal, ivec2(24, 0), 0).b;\n"
    "    LR_MON_PITCH = texelFetch(LR_Signal, ivec2(25, 0), 0).b;\n"
    "    LR_MON_SPOT_LO = texelFetch(LR_Signal, ivec2(26, 0), 0).b;\n"
    "    LR_MON_SPOT_HI = texelFetch(LR_Signal, ivec2(27, 0), 0).b;\n"
    "    LR_MON_CORNER = texelFetch(LR_Signal, ivec2(28, 0), 0).b;\n"
    "    LR_SCREEN_H = texelFetch(LR_Signal, ivec2(29, 0), 0).b;\n"
    "    LR_SCREEN_UNIT = texelFetch(LR_Signal, ivec2(30, 0), 0).b;\n"
    "    LR_BACKDROP = texelFetch(LR_Signal, ivec2(31, 0), 0).b;\n"
    "    LR_ROOM = texelFetch(LR_Signal, ivec2(32, 0), 0).b;\n"
    "    LR_SPILL = texelFetch(LR_Signal, ivec2(33, 0), 0).b;\n"
    "    LR_SCENE_SPEED = texelFetch(LR_Signal, ivec2(34, 0), 0).b;\n"
    "    lrParams[0] = vec4(LR_NORM, LR_STEADY, LR_CONV, LR_MASK_TYPE);\n"
    "    lrParams[1] = vec4(LR_MASK_STR, LR_WHITE, LR_PHOS, LR_CURV_X);\n"
    "    lrParams[2] = vec4(LR_CURV_Y, LR_BEND, LR_CORNER, LR_GLOW);\n"
    "    lrParams[3] = vec4(LR_VIGNETTE, LR_OVERSCAN, LR_OVERSCAN_V, LR_LIN_X);\n"
    "    lrParams[4] = vec4(LR_LIN_Y, LR_AMBIENT, LR_MON_SIZE, LR_MON_PITCH);\n"
    "    lrParams[5] = vec4(LR_MON_SPOT_LO, LR_MON_SPOT_HI, LR_MON_CORNER, LR_SCREEN_H);\n"
    "    lrParams[6] = vec4(LR_SCREEN_UNIT, LR_BACKDROP, LR_ROOM, LR_SPILL);\n"
    "    lrParams[7] = vec4(LR_SCENE_SPEED, 0.0, 0.0, 0.0);\n"
    "    lr_main();\n"
    "}\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "in vec2 vTexCoord;\n"
    "flat in vec3 vWhite;\n"
    "flat in vec4 vTiming;\n"
    "flat in float vPhos;\n"
    "flat in float vShare;\n"
    "flat in float vAmiga;\n"
    "out vec4 FragColor;\n"
    "uniform sampler2D LR_Beam;\n"
    "uniform sampler2D LR_Glow;\n"
    "uniform sampler2D LR_Fields;\n"
    "\n"
    "// Beam of source line i at position x along the line (from the beam pass):\n"
    "// rgb = square root of its linear brightness, a = which spot made it (PC monitor);\n"
    "// 0 outside the picture\n"
    "vec4 beamAt(float i, float x, float lines)\n"
    "{\n"
    "    if (i < 0.0 || i >= lines) return vec4(0.0);\n"
    "    vec2 bs = vec2(textureSize(LR_Beam, 0));\n"
    "    return textureLod(LR_Beam, vec2(x + 0.5 / bs.x, (i + 0.5) / bs.y), 0.0);\n"
    "}\n"
    "\n"
    "// TV show: the beam row at position p. A whole number is that row; between two console lines\n"
    "// (a standards converter scaling NTSC to PAL or back, when the preset has no show-lines pass)\n"
    "// the converter's vertical filter interpolates them, here a Catmull-Rom cubic over four lines.\n"
    "vec4 showBeam(float p, float x, float lines)\n"
    "{\n"
    "    float g = floor(p), f = p - g;\n"
    "    if (f < 1e-3) return beamAt(g, x, lines);\n"
    "    vec4 a = beamAt(g - 1.0, x, lines), b = beamAt(g, x, lines);\n"
    "    vec4 c = beamAt(g + 1.0, x, lines), d = beamAt(g + 2.0, x, lines);\n"
    "    vec4 r = b + 0.5 * f * (c - a) + f * f * (a - 2.5 * b + 2.0 * c - 0.5 * d)\n"
    "           + f * f * f * (1.5 * (b - c) + 0.5 * (d - a));\n"
    "    return max(r, 0.0);\n"
    "}\n"
    "\n"
    "// Rear-projection screen: lenticular sheet with thin black stripes, no RGB pattern\n"
    "float lenticular(float x)\n"
    "{\n"
    "    float f = fract(x);\n"
    "    return smoothstep(0.0, 0.18, f) * smoothstep(1.0, 0.82, f);\n"
    "}\n"
    "\n"
    "// Shadow mask: staggered round dots\n"
    "vec3 shadowDots(vec2 mp)\n"
    "{\n"
    "    float s = mp.x * 3.0;\n"
    "    float ci = floor(s), fx = fract(s);\n"
    "    float fy = fract(mp.y * 1.732 + mod(ci, 2.0) * 0.5);\n"
    "    float dt = smoothstep(0.52, 0.30, length(vec2(fx - 0.5, fy - 0.5)));\n"
    "    float chn = mod(ci, 3.0);\n"
    "    return vec3(chn < 0.5 ? dt : 0.0, (chn > 0.5 && chn < 1.5) ? dt : 0.0, chn > 1.5 ? dt : 0.0);\n"
    "}\n"
    "\n"
    "// Aperture grille / slot mask: vertical RGB stripes\n"
    "vec3 stripes(float x)\n"
    "{\n"
    "    float s = x * 3.0;\n"
    "    vec3 m;\n"
    "    for (int ch = 0; ch < 3; ch++)\n"
    "    {\n"
    "        float d = abs(fract((s - (float(ch) + 0.5)) / 3.0 + 0.5) - 0.5) * 3.0;\n"
    "        m[ch] = smoothstep(0.75, 0.35, d);\n"
    "    }\n"
    "    return m;\n"
    "}\n"
    "\n"
    "// Slot mask: horizontal breaks, staggered per triad column\n"
    "float slotGate(float x, float y)\n"
    "{\n"
    "    float yy = fract(y * 0.5 + mod(floor(x), 2.0) * 0.5);\n"
    "    return smoothstep(0.0, 0.12, yy) * smoothstep(1.0, 0.88, yy);\n"
    "}\n"
    "\n"
    "// Mask averaged over 2x2 points (a and b are the corners) to keep moire down.\n"
    "// Parts that only depend on x are evaluated once per column.\n"
    "vec3 maskAvg(vec2 a, vec2 b, float mt)\n"
    "{\n"
    "    if (mt > 3.5) return vec3(0.5 * (lenticular(a.x) + lenticular(b.x)));\n"
    "    if (mt > 2.5) return 0.25 * (shadowDots(a) + shadowDots(vec2(b.x, a.y)) + shadowDots(vec2(a.x, b.y)) + shadowDots(b));\n"
    "    vec3 ma = stripes(a.x), mb = stripes(b.x);\n"
    "    if (mt > 1.5)\n"
    "        return 0.25 * (ma * (slotGate(a.x, a.y) + slotGate(a.x, b.y)) + mb * (slotGate(b.x, a.y) + slotGate(b.x, b.y)));\n"
    "    return 0.5 * (ma + mb);\n"
    "}\n"
    "\n"
    "vec3 shoulder(vec3 x)\n"
    "{\n"
    "    const float k = 0.8;\n"
    "    vec3 e = max(x - k, 0.0);\n"
    "    return min(x, vec3(k)) + (1.0 - k) * (1.0 - exp(-e / (1.0 - k)));\n"
    "}\n"
    "\n"
    "// Signed distance from p to a box of half size b with corners of radius r (negative inside)\n"
    "float roundBox(vec2 p, vec2 b, float r)\n"
    "{\n"
    "    vec2 q = abs(p) - b + r;\n"
    "    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;\n"
    "}\n"
    "\n"
    "// Direction away from that box at p\n"
    "vec2 boxOut(vec2 p, vec2 b, float r)\n"
    "{\n"
    "    return sign(p) * normalize(max(abs(p) - b + r, 1e-3));\n"
    "}\n"
    "\n"
    "// A surface turned by phi radians from facing the viewer, toward dir (z toward the viewer)\n"
    "vec3 tilt(vec2 dir, float phi) { return vec3(dir * sin(phi), cos(phi)); }\n"
    "\n"
    "// Plastic lit by the room. Diffuse: light from above, a little from the right and in front (as in\n"
    "// the photos of the real monitors), plus some from the rest of the room; 1 on a surface facing\n"
    "// the viewer. Sheen of a satin finish (gloss 0.5: 4% reflection head-on, more at grazing angles;\n"
    "// 1 is twice that and sharper), seen from 60 cm in front of the tube: the room reflected, blurred\n"
    "// (a light ceiling above, a darker desk and floor below, so faces and edges turned up look\n"
    "// lighter), and the ceiling lamp, 1.2 m above the monitor, in front of it and a little to the\n"
    "// right, as a soft highlight. P: position in mm (y up, z toward the viewer), n: which way the\n"
    "// surface faces, occ: how much of the room's light reaches it.\n"
    "vec3 plastic(vec3 albedo, vec3 n, vec3 P, vec3 light, float occ, float gloss)\n"
    "{\n"
    "    const vec3 L = vec3(0.3, 0.45, 0.84);\n"
    "    float diffuse = 0.45 + 0.55 * max(dot(n, L), 0.0) / 0.84;\n"
    "    vec3 col = albedo * diffuse;\n"
    "    if (gloss > 0.0)\n"
    "    {\n"
    "        vec3 v = normalize(vec3(0.0, 0.0, 600.0) - P);\n"
    "        vec3 r = reflect(-v, n);\n"
    "        float F = 0.04 + 0.96 * pow(1.0 - max(dot(v, n), 0.0), 5.0);\n"
    "        float room = 0.45 * (0.4 + 2.3 * smoothstep(-0.3, 0.7, r.y));\n"
    "        vec3 l = normalize(vec3(250.0, 1200.0, 900.0) - P);\n"
    "        float s = mix(12.0, 80.0, gloss);\n"
    "        float lamp = 0.55 / 0.84 * max(dot(n, l), 0.0) * (s + 8.0) / 8.0 * pow(max(dot(n, normalize(l + v)), 0.0), s);\n"
    "        col += 2.0 * gloss * F * (room + lamp);\n"
    "    }\n"
    "    return light * occ * col;\n"
    "}\n"
    "\n"
    "// Signed distance to a pill (a horizontal capsule): straight part 2h long, radius r\n"
    "float pill(vec2 q, float h, float r)\n"
    "{\n"
    "    q.x = max(abs(q.x) - h, 0.0);\n"
    "    return length(q) - r;\n"
    "}\n"
    "\n"
    "// Smooth value noise, 0..1\n"
    "float valueNoise(vec2 p)\n"
    "{\n"
    "    vec2 i = floor(p), f = fract(p);\n"
    "    f = f * f * (3.0 - 2.0 * f);\n"
    "    return mix(mix(hash13(vec3(i, 5.0)), hash13(vec3(i + vec2(1.0, 0.0), 5.0)), f.x),\n"
    "               mix(hash13(vec3(i + vec2(0.0, 1.0), 5.0)), hash13(vec3(i + 1.0, 5.0)), f.x), f.y);\n"
    "}\n"
    "\n"
    "// Smooth value noise along a line, 0..1\n"
    "float noise1(float x)\n"
    "{\n"
    "    float i = floor(x), f = fract(x);\n"
    "    return mix(hash13(vec3(i, 5.0, 1.0)), hash13(vec3(i + 1.0, 5.0, 1.0)), f * f * (3.0 - 2.0 * f));\n"
    "}\n"
    "\n"
    "// Fractal noise: three octaves of value noise, 0..1\n"
    "float fbm3(vec2 p)\n"
    "{\n"
    "    return (4.0 * valueNoise(p) + 2.0 * valueNoise(p * 2.03 + 17.0) + valueNoise(p * 4.12 + 51.5)) / 7.0;\n"
    "}\n"
    "\n"
    "// Space (Around the tube 2): floating through space. Far away the Milky Way crosses the sky, with\n"
    "// dark lanes of dust, a few clouds of glowing gas, bright stars with spikes of light and now and\n"
    "// then a small galaxy; nearer stars slowly come closer and drift past. Decoration, not a\n"
    "// simulation. s: screen position from the centre in screen heights, t: seconds, pix: one screen\n"
    "// pixel in screen heights.\n"
    "vec3 space(vec2 s, float t, float pix)\n"
    "{\n"
    "    vec2 drift = vec2(sin(t * 0.013), sin(t * 0.0091 + 1.3)) * 0.08;\n"
    "    vec2 b = s + 0.2 * drift + vec2(0.003 * t, 0.0);          // the far sky, moving slowly\n"
    "    vec3 sum = vec3(0.0);\n"
    "\n"
    "    // the Milky Way: a band of light across the sky, warmer and brighter along its middle, in\n"
    "    // clouds of stars, with dark lanes of dust\n"
    "    float along = dot(b, vec2(0.92, 0.39));\n"
    "    float across = dot(b, vec2(-0.39, 0.92)) + 0.05 * sin(along * 2.3 + 1.0) - 0.04;\n"
    "    float mw = exp(-0.5 * across * across / 0.02), fine = 0.0;\n"
    "    if (mw > 0.05)\n"
    "    {\n"
    "        float cl = 0.65 * valueNoise(b * 2.4 + 3.0) + 0.35 * valueNoise(b * 5.1 + 8.0);\n"
    "        fine = (2.0 * valueNoise(b * 9.0 + 5.0) + valueNoise(b * 18.3 + 22.0)) / 3.0;\n"
    "        float core = exp(-0.5 * across * across / 0.004);\n"
    "        float ac = across + 0.012, lane = 0.0;\n"
    "        if (abs(ac) < 0.13)                                  // dark lanes of dust, near its middle\n"
    "            lane = smoothstep(0.5, 0.66, fbm3(vec2(along * 3.0, across * 10.0) + 11.0 + 0.4 * fine)) * exp(-0.5 * ac * ac / 0.0025);\n"
    "        float g = mw * smoothstep(0.05, 0.15, mw) * (0.15 + 0.85 * cl * cl) * (0.5 + fine * fine) * (1.0 - 0.85 * lane);\n"
    "        sum += mix(vec3(0.6, 0.7, 1.0), vec3(1.0, 0.94, 0.86), core) * 0.036 * g * (1.0 + core);\n"
    "        fine *= 1.0 - lane;\n"
    "    }\n"
    "\n"
    "    // clouds of glowing gas, red and blue-green, in a few places, folded into filaments\n"
    "    float nm = valueNoise(b * 0.8 + 31.0);\n"
    "    if (nm > 0.62)\n"
    "    {\n"
    "        float w = (2.0 * valueNoise(b * 1.9 + 7.0) + valueNoise(b * 3.86 + 24.0)) / 3.0;\n"
    "        float f = smoothstep(0.4, 0.75, fbm3(b * 3.6 + 2.5 * w + 19.0));\n"
    "        float fil = 1.0 - abs(2.0 * fbm3(b * 8.0 + 3.0 * w + 23.0) - 1.0);\n"
    "        float f2 = fil * fil, f8 = f2 * f2;\n"
    "        f8 *= f8;\n"
    "        vec3 neb = mix(vec3(0.9, 0.12, 0.35), vec3(0.15, 0.55, 0.75), smoothstep(0.4, 0.6, w));\n"
    "        sum += neb * smoothstep(0.62, 0.88, nm) * f * (0.03 * f + 0.06 * f8 * f2);\n"
    "    }\n"
    "\n"
    "    // many faint stars, most of them in the Milky Way, and the dust of even fainter ones there\n"
    "    for (int i = 0; i < 2; i++)\n"
    "    {\n"
    "        float C = i == 0 ? 0.0055 : 0.0026;\n"
    "        vec2 q = b / C + float(i) * 0.37, id = floor(q);\n"
    "        float h = hash13(vec3(id, 41.0 + float(i)));\n"
    "        if (h < (i == 0 ? 0.1 + 0.4 * mw : 0.9 * mw * fine * fine))\n"
    "        {\n"
    "            vec2 at = 0.15 + 0.7 * vec2(hash13(vec3(id, 42.0)), hash13(vec3(id, 43.0)));\n"
    "            float d = length(fract(q) - at) * C;\n"
    "            float r0 = 0.0002, r = max(r0, 0.55 * pix);\n"
    "            float hue = fract(h * 91.0);\n"
    "            vec3 tint = hue < 0.5 ? vec3(0.8, 0.88, 1.0) : hue < 0.8 ? vec3(1.0) : vec3(1.0, 0.85, 0.65);\n"
    "            float u = fract(h * 17.0), u3 = u * u * u;\n"
    "            float br = i == 0 ? 0.04 + 0.6 * u3 * u3 : 0.025 + 0.04 * u;\n"
    "            sum += tint * br * (r0 * r0) / (r * r) * exp(-0.5 * d * d / (r * r));\n"
    "        }\n"
    "    }\n"
    "\n"
    "    // far away: bright stars with four spikes of light, and now and then a small galaxy\n"
    "    vec2 q = b / 0.24 + 7.0, id = floor(q);\n"
    "    float h = hash13(vec3(id, 71.0));\n"
    "    vec2 d = (fract(q) - 0.3 - 0.4 * vec2(hash13(vec3(id, 72.0)), hash13(vec3(id, 73.0)))) * 0.24;\n"
    "    if (h > 0.6)\n"
    "    {\n"
    "        float r = max(0.0004, 0.6 * pix), br = 0.5 + 1.5 * fract(h * 29.0);\n"
    "        vec2 e = mat2(0.94, 0.34, -0.34, 0.94) * d;           // the spikes, a little turned\n"
    "        float L = 0.004 + 0.01 * fract(h * 29.0);\n"
    "        float spikes = (exp(-abs(e.x) / L - 0.5 * e.y * e.y / (r * r)) + exp(-abs(e.y) / L - 0.5 * e.x * e.x / (r * r)))\n"
    "                     * smoothstep(0.07, 0.035, length(d));            // fading out inside the star's cell\n"
    "        vec3 tint = fract(h * 13.0) < 0.6 ? vec3(0.85, 0.92, 1.0) : vec3(1.0, 0.88, 0.7);\n"
    "        float dd = dot(d, d);\n"
    "        sum += tint * br * (0.6 * exp(-0.5 * dd / (r * r)) + 0.025 * exp(-sqrt(dd) / 0.004) + 0.12 * spikes);\n"
    "    }\n"
    "    else if (h < 0.07)\n"
    "    {\n"
    "        float an = h * 300.0, ca = cos(an), sa = sin(an);\n"
    "        vec2 g = mat2(ca, sa, -sa, ca) * d;\n"
    "        g.y /= 0.3 + 0.5 * fract(h * 37.0);                   // seen at a slant\n"
    "        float R = 0.026 + 0.02 * fract(h * 53.0), r = length(g) / R;\n"
    "        float arms = 0.5 + 0.5 * cos(2.0 * atan(g.y, g.x) - 6.0 * log(r + 0.06));\n"
    "        float disk = exp(-3.2 * r) * (0.3 + 0.7 * arms * smoothstep(0.05, 0.35, r));\n"
    "        sum += vec3(0.55, 0.65, 1.0) * 0.06 * disk + vec3(1.0, 0.85, 0.65) * 0.3 * exp(-r * r / 0.01);\n"
    "    }\n"
    "\n"
    "    // nearer stars, in layers that slowly come closer\n"
    "    for (int i = 0; i < 4; i++)\n"
    "    {\n"
    "        float k = t * 0.008 + float(i) * 0.25;\n"
    "        float z = fract(k);                                   // 0 far away, 1 close\n"
    "        float seed = floor(k) * 4.0 + float(i);\n"
    "        float cell = 0.016 * exp2(3.0 * z);                   // stars spread apart as they come closer\n"
    "        q = (s + drift * (0.15 + z)) / cell + 97.0 * fract(seed * vec2(0.6180340, 0.4142136));\n"
    "        id = floor(q);\n"
    "        h = hash13(vec3(id, seed + 11.0));\n"
    "        if (h < 0.44) continue;\n"
    "        vec2 at = 0.2 + 0.6 * vec2(hash13(vec3(id, seed + 3.0)), hash13(vec3(id, seed + 7.0)));\n"
    "        float dn = length(fract(q) - at) * cell;              // in screen heights\n"
    "        float r0 = mix(0.00026, 0.0007, z) * (0.7 + 0.6 * fract(h * 13.0));\n"
    "        float r = max(r0, 0.6 * pix);                         // at least about a pixel, same light\n"
    "        float u = fract(h * 37.0);\n"
    "        float br = mix(0.15, 1.5, z * z) * (0.12 + 0.88 * u * u * u) * (r0 * r0) / (r * r);\n"
    "        br *= smoothstep(0.0, 0.3, z) * (1.0 - smoothstep(0.85, 1.0, z));\n"
    "        br *= 1.0 + 0.35 * (1.0 - z) * sin(t * (1.5 + 3.0 * fract(h * 53.0)) + h * 100.0);\n"
    "        float hue = fract(h * 91.0);\n"
    "        vec3 tint = hue < 0.5 ? vec3(0.78, 0.86, 1.0) : hue < 0.85 ? vec3(1.0) : vec3(1.0, 0.86, 0.68);\n"
    "        sum += br * tint * (exp(-0.5 * dn * dn / (r * r)) + 0.07 * exp(-0.5 * dn * dn / (16.0 * r * r)));\n"
    "    }\n"
    "    return sum;\n"
    "}\n"
    "\n"
    "// A palm tree's silhouette, < 0 inside (roughly the distance, in screen heights). p: from the foot\n"
    "// of the trunk, y up; H: its height; lean: how far the top leans to the side; sway: the crown's\n"
    "// sway. Each frond is a rib that arches out and droops, with leaflets hanging from it.\n"
    "float palmTree(vec2 p, float H, float lean, float sway)\n"
    "{\n"
    "    float yy = clamp(p.y / H, 0.0, 1.0), top = lean + sway;\n"
    "    float d = abs(p.x - top * yy * yy) - mix(0.0095, 0.0055, yy) * (1.0 + 0.12 * abs(sin(p.y * 260.0)));\n"
    "    d = max(d, max(-p.y, p.y - H));                           // the trunk, bending, with rings\n"
    "    vec2 q = p - vec2(top, H);                                // from the crown\n"
    "    if (dot(q, q) > 0.12) return d;\n"
    "    float sa = 3.0 * sway;                                    // the crown turns a little as it sways\n"
    "    q = mat2(cos(sa), sin(sa), -sin(sa), cos(sa)) * q;\n"
    "    d = min(d, length(q) - 0.01);\n"
    "    d = min(d, min(length(q - vec2(-0.008, -0.012)), length(q - vec2(0.007, -0.013))) - 0.0055);   // coconuts\n"
    "    for (int i = 0; i < 10; i++)\n"
    "    {\n"
    "        float fi = float(i);\n"
    "        float a = -0.5 + fi * 0.46 + 0.12 * sin(fi * 7.1);\n"
    "        vec2 e = vec2(cos(a), sin(a));\n"
    "        float L = 0.07 + 0.16 * abs(e.x) + 0.03 * fract(fi * 0.618);\n"
    "        float u = dot(q, e), uu = u / L;\n"
    "        if (uu <= 0.0 || uu >= 1.0) continue;\n"
    "        float sx = e.x < 0.0 ? -1.0 : 1.0;\n"
    "        float vb = (dot(q, vec2(-e.y, e.x)) + e.x * (0.25 + 0.4 * abs(e.x)) * L * uu * uu) * sx;   // across, > 0 above the rib\n"
    "        float rib = abs(vb) - 0.0028 * (1.0 - uu * uu);\n"
    "        float lf = (vb < 0.0 ? 0.042 : 0.013) * sqrt(4.0 * uu * (1.0 - uu));   // leaflets, hanging below\n"
    "        float k = abs(vb) / max(lf, 1e-4);\n"
    "        float ph = abs(fract((u + 1.4 * abs(vb)) / 0.0105) - 0.5);   // from the middle of the nearest leaflet\n"
    "        float leaf = max(abs(vb) - lf, (ph - 0.3 * (1.0 - 0.7 * k)) * 0.0105);\n"
    "        d = min(d, min(rib, leaf));\n"
    "    }\n"
    "    return d;\n"
    "}\n"
    "\n"
    "// Synthwave (Around the tube 3): a big striped sun behind the monitor, two ranges of mountains\n"
    "// (the near one with neon lines along its slopes), palm trees at the sides, a neon grid floor that\n"
    "// runs toward the viewer, a purple sky full of stars. Decoration, not a simulation. s: screen\n"
    "// position from the centre in screen heights (y up), hs: half the screen's size, t: seconds,\n"
    "// pix: one screen pixel in screen heights.\n"
    "vec3 synthwave(vec2 s, vec2 hs, float t, float pix)\n"
    "{\n"
    "    const float hz = -0.12;                                       // the horizon\n"
    "    float y = s.y - hz;\n"
    "    vec3 col;\n"
    "    if (y > 0.0)\n"
    "    {\n"
    "        // the sky: deep indigo above, magenta at the horizon\n"
    "        col = mix(vec3(0.16, 0.008, 0.14), vec3(0.006, 0.0015, 0.025), smoothstep(0.0, 0.5, y));\n"
    "        // stars, more of them high up, twinkling\n"
    "        for (int i = 0; i < 2; i++)\n"
    "        {\n"
    "            float C = i == 0 ? 0.014 : 0.0075;\n"
    "            vec2 q = s / C + 0.5 * float(i), id = floor(q);\n"
    "            float h = hash13(vec3(id, 91.0 + 3.0 * float(i)));\n"
    "            if (h > (i == 0 ? 0.9 : 0.86))\n"
    "            {\n"
    "                vec2 at = 0.2 + 0.6 * vec2(hash13(vec3(id, 92.0)), hash13(vec3(id, 93.0)));\n"
    "                float d = length(fract(q) - at) * C, r = max(0.0003, 0.6 * pix);\n"
    "                float br = (i == 0 ? 0.3 : 0.1) * (0.7 + 0.3 * sin(t * (1.0 + 2.0 * fract(h * 41.0)) + h * 60.0));\n"
    "                col += (fract(h * 23.0) < 0.3 ? vec3(1.0, 0.7, 0.9) : vec3(0.85, 0.8, 1.0)) * br\n"
    "                     * exp(-0.5 * d * d / (r * r)) * 9e-8 / (r * r) * smoothstep(0.08, 0.45, y);\n"
    "            }\n"
    "        }\n"
    "        // the sun: yellow at the top, orange, then hot pink toward the horizon, cut by bands that\n"
    "        // thicken toward the horizon and slowly move down; a glow around it\n"
    "        vec2 sp = s - vec2(0.0, hz + 0.10);\n"
    "        float R = 0.56, sd = length(sp) - R, v = sp.y / R;\n"
    "        vec3 sun = mix(vec3(1.0, 0.04, 0.38), vec3(1.0, 0.32, 0.07), smoothstep(-0.3, 0.35, v));\n"
    "        sun = mix(sun, vec3(1.0, 0.78, 0.14), smoothstep(0.35, 0.95, v)) * 0.55;\n"
    "        float band = 1.0;\n"
    "        if (v < 0.45)\n"
    "        {\n"
    "            float k = fract(v * 7.0 + t * 0.12), w = max(0.01, 7.0 * pix / R);\n"
    "            float gap = mix(0.06, 0.55, smoothstep(0.45, -0.4, v));\n"
    "            band = smoothstep(gap - w, gap + w, k) * smoothstep(1.0, 1.0 - w, k);\n"
    "        }\n"
    "        float disk = 1.0 - smoothstep(-pix, pix, sd);\n"
    "        col = mix(col, sun, disk * band);\n"
    "        col += sun * (1.0 - disk) * (0.35 * exp(-max(sd, 0.0) / 0.05) + 0.1 * exp(-max(sd, 0.0) / 0.25));\n"
    "        // two ranges of mountains, cut in flat faces like the 3D graphics of the time: the side of a\n"
    "        // peak that faces the sun is lighter. The far range is dark violet with a ridge the sun\n"
    "        // behind it lights; the near one nearly black, with a neon ridge and neon lines along its\n"
    "        // slopes. Both are lower toward the middle, where the sun sets (the monitor hides it anyway).\n"
    "        float side = abs(s.x);\n"
    "        for (int r = 0; r < 2; r++)\n"
    "        {\n"
    "            float W = r == 0 ? 0.075 : 0.05;\n"
    "            float xw = s.x + 0.25 * W * sin(s.x * 9.0 / W * 0.1 + float(r));          // uneven spacing\n"
    "            float c = floor(xw / W), f = xw / W - c;\n"
    "            float h0 = hash13(vec3(c, float(r), 31.0)), h1 = hash13(vec3(c + 1.0, float(r), 31.0));\n"
    "            bool peak0 = mod(c, 2.0) < 0.5;                                          // peaks and valleys take turns\n"
    "            float hp = r == 0 ? 0.05 + 0.12 * (peak0 ? h0 : h1) : 0.02 + 0.05 * (peak0 ? h0 : h1);\n"
    "            float hv = (r == 0 ? 0.015 : 0.006) + 0.35 * hp * (peak0 ? h1 : h0);\n"
    "            float a0 = peak0 ? hp : hv, a1 = peak0 ? hv : hp;\n"
    "            float lowMid = smoothstep(r == 0 ? 0.06 : 0.15, r == 0 ? 0.5 : 0.45, side);\n"
    "            float mh = mix(a0, a1, f) * lowMid;                                       // the ridge here\n"
    "            float md = y - mh;\n"
    "            // which face: the crease runs from the peak down and a little sideways\n"
    "            float px = peak0 ? c : c + 1.0;\n"
    "            float facing = sign((xw / W - px - 0.35 * (mh - y) / (W * max(hp * lowMid, 1e-3))) * sign(s.x)) ;\n"
    "            vec3 face = r == 0 ? (facing < 0.0 ? vec3(0.085, 0.016, 0.115) : vec3(0.035, 0.007, 0.065))\n"
    "                               : (facing < 0.0 ? vec3(0.02, 0.004, 0.04) : vec3(0.008, 0.001, 0.02));\n"
    "            if (r == 1 && md < 0.0)\n"
    "                for (int i = 1; i < 4; i++)\n"
    "                {\n"
    "                    float k = float(i) * 0.25, dl = abs(y - k * mh) / max(0.0015, pix);\n"
    "                    face += vec3(1.0, 0.1, 0.7) * 0.05 * k * exp(-dl) * smoothstep(0.01, 0.04, mh);\n"
    "                }\n"
    "            col = mix(col, face, 1.0 - smoothstep(-pix, pix, md));\n"
    "            vec3 rim = r == 0 ? mix(vec3(1.0, 0.3, 0.3), vec3(0.7, 0.1, 0.8), smoothstep(0.2, 0.7, side)) * 0.12\n"
    "                              : vec3(1.0, 0.1, 0.7) * 0.2;\n"
    "            col += rim * exp(-abs(md) / max(0.002, pix)) * smoothstep(0.002, 0.004, mh);\n"
    "        }\n"
    "    }\n"
    "    else\n"
    "    {\n"
    "        // the floor: a neon grid in perspective, running toward the viewer, fading into the haze\n"
    "        float z = 1.0 / max(-y, 1e-4);\n"
    "        vec2 g = vec2(s.x * z, z + 0.6 * t) * 1.5;               // grid units\n"
    "        vec2 gd = abs(fract(g + 0.5) - 0.5);                     // to the nearest line\n"
    "        vec2 gw = vec2(z + abs(s.x) * z * z, z * z) * 1.5 * pix; // one pixel in grid units\n"
    "        vec2 line = (1.0 - smoothstep(0.03 - gw, 0.03 + gw, gd)) * (1.0 - smoothstep(0.15, 0.5, gw));\n"
    "        vec2 glow = exp(-gd / (0.12 + gw)) * (1.0 - smoothstep(0.15, 0.5, gw));\n"
    "        float lines = max(max(line.x, line.y), 0.3 * max(glow.x, glow.y));\n"
    "        col = vec3(0.006, 0.0, 0.014) + vec3(1.0, 0.06, 0.65) * (0.55 * lines * exp(-0.08 * z));\n"
    "    }\n"
    "    // haze and a bright line at the horizon\n"
    "    col += vec3(0.25, 0.015, 0.2) * exp(-abs(y) / 0.04) + vec3(1.0, 0.1, 0.6) * 0.25 * exp(-abs(y) / max(0.002, pix));\n"
    "    // palm trees at both sides, black against the sky, with a little light from the sun on their\n"
    "    // edges; their crowns sway a little\n"
    "    float px = hs.x - 0.15;\n"
    "    if (abs(s.x) > px - 0.2 && s.y < 0.38)\n"
    "    {\n"
    "        float sg = sign(s.x);\n"
    "        vec2 pp = vec2(sg * s.x - px, s.y + 0.56);                  // the feet, below the bottom of the screen\n"
    "        float pd = palmTree(pp, 0.64, 0.08, 0.004 * sin(t * 0.6 + sg));\n"
    "        pd = min(pd, palmTree(pp - vec2(0.12, 0.0), 0.51, 0.1, 0.004 * sin(t * 0.5 + 2.0 + sg)));\n"
    "        col = mix(col, vec3(0.004, 0.001, 0.01), 1.0 - smoothstep(-pix, pix, pd));\n"
    "        col += vec3(1.0, 0.15, 0.55) * 0.08 * exp(-abs(pd) / max(0.0015, pix)) * smoothstep(-pix, 0.0, pd);\n"
    "    }\n"
    "    return col;\n"
    "}\n"
    "\n"
    "// ---------------------------------------------------------------------------\n"
    "// More scenes (Around the tube 4-11). Decoration, not a simulation, all drawn here (no pictures).\n"
    "// fc: the screen pixel, counted from the centre (y up). The pixel-art scenes draw their pixels as\n"
    "// squares of a whole number of screen pixels and scroll in whole screen pixels, so they stay sharp.\n"
    "// ---------------------------------------------------------------------------\n"
    "\n"
    "// a colour given as 0-255 sRGB, in linear light like the picture\n"
    "vec3 rgb8(float r, float g, float b) { return pow(vec3(r, g, b) / 255.0, vec3(2.2)); }\n"
    "\n"
    "// screen pixels per pixel of a picture this many lines tall on the screen\n"
    "float pixSize(float lines, float pix) { return max(1.0, floor(1.0 / (lines * pix) + 0.5)); }\n"
    "\n"
    "// the pixel column of a layer that moves left at v screen heights per second; pixels n screen pixels wide\n"
    "float layerX(float fx, float t, float v, float n, float pix) { return floor((fx + floor(t * v / pix)) / n); }\n"
    "\n"
    "// 4x4 ordered dither threshold, 0..15/16\n"
    "float bayer2(vec2 a) { return 2.0 * a.x + 3.0 * a.y - 4.0 * a.x * a.y; }\n"
    "float bayer4(vec2 p) { return (4.0 * bayer2(mod(p, 2.0)) + bayer2(mod(floor(p * 0.5), 2.0))) / 16.0; }\n"
    "\n"
    "// Tiles (4): a 90s desktop wallpaper, a small pattern in the 16 Windows colours repeated over a\n"
    "// 640x480 desktop, scrolling slowly and diagonally. Eight patterns take turns every two minutes,\n"
    "// dissolving into each other. p: the pattern's pixel (y up).\n"
    "bool dith(vec2 p) { return mod(p.x + p.y, 2.0) < 1.0; }\n"
    "// the face of the isometric cubes a pattern pixel is on: 0 top, 1 left, 2 right\n"
    "int cubeFace(vec2 p)\n"
    "{\n"
    "    vec2 q = (p + 0.5) / 16.0;\n"
    "    q.x *= 0.8660254;                                     // 2:1 pixel slopes\n"
    "    float j = floor(q.y / 1.5);\n"
    "    vec2 best = vec2(1e9);\n"
    "    for (int i = 0; i < 2; i++)\n"
    "    {\n"
    "        float jj = j + float(i), sh = 0.5 * mod(jj, 2.0);\n"
    "        vec2 d = q - vec2((floor(q.x / 1.7320508 - sh + 0.5) + sh) * 1.7320508, 1.5 * jj);\n"
    "        if (dot(d, d) < dot(best, best)) best = d;\n"
    "    }\n"
    "    if (best.y * 1.7320508 > abs(best.x)) return 0;\n"
    "    return best.x < 0.0 ? 1 : 2;\n"
    "}\n"
    "vec3 tilePattern(int k, vec2 p)\n"
    "{\n"
    "    const vec3 BLACK = vec3(0.0), WHITE = vec3(1.0);\n"
    "    vec3 SILVER = rgb8(192.0, 192.0, 192.0), GREY = rgb8(128.0, 128.0, 128.0);\n"
    "    vec3 c;\n"
    "    if (k == 0)\n"
    "    {\n"
    "        // cubes: light on top, teal on the left, dark teal on the right; the top's upper edges catch\n"
    "        // the light, the cubes' lower edges are dark\n"
    "        int f = cubeFace(p), fu = cubeFace(p + vec2(0.0, 1.0)), fd = cubeFace(p - vec2(0.0, 1.0));\n"
    "        c = f == 0 ? SILVER : f == 1 ? rgb8(0.0, 128.0, 128.0) : dith(p) ? rgb8(0.0, 128.0, 128.0) : BLACK;\n"
    "        if (f == 0 && fu != 0) c = WHITE;\n"
    "        if (f != 0 && fd == 0) c = BLACK;\n"
    "    }\n"
    "    else if (k == 1)\n"
    "    {\n"
    "        // studs: little pyramids, purple, lit from the top left, with dark lines between them\n"
    "        vec2 f = mod(p, 16.0) - 7.5;\n"
    "        float ax = abs(f.x), ay = abs(f.y);\n"
    "        if (max(ax, ay) > 7.0) c = BLACK;\n"
    "        else if (f.y >= ax) c = dith(p) ? rgb8(255.0, 0.0, 255.0) : rgb8(128.0, 0.0, 128.0);\n"
    "        else if (-f.y >= ax) c = rgb8(0.0, 0.0, 128.0);\n"
    "        else if (f.x < 0.0) c = rgb8(128.0, 0.0, 128.0);\n"
    "        else c = dith(p) ? rgb8(128.0, 0.0, 128.0) : rgb8(0.0, 0.0, 128.0);\n"
    "        if (ax < 1.0 && ay < 1.0) c = rgb8(255.0, 0.0, 255.0);   // the tip catches the light\n"
    "    }\n"
    "    else if (k == 2)\n"
    "    {\n"
    "        // bricks, raised like 90s buttons: light on the top and left edges\n"
    "        float row = floor(p.y / 16.0);\n"
    "        vec2 f = vec2(mod(p.x + 16.0 * mod(row, 2.0), 32.0), p.y - row * 16.0);\n"
    "        c = SILVER;\n"
    "        if (f.x > 30.5 || f.y < 0.5) c = BLACK;\n"
    "        else if (f.x > 29.5 || f.y < 1.5) c = GREY;\n"
    "        else if (f.x < 0.5 || f.y > 14.5) c = WHITE;\n"
    "    }\n"
    "    else if (k == 3)\n"
    "    {\n"
    "        // scales: rows of green scales, each row lying over the top of the row below like roof\n"
    "        // tiles; a dark rim, lighter toward the middle, a shadow under the row above\n"
    "        float yd = -p.y - 0.5, x = p.x + 0.5;\n"
    "        float j0 = floor(yd / 8.0);\n"
    "        c = BLACK;\n"
    "        for (int i = 0; i < 3; i++)\n"
    "        {\n"
    "            float j = j0 - 1.0 + float(i);\n"
    "            float cx = (floor((x - 8.0 * mod(j, 2.0)) / 16.0) + 0.5) * 16.0 + 8.0 * mod(j, 2.0);\n"
    "            vec2 d = vec2(x - cx, yd - 8.0 * j);\n"
    "            float r = length(d);\n"
    "            if (r < 9.0 && d.y > -1.0)\n"
    "            {\n"
    "                c = r > 8.0 ? BLACK : r > 6.5 ? rgb8(0.0, 128.0, 0.0) : r > 4.0 ? (dith(p) ? rgb8(0.0, 255.0, 0.0) : rgb8(0.0, 128.0, 0.0)) : rgb8(0.0, 255.0, 0.0);\n"
    "                if (d.y < 1.5) c = dith(p) ? rgb8(0.0, 128.0, 0.0) : BLACK;   // in the shadow of the row above\n"
    "                break;\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "    else if (k == 4)\n"
    "    {\n"
    "        // pearls on navy, round and shiny, each with a shadow at its lower right\n"
    "        float row = floor(p.y / 16.0);\n"
    "        vec2 f = vec2(mod(p.x + 8.0 * mod(row, 2.0), 16.0), p.y - row * 16.0) - 7.5;\n"
    "        float r = length(f);\n"
    "        if (r < 6.6)\n"
    "        {\n"
    "            vec3 n = vec3(f / 6.6, sqrt(max(1.0 - r * r / 43.56, 0.0)));\n"
    "            float l = dot(n, vec3(-0.45, 0.55, 0.7));\n"
    "            c = l > 0.93 ? WHITE : l > 0.6 ? rgb8(0.0, 255.0, 255.0) : l > 0.38 ? (dith(p) ? rgb8(0.0, 255.0, 255.0) : rgb8(0.0, 128.0, 128.0))\n"
    "              : l > 0.1 ? rgb8(0.0, 128.0, 128.0) : (dith(p) ? rgb8(0.0, 128.0, 128.0) : rgb8(0.0, 0.0, 128.0));\n"
    "        }\n"
    "        else\n"
    "            c = length(f - vec2(1.5, -1.5)) < 6.6 && dith(p) ? BLACK : rgb8(0.0, 0.0, 128.0);\n"
    "    }\n"
    "    else if (k == 5)\n"
    "    {\n"
    "        // weave: a straw mat, strips going across and up in turn, olive with maroon shadows\n"
    "        vec2 b = floor(p / 16.0), f = p - b * 16.0;\n"
    "        float w = mod(mod(b.x + b.y, 2.0) < 0.5 ? f.y : f.x, 4.0);\n"
    "        c = w < 0.5 ? rgb8(128.0, 0.0, 0.0) : rgb8(128.0, 128.0, 0.0);\n"
    "        if (w > 2.5 && dith(p)) c = rgb8(255.0, 255.0, 0.0);\n"
    "    }\n"
    "    else if (k == 6)\n"
    "    {\n"
    "        // honeycomb: blue cells with bevelled edges, lit from the upper left, black between them\n"
    "        vec2 q = (p + 0.5) / 20.0;\n"
    "        const vec2 R = vec2(1.0, 1.7320508);\n"
    "        vec2 a = mod(q, R) - 0.5 * R, b = mod(q - 0.5 * R, R) - 0.5 * R;\n"
    "        vec2 g = dot(a, a) < dot(b, b) ? a : b;\n"
    "        float hd = max(abs(g.x), dot(abs(g), vec2(0.5, 0.8660254)));   // 0.5 at the edge\n"
    "        float lit = dot(normalize(g + 1e-4), vec2(-0.6, 0.8));\n"
    "        if (hd > 0.46) c = BLACK;\n"
    "        else if (hd > 0.36) c = lit > 0.3 ? (dith(p) ? rgb8(0.0, 255.0, 255.0) : rgb8(0.0, 0.0, 255.0))\n"
    "                              : lit < -0.3 ? (dith(p) ? rgb8(0.0, 0.0, 128.0) : BLACK) : rgb8(0.0, 0.0, 128.0);\n"
    "        else c = dith(p) ? rgb8(0.0, 0.0, 255.0) : rgb8(0.0, 0.0, 128.0);\n"
    "    }\n"
    "    else\n"
    "    {\n"
    "        // argyle: maroon and grey diamonds, crossed by thin stitched white lines through their middles\n"
    "        vec2 uv = vec2((p.x + 0.5) / 24.0 + (p.y + 0.5) / 36.0, (p.x + 0.5) / 24.0 - (p.y + 0.5) / 36.0);\n"
    "        c = mod(floor(uv.x) + floor(uv.y), 2.0) < 0.5 ? rgb8(128.0, 0.0, 0.0) : GREY;\n"
    "        vec2 dl = abs(fract(uv) - 0.5) * 14.4;                // about pixels from the lines\n"
    "        if (min(dl.x, dl.y) < 0.55 && mod(p.y, 4.0) < 3.0) c = SILVER;\n"
    "    }\n"
    "    return c;\n"
    "}\n"
    "vec3 tiles(vec2 fc, float t, float pix)\n"
    "{\n"
    "    float n = pixSize(480.0, pix);\n"
    "    vec2 p = floor((fc - floor(t * 0.012 / pix) * vec2(1.0, -1.0)) / n);   // moving right and down\n"
    "    float turn = t / 120.0;\n"
    "    int k = int(mod(floor(turn), 8.0));\n"
    "    vec3 c = tilePattern(k, p);\n"
    "    if (fract(turn) * 120.0 - 118.0 > 2.0 * bayer4(p))                    // the last two seconds: dissolve\n"
    "        c = tilePattern(int(mod(float(k + 1), 8.0)), p);\n"
    "    return 0.4 * c;\n"
    "}\n"
    "vec3 tilesLight(float t)\n"
    "{\n"
    "    float turn = t / 120.0;\n"
    "    int k = int(mod(floor(turn), 8.0)), k1 = int(mod(float(k + 1), 8.0));\n"
    "    vec3 l[8] = vec3[8](vec3(0.86, 0.98, 0.98), vec3(0.95, 0.82, 1.0), vec3(1.0), vec3(0.86, 1.0, 0.86),\n"
    "                        vec3(0.8, 0.92, 1.0), vec3(1.0, 0.97, 0.8), vec3(0.82, 0.88, 1.0), vec3(1.0, 0.86, 0.84));\n"
    "    return mix(l[k], l[k1], clamp(fract(turn) * 60.0 - 59.0, 0.0, 1.0));\n"
    "}\n"
    "\n"
    "// Bouncing lines (5): two four-cornered shapes whose corners bounce off the edges of the screen,\n"
    "// each followed by fading copies of itself that slowly change colour along the trail, on black\n"
    "// (in the spirit of the 90s screensavers). hs: half the screen's size in screen heights.\n"
    "float segDist2(vec2 p, vec2 a, vec2 b)\n"
    "{\n"
    "    vec2 ba = b - a, pa = p - a;\n"
    "    vec2 e = pa - ba * clamp(dot(pa, ba) / max(dot(ba, ba), 1e-8), 0.0, 1.0);\n"
    "    return dot(e, e);\n"
    "}\n"
    "vec4 triWave(vec4 u) { return abs(fract(u) * 2.0 - 1.0) * 2.0 - 1.0; }\n"
    "float triWave(float u) { return abs(fract(u) * 2.0 - 1.0) * 2.0 - 1.0; }\n"
    "vec3 bounceLines(vec2 s, vec2 hs, float t, float pix)\n"
    "{\n"
    "    const float DT = 0.15, SPAN = 1.05;                       // between the copies; the whole trail\n"
    "    vec3 col = vec3(0.0);\n"
    "    float w = max(pix, 1.0 / 960.0);                          // half the line's width\n"
    "    float m = w + 110.0 * pix;                                // as far as the glow reaches\n"
    "    vec2 box = hs - 0.02;\n"
    "    for (int sh = 0; sh < 2; sh++)\n"
    "    {\n"
    "        // where the four corners start and how fast they move (fractions of the screen per second)\n"
    "        float h = float(sh * 4);\n"
    "        vec4 phx = vec4(hash13(vec3(h, 1.0, 7.0)), hash13(vec3(h + 1.0, 1.0, 7.0)), hash13(vec3(h + 2.0, 1.0, 7.0)), hash13(vec3(h + 3.0, 1.0, 7.0)));\n"
    "        vec4 phy = vec4(hash13(vec3(h, 2.0, 7.0)), hash13(vec3(h + 1.0, 2.0, 7.0)), hash13(vec3(h + 2.0, 2.0, 7.0)), hash13(vec3(h + 3.0, 2.0, 7.0)));\n"
    "        vec4 rx = 0.035 + 0.04 * vec4(hash13(vec3(h, 3.0, 7.0)), hash13(vec3(h + 1.0, 3.0, 7.0)), hash13(vec3(h + 2.0, 3.0, 7.0)), hash13(vec3(h + 3.0, 3.0, 7.0)));\n"
    "        vec4 ry = 0.035 + 0.04 * vec4(hash13(vec3(h, 4.0, 7.0)), hash13(vec3(h + 1.0, 4.0, 7.0)), hash13(vec3(h + 2.0, 4.0, 7.0)), hash13(vec3(h + 3.0, 4.0, 7.0)));\n"
    "        // where each corner goes during the trail: between its newest and oldest place, or up to\n"
    "        // the edge of the screen if it bounced there in between\n"
    "        vec4 ux = phx + rx * t, uy = phy + ry * t;\n"
    "        vec4 x1 = triWave(ux), x0 = triWave(ux - rx * SPAN), y1 = triWave(uy), y0 = triWave(uy - ry * SPAN);\n"
    "        vec4 kx = floor(2.0 * ux), ky = floor(2.0 * uy);\n"
    "        vec4 bx = step(0.5, kx - floor(2.0 * (ux - rx * SPAN))), by = step(0.5, ky - floor(2.0 * (uy - ry * SPAN)));\n"
    "        vec4 ex = step(mod(kx, 2.0), vec4(0.5)), ey = step(mod(ky, 2.0), vec4(0.5));   // 1: bounced at the top end\n"
    "        vec4 xlo = min(min(x0, x1), mix(vec4(1.0), vec4(-1.0), bx * (1.0 - ex))), xhi = max(max(x0, x1), mix(vec4(-1.0), vec4(1.0), bx * ex));\n"
    "        vec4 ylo = min(min(y0, y1), mix(vec4(1.0), vec4(-1.0), by * (1.0 - ey))), yhi = max(max(y0, y1), mix(vec4(-1.0), vec4(1.0), by * ey));\n"
    "        // which of the four sides (corner i to corner i+1) come near this pixel during the trail\n"
    "        vec4 near = step(min(xlo, xlo.yzwx) * box.x - m, vec4(s.x)) * step(vec4(s.x), max(xhi, xhi.yzwx) * box.x + m)\n"
    "                  * step(min(ylo, ylo.yzwx) * box.y - m, vec4(s.y)) * step(vec4(s.y), max(yhi, yhi.yzwx) * box.y + m);\n"
    "        if (dot(near, near) < 0.5) continue;\n"
    "        float d2[8];\n"
    "        for (int k = 0; k < 8; k++) d2[k] = 1e9;\n"
    "        for (int e = 0; e < 4; e++)\n"
    "        {\n"
    "            if (near[e] < 0.5) continue;\n"
    "            int f = (e + 1) % 4;\n"
    "            // unless a corner bounced during the trail, the copies lie evenly between the newest\n"
    "            // and the oldest\n"
    "            bool straight = bx[e] + by[e] + bx[f] + by[f] < 0.5;\n"
    "            vec2 a0 = vec2(x1[e], y1[e]) * box, a7 = vec2(x0[e], y0[e]) * box;\n"
    "            vec2 b0 = vec2(x1[f], y1[f]) * box, b7 = vec2(x0[f], y0[f]) * box;\n"
    "            for (int k = 0; k < 8; k++)\n"
    "            {\n"
    "                vec2 a, b;\n"
    "                if (straight)\n"
    "                {\n"
    "                    a = mix(a0, a7, float(k) / 7.0);\n"
    "                    b = mix(b0, b7, float(k) / 7.0);\n"
    "                }\n"
    "                else\n"
    "                {\n"
    "                    float tk = t - DT * float(k);\n"
    "                    a = vec2(triWave(phx[e] + rx[e] * tk), triWave(phy[e] + ry[e] * tk)) * box;\n"
    "                    b = vec2(triWave(phx[f] + rx[f] * tk), triWave(phy[f] + ry[f] * tk)) * box;\n"
    "                }\n"
    "                d2[k] = min(d2[k], segDist2(s, a, b));\n"
    "            }\n"
    "        }\n"
    "        // the colour drifts slowly, and a little further along the trail; the newest copy is the\n"
    "        // brightest, with a whiter core; the glow comes from the nearest copies\n"
    "        float fade = 1.0, gd = 1e9;\n"
    "        vec3 gt = vec3(0.0);\n"
    "        vec3 ang = TAU * (t * 0.013 + 0.5 * float(sh) + vec3(0.0, 0.33, 0.67));\n"
    "        vec3 cs = cos(ang), sn = sin(ang);\n"
    "        const float CD = 0.9758, SD = 0.2187;                 // cos and sin of 0.035 turns\n"
    "        for (int k = 0; k < 8; k++)\n"
    "        {\n"
    "            vec3 tint = 0.5 + 0.5 * cs;\n"
    "            tint *= tint;\n"
    "            vec3 c2 = cs * CD + sn * SD;                      // the next copy's colour\n"
    "            sn = sn * CD - cs * SD;\n"
    "            cs = c2;\n"
    "            if (d2[k] < 1e8)\n"
    "            {\n"
    "                float d = sqrt(d2[k]);\n"
    "                float core = clamp((w - d) / pix + 0.5, 0.0, 1.0);\n"
    "                col += fade * (0.8 * core * tint + (k == 0 ? 0.25 * core : 0.0));\n"
    "                float dg = d + 4.0 * pix * float(k);\n"
    "                if (dg < gd) { gd = dg; gt = tint; }\n"
    "            }\n"
    "            fade *= 0.76;\n"
    "        }\n"
    "        col += gt * (0.09 * exp(-gd / (3.0 * pix)) + 0.025 * exp(-gd / (12.0 * pix)));\n"
    "    }\n"
    "    return col;\n"
    "}\n"
    "\n"
    "// a sprite's own pixel (its centre), seen from screen pixel fc: the sprite stands at pos, in scene\n"
    "// pixels of n screen pixels; it moves in whole screen pixels and keeps its big pixels\n"
    "vec2 spritePix(vec2 fc, vec2 pos, float n) { return floor((fc - floor(pos * n)) / n) + 0.5; }\n"
    "\n"
    "// signed distances to a five-pointed star and to a triangle (< 0 inside)\n"
    "float sdStar5(vec2 p, float r, float rf)\n"
    "{\n"
    "    const vec2 k1 = vec2(0.809016994, -0.587785252), k2 = vec2(-0.809016994, -0.587785252);\n"
    "    p.x = abs(p.x);\n"
    "    p -= 2.0 * max(dot(k1, p), 0.0) * k1;\n"
    "    p -= 2.0 * max(dot(k2, p), 0.0) * k2;\n"
    "    p.x = abs(p.x);\n"
    "    p.y -= r;\n"
    "    vec2 ba = rf * vec2(-k1.y, k1.x) - vec2(0.0, 1.0);\n"
    "    float h = clamp(dot(p, ba) / dot(ba, ba), 0.0, r);\n"
    "    return length(p - ba * h) * sign(p.y * ba.x - p.x * ba.y);\n"
    "}\n"
    "float sdTriangle(vec2 p, float r)\n"
    "{\n"
    "    const float k = 1.7320508;\n"
    "    p.x = abs(p.x) - r;\n"
    "    p.y = p.y + r / k;\n"
    "    if (p.x + k * p.y > 0.0) p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;\n"
    "    p.x -= clamp(p.x, -2.0 * r, 0.0);\n"
    "    return -length(p) * sign(p.y);\n"
    "}\n"
    "\n"
    "// Underwater (6): a calm sea floor from a 16-bit game, drawn at 224 lines. The surface ripples at\n"
    "// the top; light falls in slanted rays that sway slowly; far away a reef, fish passing and now and\n"
    "// then a school of small fish; on the sand rocks, corals, sponges, kelp and seaweed swaying,\n"
    "// patches of light moving over it, shells and starfish; bubbles rise, specks drift down.\n"
    "// hs: half the screen's size in screen heights.\n"
    "float segPix(vec2 p, vec2 a, vec2 b)                         // distance to a segment\n"
    "{\n"
    "    vec2 ba = b - a, pa = p - a;\n"
    "    return length(pa - ba * clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0));\n"
    "}\n"
    "vec3 underwater(vec2 fc, vec2 hs, float t, float pix)\n"
    "{\n"
    "    float n = pixSize(224.0, pix);\n"
    "    vec2 p = floor(fc / n);\n"
    "    float x = p.x + 0.5, y = p.y + 0.5;\n"
    "    float L = 1.0 / (n * pix);                                // the screen's height in scene pixels\n"
    "    bool dt = mod(p.x + p.y, 2.0) < 1.0;                      // every other pixel, for dithering\n"
    "    // the water, lighter toward the surface, in bands with dithered edges\n"
    "    float wb = clamp(floor((y + 100.0) / 26.0 + 0.4 * (bayer4(p) - 0.47)) / 7.0, 0.0, 1.0);\n"
    "    vec3 col = mix(rgb8(8.0, 30.0, 70.0), rgb8(40.0, 120.0, 156.0), wb);\n"
    "    // the surface, seen from below: a bright rippling edge at the top of the screen\n"
    "    float ys = 0.5 * L - 7.0 + 1.6 * sin(x * 0.07 + t * 0.7) + 1.2 * sin(x * 0.19 - t * 0.5);\n"
    "    if (y > ys - 1.0)\n"
    "    {\n"
    "        col = y < ys ? rgb8(150.0, 215.0, 230.0) : mix(col, rgb8(110.0, 190.0, 215.0), 0.45);\n"
    "        if (y > ys + 1.0 && sin(x * 0.31 + 3.0 * sin(y * 0.5 + t * 0.6) - t * 0.4) > 0.6 && dt) col = rgb8(150.0, 215.0, 230.0);\n"
    "    }\n"
    "    // light falling in slanted rays, swaying slowly, fainter deeper down (dithered at the edges)\n"
    "    float u = x + 0.5 * y;\n"
    "    float ray = sin(u * 0.045 + 0.8 * sin(t * 0.13)) + 0.6 * sin(u * 0.11 - t * 0.07);\n"
    "    float lit = ray > 0.95 || (ray > 0.75 && dt) ? 0.3 * smoothstep(-60.0, 90.0, y) : 0.0;\n"
    "    col = mix(col, rgb8(110.0, 190.0, 210.0), lit);\n"
    "    // the sand line\n"
    "    float sand = -84.0 + 3.0 * sin(x * 0.06) + 2.0 * sin(x * 0.17 + 1.0);\n"
    "    // a reef far away, blue in the distance, lit a little at the top\n"
    "    if (y < sand + 52.0)\n"
    "    {\n"
    "        float spire = max(sin(x * 0.045 + 1.0), 0.0);         // now and then a taller rock\n"
    "        spire *= spire;\n"
    "        spire *= spire;\n"
    "        float reef = sand + 6.0 + 30.0 * (0.65 * noise1(x * 0.03 + 20.0) + 0.35 * noise1(x * 0.11 + 50.0))\n"
    "                   + 14.0 * spire * spire;\n"
    "        if (y < reef) col = y > reef - 1.0 ? rgb8(30.0, 84.0, 110.0) : mix(rgb8(14.0, 50.0, 78.0), rgb8(20.0, 64.0, 92.0), lit * 2.0);\n"
    "    }\n"
    "    // fish far away, dark, crossing slowly\n"
    "    float span = 2.0 * hs.x / (n * pix) + 40.0;\n"
    "    if (y > -18.0 && y < 58.0)\n"
    "    for (int i = 0; i < 3; i++)\n"
    "    {\n"
    "        float h = hash13(vec3(float(i), 3.0, 63.0));\n"
    "        vec2 fp = vec2(mod(h * span + t * (4.0 + 4.0 * h), span) - 0.5 * span,\n"
    "                       -10.0 + 60.0 * fract(h * 7.0) + 4.0 * sin(t * 0.4 + h * 9.0));\n"
    "        vec2 d = spritePix(fc, fp, n);\n"
    "        if (d.x * d.x / 36.0 + d.y * d.y / 9.0 < 1.0 || (d.x < -5.0 && d.x > -10.0 && abs(d.y) < (-4.0 - d.x) * 0.7))\n"
    "            col = mix(col, rgb8(6.0, 22.0, 52.0), 0.75);\n"
    "    }\n"
    "    // now and then a school of small silvery fish, swimming to the left together\n"
    "    float sc = t / 80.0, ci = floor(sc);\n"
    "    vec2 sp = vec2(mix(0.5 * span + 30.0, -0.5 * span - 30.0, fract(sc)),\n"
    "                   -30.0 + 70.0 * hash13(vec3(ci, 5.0, 66.0)) + 5.0 * sin(t * 0.35));\n"
    "    if (abs(x - sp.x) < 30.0 && abs(y - sp.y) < 15.0)\n"
    "        for (int i = 0; i < 12; i++)\n"
    "        {\n"
    "            float h = hash13(vec3(float(i), ci, 67.0));\n"
    "            vec2 fp = sp + vec2(40.0 * (h - 0.5) + 2.0 * sin(t * 0.9 + h * 30.0), 18.0 * (fract(h * 13.0) - 0.5) + 1.5 * sin(t * 1.3 + h * 17.0));\n"
    "            vec2 d = spritePix(fc, fp, n);\n"
    "            if (d.x * d.x / 16.0 + d.y * d.y / 3.2 < 1.0)\n"
    "                col = d.x < -2.0 && d.x > -3.0 && d.y > 0.0 && d.y < 1.0 ? rgb8(20.0, 40.0, 60.0)\n"
    "                    : d.y > 0.0 ? rgb8(92.0, 132.0, 160.0) : rgb8(150.0, 188.0, 204.0);\n"
    "            else if (d.x > 3.0 && d.x < 6.0 && abs(d.y) < 0.75 * (d.x - 2.6) && abs(d.y) > 0.9 * (d.x - 5.0))\n"
    "                col = rgb8(92.0, 132.0, 160.0);\n"
    "        }\n"
    "    // the sand: little ripples, lighter at the top, patches of light moving over it, pebbles,\n"
    "    // shells and now and then a starfish\n"
    "    if (y < sand)\n"
    "    {\n"
    "        float dep = clamp((sand - y) / 26.0 + 0.3 * (bayer4(p) - 0.47), 0.0, 1.0);\n"
    "        col = mix(rgb8(118.0, 120.0, 112.0), rgb8(78.0, 86.0, 92.0), floor(dep * 3.0) / 2.0);\n"
    "        if (y > sand - 2.0) col = rgb8(138.0, 140.0, 128.0);\n"
    "        else if (sin(x * 0.42 + 2.0 * sin(x * 0.05) + y * 1.3) > 0.75 && dt) col *= 0.82;\n"
    "        // light through the rippling surface, in patches that drift over the sand, flattened by the\n"
    "        // low angle and fading deeper into it\n"
    "        float cs = sin(x * 0.17 + t * 0.5 + 1.6 * sin(y * 0.9 + x * 0.05 - t * 0.4)) + sin(x * 0.07 - t * 0.3 + y * 0.6);\n"
    "        cs -= 0.04 * (sand - y);\n"
    "        if (cs > 1.4 && (cs > 1.6 || dt)) col = mix(col, rgb8(175.0, 190.0, 170.0), 0.55);\n"
    "        float hp = hash13(vec3(floor(x / 3.0), floor(y / 2.0), 64.0));\n"
    "        if (y < sand - 2.0)\n"
    "        {\n"
    "            if (hp > 0.975 && mod(p.x, 3.0) < 2.0 && mod(p.y, 2.0) < 1.0) col = rgb8(70.0, 78.0, 84.0);\n"
    "            else if (hp < 0.004) col = rgb8(200.0, 175.0, 170.0);\n"
    "        }\n"
    "        vec2 sf = vec2(x - (floor(x / 70.0) * 70.0 + 35.0 + 20.0 * (hash13(vec3(floor(x / 70.0), 1.0, 65.0)) - 0.5)), y - (sand - 12.0));\n"
    "        if (hash13(vec3(floor(x / 70.0), 2.0, 65.0)) > 0.7 && sdStar5(sf, 4.2, 0.45) < 0.0) col = rgb8(196.0, 120.0, 84.0);\n"
    "    }\n"
    "    // on the sand: rocks, corals, sponges and kelp, one in each stretch of 30 pixels\n"
    "    float c0 = floor(x / 30.0);\n"
    "    if (y < -18.0)\n"
    "    for (int i = -1; i <= 1; i++)\n"
    "    {\n"
    "        float c = c0 + float(i);\n"
    "        float h = hash13(vec3(c, 11.0, 68.0)), hk = hash13(vec3(c, 12.0, 68.0));\n"
    "        float ax = floor(c * 30.0 + 15.0 + 10.0 * (hk - 0.5)) + 0.5;\n"
    "        float by = floor(-84.0 + 3.0 * sin(ax * 0.06) + 2.0 * sin(ax * 0.17 + 1.0));\n"
    "        vec2 d = vec2(x - ax, y - by);\n"
    "        if (abs(d.x) > 15.0 || d.y < -4.0 || d.y > 60.0) continue;\n"
    "        float sz = 0.8 + 0.5 * fract(hk * 7.0);\n"
    "        if (h < 0.25)\n"
    "        {\n"
    "            // a rock, lit from above\n"
    "            vec2 e = vec2(d.x / (6.0 + 6.0 * fract(hk * 3.0)), (d.y + 1.0) / (4.0 + 5.0 * fract(hk * 5.0)));\n"
    "            if (dot(e, e) < 1.0)\n"
    "            {\n"
    "                float l = -0.5 * e.x + 0.85 * e.y;\n"
    "                col = l > 0.45 ? rgb8(104.0, 122.0, 130.0) : l > -0.1 ? rgb8(68.0, 86.0, 100.0) : rgb8(40.0, 54.0, 70.0);\n"
    "                if (e.y > 0.55 && hash13(vec3(p, 69.0)) > 0.75) col = rgb8(52.0, 92.0, 72.0);\n"
    "            }\n"
    "        }\n"
    "        else if (h < 0.37)\n"
    "        {\n"
    "            // a brain coral: a low dome with winding grooves\n"
    "            float r = 7.0 * sz;\n"
    "            vec2 e = vec2(d.x / r, (d.y + 0.5) / (0.75 * r));\n"
    "            if (dot(e, e) < 1.0 && d.y > -1.5)\n"
    "                col = sin(d.x * 1.1 + 2.5 * sin(d.y * 0.8 + hk * 9.0)) > 0.45 ? rgb8(104.0, 86.0, 74.0)\n"
    "                    : (e.y > 0.5 ? rgb8(160.0, 138.0, 104.0) : rgb8(134.0, 114.0, 90.0));\n"
    "        }\n"
    "        else if (h < 0.52)\n"
    "        {\n"
    "            // a branching coral, pink, lighter at the tips\n"
    "            vec2 q = vec2(d.x * (hk > 0.5 ? 1.0 : -1.0), d.y) / sz;\n"
    "            float dd = min(min(segPix(q, vec2(0.0, -1.0), vec2(0.0, 8.0)), segPix(q, vec2(0.0, 4.0), vec2(-5.0, 11.0))),\n"
    "                           min(segPix(q, vec2(0.0, 6.0), vec2(4.0, 13.0)), segPix(q, vec2(0.0, 8.0), vec2(0.0, 15.0))));\n"
    "            dd = min(dd, min(min(segPix(q, vec2(-5.0, 11.0), vec2(-7.0, 17.0)), segPix(q, vec2(-5.0, 11.0), vec2(-3.0, 18.0))),\n"
    "                             min(segPix(q, vec2(4.0, 13.0), vec2(7.0, 18.0)), segPix(q, vec2(4.0, 13.0), vec2(2.0, 20.0)))));\n"
    "            if (dd * sz < 1.1) col = q.y > 15.0 ? rgb8(214.0, 136.0, 146.0) : d.x < 0.0 ? rgb8(178.0, 98.0, 114.0) : rgb8(150.0, 80.0, 100.0);\n"
    "        }\n"
    "        else if (h < 0.62)\n"
    "        {\n"
    "            // a sea fan: a flat fan on a short stem, purple, its branches darker\n"
    "            vec2 q = vec2(d.x / (10.0 * sz), (d.y - 3.0) / (12.0 * sz));\n"
    "            float r = length(q), an = atan(d.x, d.y - 1.0);\n"
    "            if ((q.y > -0.05 && r < 1.0) || (abs(d.x) < 1.0 && d.y < 4.0 && d.y > -1.0))\n"
    "                col = abs(fract(an / 0.3 + 0.5) - 0.5) < 0.12 || abs(d.x) < 1.0 ? rgb8(104.0, 62.0, 120.0)\n"
    "                    : r > 0.82 ? rgb8(170.0, 116.0, 178.0) : rgb8(136.0, 88.0, 150.0);\n"
    "        }\n"
    "        else if (h < 0.74)\n"
    "        {\n"
    "            // tube sponges: three tubes, open at the top\n"
    "            for (int k = 0; k < 3; k++)\n"
    "            {\n"
    "                float ox = float(k - 1) * 4.0 * sz, th = (9.0 + 9.0 * fract(hk * float(k + 3) * 1.7)) * sz;\n"
    "                float dx = d.x - ox;\n"
    "                if (abs(dx) < 2.0 && d.y > -1.0 && d.y < th)\n"
    "                    col = d.y > th - 2.0 && abs(dx) < 1.0 ? rgb8(60.0, 56.0, 40.0) : dx < 0.0 ? rgb8(170.0, 156.0, 92.0) : rgb8(132.0, 118.0, 70.0);\n"
    "            }\n"
    "        }\n"
    "        else if (h < 0.88)\n"
    "        {\n"
    "            // kelp: a tall stem swaying, with leaves on alternate sides\n"
    "            float ht = (32.0 + 20.0 * fract(hk * 11.0)) * min(sz, 1.1);\n"
    "            if (d.y > -1.0 && d.y < ht)\n"
    "            {\n"
    "                float k = d.y / ht;\n"
    "                float sx = 4.0 * k * k * sin(t * 0.6 + hk * 20.0 + d.y * 0.05);\n"
    "                float dx = d.x - sx;\n"
    "                float li = floor(d.y / 6.0), side = mod(li, 2.0) < 0.5 ? -1.0 : 1.0;\n"
    "                vec2 lq = vec2(dx - side * 3.0, d.y - li * 6.0 - 3.0 - side * dx * 0.3);\n"
    "                if (abs(dx) < 1.0) col = rgb8(76.0, 104.0, 52.0);\n"
    "                else if (li > 0.0 && lq.x * lq.x / 9.0 + lq.y * lq.y / 2.2 < 1.0) col = lq.y > 0.0 ? rgb8(104.0, 138.0, 64.0) : rgb8(68.0, 100.0, 50.0);\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "    // seaweed swaying over the sand\n"
    "    float sw = floor(x / 11.0), hw = y < -40.0 ? hash13(vec3(sw, 8.0, 61.0)) : 0.0;\n"
    "    if (hw > 0.45)\n"
    "    {\n"
    "        float top = sand + 10.0 + 24.0 * fract(hw * 7.0);\n"
    "        float k = clamp((y - sand) / (top - sand), 0.0, 1.0);\n"
    "        float dx = abs(x - (sw * 11.0 + 5.5 + 3.0 * k * k * sin(t * 0.7 + hw * 20.0 + y * 0.08)));\n"
    "        if (y < top && y > sand - 1.0 && dx < 1.5) col = dx < 0.5 ? rgb8(50.0, 120.0, 90.0) : rgb8(22.0, 78.0, 66.0);\n"
    "    }\n"
    "    // bubbles rising from a few places, now and then, in different sizes, wobbling\n"
    "    float bc = floor(x / 48.0), hb = hash13(vec3(bc, 7.0, 61.0));\n"
    "    if (hb > 0.6)\n"
    "    {\n"
    "        float yy = fc.y / n - t * 9.0 - 300.0 * hb, cell = floor(yy / 22.0);\n"
    "        float hc = hash13(vec3(bc, cell, 62.0)), r = 1.0 + 2.8 * hc * hc;\n"
    "        vec2 bp = vec2(bc * 48.0 + 8.0 + 32.0 * hb + 1.5 * sin(cell * 1.7 + t * 1.6),\n"
    "                       cell * 22.0 + 11.0 + 7.0 * (fract(hc * 17.0) - 0.5) + t * 9.0 + 300.0 * hb);\n"
    "        vec2 d = spritePix(fc, bp, n);\n"
    "        float Lb = length(d);\n"
    "        if (hc > 0.35 && Lb < r + 0.5 && y > sand + 2.0)\n"
    "        {\n"
    "            float a = r < 2.0 ? 0.45 : Lb > r - 1.0 ? 0.5 : 0.08;          // small ones are just a dot\n"
    "            if (r >= 2.0 && length(d - vec2(-0.45, 0.45) * r) < 0.75) a = 0.75;   // the light caught on top\n"
    "            col = mix(col, rgb8(170.0, 225.0, 240.0), a);\n"
    "        }\n"
    "    }\n"
    "    // specks drifting slowly down through the water\n"
    "    vec2 mq = vec2(x + 3.0 * sin(t * 0.2 + floor(y / 40.0)), y + t * 2.5);\n"
    "    vec2 mc = floor(mq / 18.0);\n"
    "    float hm = hash13(vec3(mc, 70.0));\n"
    "    if (hm > 0.6 && all(equal(floor(mq) - mc * 18.0, floor(vec2(hm, fract(hm * 7.0)) * 17.0))) && y > sand)\n"
    "        col = mix(col, rgb8(160.0, 200.0, 205.0), 0.35);\n"
    "    return 0.55 * col;\n"
    "}\n"
    "\n"
    "// Copper bars (7): Amiga demo raster bars, shiny bands swinging up and down around an invisible\n"
    "// cylinder, stars flying sideways behind them over a sky that the copper fades from black to\n"
    "// violet, a checkerboard floor rushing toward the viewer, polished so the bars show in it.\n"
    "// Drawn at 256 lines, in the Amiga's 4096 colours.\n"
    "vec3 amiga12(vec3 c) { return pow(floor(clamp(c, 0.0, 1.0) * 15.0 + 0.5) / 15.0, vec3(2.2)); }\n"
    "// the bars at line y (from the centre, y up; L lines on the screen): their colour (before the\n"
    "// 4096 colours), and a = 1 where there is one\n"
    "vec4 copperBars(float y, float t, float L)\n"
    "{\n"
    "    const vec3 BAR[6] = vec3[6](vec3(1.0, 0.25, 0.2), vec3(1.0, 0.6, 0.1), vec3(1.0, 0.95, 0.3),\n"
    "                                vec3(0.3, 1.0, 0.35), vec3(0.2, 0.75, 1.0), vec3(0.75, 0.35, 1.0));\n"
    "    vec4 c = vec4(0.0);\n"
    "    float zb = -2.0;\n"
    "    for (int i = 0; i < 6; i++)\n"
    "    {\n"
    "        float a = t * 1.1 + float(i) * TAU / 6.0, z = cos(a);\n"
    "        float dy = abs(y - (0.17 * L + 0.17 * L * sin(a))) / 10.0;\n"
    "        if (dy < 1.0 && z > zb)                               // the nearer ones in front, darker at the back\n"
    "        {\n"
    "            zb = z;\n"
    "            float e = (1.0 - dy) * (1.0 - dy) * (1.0 - dy);\n"
    "            c = vec4(BAR[i] * (1.0 - dy * dy) * (0.6 + 0.4 * z) + 0.25 * e * e, 1.0);\n"
    "        }\n"
    "    }\n"
    "    return c;\n"
    "}\n"
    "vec3 copper(vec2 fc, vec2 hs, float t, float pix)\n"
    "{\n"
    "    float n = pixSize(256.0, pix);\n"
    "    vec2 p = floor(fc / n);\n"
    "    float L = 1.0 / (n * pix);                                // the screen's height in lines\n"
    "    float y = p.y + 0.5, hz = -0.2 * L;\n"
    "    vec3 col;\n"
    "    if (y > hz)\n"
    "    {\n"
    "        // the sky: one colour per line, black high up, violet toward the horizon, which glows\n"
    "        float up = (y - hz) / L;\n"
    "        vec3 sky = mix(vec3(0.16, 0.06, 0.3), vec3(0.0), smoothstep(0.0, 0.35, up)) + vec3(0.35, 0.4, 0.8) * exp(-(y - hz) / 5.0);\n"
    "        // stars flying to the left at three speeds, one on most lines\n"
    "        if (hash13(vec3(p.y, 3.0, 17.0)) > 0.35)\n"
    "        {\n"
    "            float lay = floor(hash13(vec3(p.y, 4.0, 17.0)) * 3.0), w = 2.0 * hs.x * L;\n"
    "            float x = mod(hash13(vec3(p.y, 5.0, 17.0)) * w - t * (14.0 + 22.0 * lay), w) - 0.5 * w;\n"
    "            if (p.x == floor(x)) sky = max(sky, vec3(0.3 + 0.35 * lay));\n"
    "            else if (lay > 1.5 && p.x > floor(x) && p.x < floor(x) + 4.0) sky = max(sky, vec3(0.25 - 0.06 * (p.x - floor(x))));   // a short trail\n"
    "        }\n"
    "        vec4 bar = copperBars(y, t, L);\n"
    "        col = amiga12(bar.a > 0.0 ? bar.rgb : sky);\n"
    "        if (abs(y - hz - 0.5) < 0.6) col = amiga12(vec3(0.55, 0.65, 1.0));   // the horizon\n"
    "    }\n"
    "    else\n"
    "    {\n"
    "        // the floor: a checkerboard in perspective, fading out in the distance; the bars show in\n"
    "        // it upside down, clearest near the horizon\n"
    "        float dy = (hz - y) / L;\n"
    "        float z = 0.09 / dy;\n"
    "        vec2 g = vec2((p.x + 0.5) / L * z * 7.0, z * 7.0 + t * 1.6);\n"
    "        float ch = mod(floor(g.x) + floor(g.y), 2.0);\n"
    "        vec3 c = mix(vec3(0.85, 0.85, 1.0), vec3(0.2, 0.1, 0.55), ch);\n"
    "        float cell = max(z * 7.0 / L, 0.09 / (dy * dy) * 7.0 / L);   // cell size against a pixel\n"
    "        c = mix(c, vec3(0.52, 0.48, 0.78), smoothstep(0.25, 0.6, cell));\n"
    "        c *= exp(-0.12 * z);\n"
    "        vec4 bar = copperBars(2.0 * hz - y, t, L);\n"
    "        c = mix(c, bar.rgb, bar.a * (0.3 + 0.35 * ch) * exp(-(hz - y) / 60.0));\n"
    "        c += vec3(0.2, 0.22, 0.45) * exp(-(hz - y) / 4.0);    // the horizon's glow, mirrored\n"
    "        col = amiga12(c);\n"
    "    }\n"
    "    return 0.5 * col;\n"
    "}\n"
    "\n"
    "// Amiga demo (8): a screen from an early-90s Amiga demo, built the way they were: everything in\n"
    "// 320x256 pixels and the Amiga's 4096 colours, all motion from sine waves. A glenz vector (a\n"
    "// see-through solid of 24 triangles, white and blue) and a cube of vector balls that turns into a\n"
    "// ball and back swing out from behind the monitor, one on each side; stars fly toward the viewer;\n"
    "// a twister turns along the bottom; a DYCP scroller (every letter on its own sine) runs along the\n"
    "// top in copper colours. Heavier than the other scenes.\n"
    "const uint DEMO_FONT[88] = uint[88](\n"
    "    0x00000000u, 0x00000000u, 0x3C66C3C3u, 0xFFC3C300u, 0xFCC6C6FCu, 0xC6C6FC00u, 0x3E63C0C0u, 0xC0633E00u,\n"
    "    0xF8CCC6C6u, 0xC6CCF800u, 0xFEC0C0FCu, 0xC0C0FE00u, 0xFEC0C0FCu, 0xC0C0C000u, 0x3E60C0CEu, 0xC6663C00u,\n"
    "    0xC6C6C6FEu, 0xC6C6C600u, 0x7E181818u, 0x18187E00u, 0x0E060606u, 0xC6C67C00u, 0xC6CCD8F0u, 0xD8CCC600u,\n"
    "    0xC0C0C0C0u, 0xC0C0FE00u, 0xC3E7FFDBu, 0xC3C3C300u, 0xC6E6F6DEu, 0xCEC6C600u, 0x3C66C3C3u, 0xC3663C00u,\n"
    "    0xFCC6C6FCu, 0xC0C0C000u, 0x3C66C3C3u, 0xCB663B00u, 0xFCC6C6FCu, 0xD8CCC600u, 0x7EC0C07Cu, 0x0606FC00u,\n"
    "    0xFF181818u, 0x18181800u, 0xC6C6C6C6u, 0xC6C67C00u, 0xC6C6C6C6u, 0x6C381000u, 0xC3C3C3DBu, 0xFFE7C300u,\n"
    "    0xC66C3838u, 0x6CC6C600u, 0xC3663C18u, 0x18181800u, 0xFE060C18u, 0x3060FE00u, 0x3C66CEDEu, 0xF6663C00u,\n"
    "    0x18387818u, 0x18187E00u, 0x7CC6061Cu, 0x70C0FE00u, 0x7CC6063Cu, 0x06C67C00u, 0x0E1E3666u, 0xFE060600u,\n"
    "    0xFEC0FC06u, 0x06C67C00u, 0x3C60C0FCu, 0xC6C67C00u, 0xFE060C18u, 0x30303000u, 0x7CC6C67Cu, 0xC6C67C00u,\n"
    "    0x7CC6C67Eu, 0x060C7800u, 0x00000000u, 0x00181800u, 0x00000000u, 0x00181830u, 0x18181818u, 0x18001800u,\n"
    "    0x0000007Eu, 0x00000000u, 0x00181800u, 0x18180000u, 0x18183000u, 0x00000000u, 0x7CC6061Cu, 0x18001800u);\n"
    "const int DEMO_TEXT[319] = int[319](\n"
    "    12, 15, 12, 1, 0, 18, 5, 20, 18, 15, 0, 16, 18, 5, 19, 5, 14, 20, 19, 37, 37, 37, 0, 20,\n"
    "    8, 5, 0, 19, 3, 18, 5, 5, 14, 0, 1, 18, 15, 21, 14, 4, 0, 25, 15, 21, 18, 0, 13, 15,\n"
    "    14, 9, 20, 15, 18, 39, 0, 0, 0, 7, 12, 5, 14, 26, 0, 22, 5, 3, 20, 15, 18, 19, 38, 0,\n"
    "    22, 5, 3, 20, 15, 18, 0, 2, 1, 12, 12, 19, 38, 0, 1, 0, 20, 23, 9, 19, 20, 5, 18, 0,\n"
    "    1, 14, 4, 0, 20, 8, 9, 19, 0, 12, 9, 20, 20, 12, 5, 0, 4, 25, 3, 16, 0, 19, 3, 18,\n"
    "    15, 12, 12, 5, 18, 38, 0, 1, 12, 12, 0, 9, 14, 0, 30, 29, 27, 24, 29, 32, 33, 0, 1, 14,\n"
    "    4, 0, 31, 27, 36, 33, 0, 3, 15, 12, 15, 21, 18, 19, 38, 0, 20, 8, 5, 0, 23, 1, 25, 0,\n"
    "    20, 8, 5, 0, 1, 13, 9, 7, 1, 0, 4, 9, 4, 0, 9, 20, 37, 0, 0, 0, 7, 18, 5, 5,\n"
    "    20, 9, 14, 7, 19, 0, 20, 15, 0, 1, 12, 12, 0, 1, 13, 9, 7, 1, 0, 6, 18, 5, 1, 11,\n"
    "    19, 38, 0, 19, 3, 5, 14, 5, 18, 19, 0, 1, 14, 4, 0, 3, 18, 20, 0, 12, 15, 22, 5, 18,\n"
    "    19, 39, 0, 0, 0, 12, 15, 12, 1, 0, 9, 19, 0, 1, 0, 18, 5, 20, 18, 9, 5, 22, 5, 18,\n"
    "    38, 0, 18, 5, 20, 18, 15, 0, 2, 5, 3, 1, 21, 19, 5, 0, 9, 20, 0, 9, 19, 0, 18, 5,\n"
    "    20, 18, 15, 37, 37, 37, 0, 0, 0, 20, 5, 24, 20, 0, 18, 5, 19, 20, 1, 18, 20, 19, 37, 37,\n"
    "    37, 0, 0, 0, 0, 0, 0);\n"
    "mat3 demoRot(vec3 a)\n"
    "{\n"
    "    vec3 c = cos(a), s = sin(a);\n"
    "    return mat3(c.y * c.z, c.y * s.z, -s.y,\n"
    "                s.x * s.y * c.z - c.x * s.z, s.x * s.y * s.z + c.x * c.z, s.x * c.y,\n"
    "                c.x * s.y * c.z + s.x * s.z, c.x * s.y * s.z - s.x * c.z, c.x * c.y);\n"
    "}\n"
    "vec3 demoRainbow(float x) { return 0.5 + 0.5 * cos(TAU * (x + vec3(0.0, 0.33, 0.67))); }\n"
    "// one pixel of the scroller's font: glyph g, column x and row y (0-7, top row 0)\n"
    "bool demoFontPixel(int g, int x, int y)\n"
    "{\n"
    "    uint w = DEMO_FONT[g * 2 + (y >> 2)];\n"
    "    return ((w >> uint((3 - (y & 3)) * 8 + 7 - x)) & 1u) == 1u;\n"
    "}\n"
    "vec3 amigaDemo(vec2 fc, vec2 hs, float t, float pix)\n"
    "{\n"
    "    float n = pixSize(256.0, pix);\n"
    "    vec2 P = floor(fc / n);                                   // the Amiga pixel, from the centre, y up\n"
    "    float L = 1.0 / (n * pix);                                // the screen's height in Amiga pixels\n"
    "    vec2 s = (P + 0.5) / L;                                   // its centre, in screen heights\n"
    "    // the background: black in the middle, the copper fading it to deep blue at the bottom and to\n"
    "    // deep violet at the top, one colour per line\n"
    "    float vy = (P.y + 0.5) / L;\n"
    "    vec3 col = vec3(0.02, 0.05, 0.22) * smoothstep(-0.2, -0.5, vy) + vec3(0.12, 0.02, 0.2) * smoothstep(0.3, 0.5, vy);\n"
    "\n"
    "    // stars flying toward the viewer: layers that grow from the centre, three shades as on a 3-plane screen\n"
    "    for (int i = 0; i < 4; i++)\n"
    "    {\n"
    "        float k = t * 0.22 + float(i) * 0.25, z = fract(k), seed = floor(k) * 4.0 + float(i);\n"
    "        float cell = 0.02 * exp2(4.0 * z);\n"
    "        vec2 off = 50.0 * vec2(hash13(vec3(seed, 1.0, 81.0)), hash13(vec3(seed, 2.0, 81.0)));\n"
    "        vec2 id = floor(s / cell + off);\n"
    "        float h = hash13(vec3(id, seed + 3.0));\n"
    "        vec2 sp = (id - off + 0.25 + 0.5 * vec2(h, fract(h * 13.0))) * cell;   // the star, in screen heights\n"
    "        if (h > 0.75 && all(equal(floor(sp * L), P)) && z > 0.15)\n"
    "            col = max(col, vec3(z < 0.45 ? 0.27 : z < 0.75 ? 0.6 : 1.0));\n"
    "    }\n"
    "\n"
    "    // the two objects swing from one side of the monitor to the other, opposite each other\n"
    "    float sw = sin(t * 0.42), A = max(hs.x - 0.22, 0.3);\n"
    "    vec2 cg = vec2(A * sw, 0.06 * sin(t * 0.9));               // the glenz vector\n"
    "    vec2 cb = vec2(-A * sw, 0.06 * sin(t * 0.9 + 2.0));        // the vector balls\n"
    "\n"
    "    // glenz vector: a tetrakis hexahedron (a cube with a low pyramid on each face). A ray from the eye\n"
    "    // enters through one face and leaves through another; white faces are solid, blue ones show the\n"
    "    // back faces through them, as two bitplanes of front and back faces did\n"
    "    const float H = 0.6, GS = 0.1;\n"
    "    vec2 u = (s - cg) / GS;\n"
    "    if (dot(u, u) < 8.0)\n"
    "    {\n"
    "        mat3 R = demoRot(vec3(t * 0.8, t * 1.1, t * 0.5));\n"
    "        vec3 o = vec3(0.0, 0.0, 5.0) * R, d = vec3(u, -5.0) * R;   // the ray, in the object's frame\n"
    "        float tin = -1e9, tout = 1e9;\n"
    "        int kin = 0, kout = 0;\n"
    "        for (int k = 0; k < 24; k++)\n"
    "        {\n"
    "            int f = k / 4, e = k % 4, ax = f / 2, ex = (ax + 1 + e / 2) % 3;\n"
    "            vec3 nk = (ax == 0 ? vec3(1.0, 0.0, 0.0) : ax == 1 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0)) * (f % 2 == 0 ? 1.0 : -1.0)\n"
    "                    + (ex == 0 ? vec3(1.0, 0.0, 0.0) : ex == 1 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0)) * (e % 2 == 0 ? H : -H);\n"
    "            float nd = dot(nk, d), tt = (1.0 + H - dot(nk, o)) / nd;\n"
    "            if (nd < 0.0) { if (tt > tin) { tin = tt; kin = k; } }\n"
    "            else if (tt < tout) { tout = tt; kout = k; }\n"
    "        }\n"
    "        if (tin < tout)\n"
    "        {\n"
    "            // a checkerboard of triangles; the faces turned toward the light are lighter (three\n"
    "            // shades, as a light-sourced glenz had)\n"
    "            bool frontWhite = kin % 4 < 2, backWhite = kout % 4 < 2;\n"
    "            int f = kin / 4, e = kin % 4, ax = f / 2, ex = (ax + 1 + e / 2) % 3;\n"
    "            vec3 nk = (ax == 0 ? vec3(1.0, 0.0, 0.0) : ax == 1 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0)) * (f % 2 == 0 ? 1.0 : -1.0)\n"
    "                    + (ex == 0 ? vec3(1.0, 0.0, 0.0) : ex == 1 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0)) * (e % 2 == 0 ? H : -H);\n"
    "            float lv = floor(clamp(dot(normalize(R * nk), vec3(-0.45, 0.55, 0.7)), 0.0, 1.0) * 2.99) / 2.0;\n"
    "            vec3 back = backWhite ? vec3(0.55, 0.6, 0.85) : vec3(0.05, 0.1, 0.45);\n"
    "            col = frontWhite ? vec3(0.95, 0.95, 1.0) * (0.72 + 0.28 * lv) : mix(back, vec3(0.2, 0.45, 1.0) * (0.75 + 0.45 * lv), 0.45);\n"
    "        }\n"
    "    }\n"
    "\n"
    "    // vector balls: 26 balls in a 3x3x3 cube that turns into a ball and back, nearer balls in front,\n"
    "    // each shaded like a bob drawn in eight shades\n"
    "    const float BS = 0.085;\n"
    "    vec2 ub = (s - cb) / BS;\n"
    "    if (dot(ub, ub) < 10.0)\n"
    "    {\n"
    "        mat3 R = demoRot(vec3(t * 0.9, t * 0.6, t * 0.35));\n"
    "        float m = smoothstep(-0.4, 0.4, sin(t * 0.33)), zb = -1e9;\n"
    "        vec2 bd = vec2(0.0);\n"
    "        int bi = 0;\n"
    "        for (int i = 0; i < 27; i++)\n"
    "        {\n"
    "            if (i == 13) continue;\n"
    "            vec3 q = vec3(float(i % 3), float((i / 3) % 3), float(i / 9)) - 1.0;\n"
    "            float fi = float(i < 13 ? i : i - 1), zz = 1.0 - (2.0 * fi + 1.0) / 26.0, ph = fi * 2.39996;\n"
    "            vec3 p = R * mix(q, 1.45 * vec3(sqrt(1.0 - zz * zz) * vec2(cos(ph), sin(ph)), zz), m);\n"
    "            float w = 1.0 / (1.0 - p.z * 0.18), r = 0.33 * w;\n"
    "            vec2 dd = (ub - p.xy * w) / r;\n"
    "            if (dot(dd, dd) < 1.0 && p.z > zb) { zb = p.z; bd = dd; bi = i; }\n"
    "        }\n"
    "        if (zb > -1e8)\n"
    "        {\n"
    "            vec3 nb = vec3(bd, sqrt(max(1.0 - dot(bd, bd), 0.0)));\n"
    "            float l = dot(nb, normalize(vec3(-0.5, 0.6, 0.62)));\n"
    "            float lev = floor((0.25 + 0.75 * max(l, 0.0)) * 7.0 + 0.5) / 7.0;\n"
    "            vec3 base = bi / 9 == 0 ? vec3(1.0, 0.35, 0.2) : bi / 9 == 1 ? vec3(1.0, 0.8, 0.25) : vec3(0.35, 0.7, 1.0);\n"
    "            col = base * lev + (l > 0.93 ? 0.6 : 0.0);\n"
    "        }\n"
    "    }\n"
    "\n"
    "    // the twister along the bottom: a bar with a square cross-section, turned a little more at\n"
    "    // every column, its four faces in copper colours with a checked pattern\n"
    "    float Yc = -0.43 * L + 3.0 * sin(P.x * 0.045 + t * 1.3);\n"
    "    if (abs(P.y + 0.5 - Yc) < 16.0)\n"
    "    {\n"
    "        float a = t * 1.7 + P.x * 0.03 * sin(t * 0.31);\n"
    "        for (int i = 0; i < 4; i++)\n"
    "        {\n"
    "            float a0 = a + float(i) * 1.5707963, y0 = Yc + 15.5 * sin(a0), y1 = Yc + 15.5 * sin(a0 + 1.5707963);\n"
    "            float y = P.y + 0.5;\n"
    "            if (y1 > y0 && y >= y0 && y < y1)\n"
    "            {\n"
    "                float v = (y - y0) / (y1 - y0), shade = cos(a0 + 0.7853982);\n"
    "                float chk = mod(floor(v * 4.0) + floor((P.x + t * 24.0) / 8.0), 2.0);\n"
    "                vec3 fcol = demoRainbow(float(i) * 0.25 + 0.08 * sin(t * 0.2));\n"
    "                col = fcol * (0.3 + 0.7 * shade) * (chk < 0.5 ? 1.0 : 0.65) * (v < 0.06 || v > 0.94 ? 0.4 : 1.0);\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "\n"
    "    // the DYCP scroller along the top: 16x16 letters, each on its own sine, coloured line by line\n"
    "    // like a copper list, with a shadow\n"
    "    float base = floor(0.43 * L);\n"
    "    float sx = P.x + floor(t * 70.0);\n"
    "    float slot = floor(sx / 16.0);\n"
    "    int ch = DEMO_TEXT[int(mod(slot, float(DEMO_TEXT.length())))];\n"
    "    float oy = floor(7.0 * sin(slot * 0.55 + t * 3.2));\n"
    "    int gx = int(floor((sx - slot * 16.0) / 2.0)), gy = int(floor((base + oy - P.y) / 2.0));\n"
    "    if (gy >= 0 && gy < 8 && demoFontPixel(ch, gx, gy))\n"
    "        col = demoRainbow(P.y * 0.022 - t * 0.35) * 0.9 + 0.1;\n"
    "    else\n"
    "    {\n"
    "        float sx2 = sx - 2.0, slot2 = floor(sx2 / 16.0);\n"
    "        int ch2 = DEMO_TEXT[int(mod(slot2, float(DEMO_TEXT.length())))];\n"
    "        float oy2 = floor(7.0 * sin(slot2 * 0.55 + t * 3.2));\n"
    "        int gx2 = int(floor((sx2 - slot2 * 16.0) / 2.0)), gy2 = int(floor((base + oy2 - P.y - 2.0) / 2.0));\n"
    "        if (gy2 >= 0 && gy2 < 8 && demoFontPixel(ch2, gx2, gy2)) col *= 0.25;\n"
    "    }\n"
    "    // a copper bar above and below the scroller\n"
    "    float cl = min(abs(P.y - (base - 26.0)), abs(P.y - (base + 10.0)));\n"
    "    if (cl < 2.0) col = demoRainbow(P.x * 0.004 + t * 0.15) * (1.0 - 0.35 * cl);\n"
    "\n"
    "    return 0.55 * amiga12(col);\n"
    "}\n"
    "\n"
    "// Hills (9): a 16-bit side-scroller landscape in layers, each moving slower the further away it\n"
    "// is: a sky with the sun, clouds near and far, birds, pale mountains far away and snowy ones nearer,\n"
    "// hills with bushes, trees, and grass with flowers. Drawn at 224 lines. hs: half the screen's size.\n"
    "// a pixel-art cloud: puffs on a flat base; 0 outside, 1 lit, 2 middle, 3 in shadow. a: from the\n"
    "// middle of its base, in pixels; k: its size\n"
    "float cloudSd(vec2 a, float k)\n"
    "{\n"
    "    return min(min(length(a - vec2(-12.0, 5.0) * k) - 7.5 * k, length(a - vec2(0.0, 9.0) * k) - 11.0 * k),\n"
    "               min(length(a - vec2(13.0, 5.0) * k) - 7.5 * k, length(a - vec2(-3.0, 4.0) * k) - 9.0 * k));\n"
    "}\n"
    "int cloudPix(vec2 a, float k)\n"
    "{\n"
    "    if (a.y < 0.0 || cloudSd(a, k) > 0.0) return 0;\n"
    "    if (a.y < 2.0 || cloudSd(a + vec2(-2.5, 2.5), k) > 0.0) return 3;   // the bottom and lower right\n"
    "    if (cloudSd(a + vec2(2.0, -2.5), k) > 0.0) return 1;                // the upper left catches the sun\n"
    "    return 2;\n"
    "}\n"
    "vec3 hills(vec2 fc, vec2 hs, float t, float pix)\n"
    "{\n"
    "    float n = pixSize(224.0, pix);\n"
    "    vec2 P = floor(fc / n);\n"
    "    float y = P.y + 0.5, L = 1.0 / (n * pix);\n"
    "    bool dt = mod(P.x + P.y, 2.0) < 1.0;\n"
    "    // the sky, in bands with dithered edges, and the sun at the upper left with rings of light\n"
    "    vec3 col = mix(rgb8(150.0, 205.0, 255.0), rgb8(48.0, 96.0, 208.0), clamp(floor((y + 40.0) / 19.0 + 0.4 * (bayer4(P) - 0.47)) / 7.0, 0.0, 1.0));\n"
    "    float sr = y > 0.5 * L - 60.0 ? length(vec2(P.x + 0.5 + hs.x * L - 44.0, y - 0.5 * L + 36.0)) : 99.0;\n"
    "    if (sr < 7.5) col = rgb8(255.0, 252.0, 228.0);\n"
    "    else if (sr < 9.5) col = dt ? rgb8(255.0, 244.0, 190.0) : col;\n"
    "    else if (abs(sr - 13.0) < 1.0 || (abs(sr - 17.5) < 1.0 && dt)) col = mix(col, rgb8(255.0, 250.0, 220.0), 0.35);\n"
    "    // clouds: small ones far away, moving slowly, and big ones nearer\n"
    "    for (int i = 0; i < 2; i++)\n"
    "    {\n"
    "        float W = i == 0 ? 70.0 : 110.0, k = i == 0 ? 0.55 : 1.0;\n"
    "        if (y < (i == 0 ? 61.0 : 29.0) || y > (i == 0 ? 101.0 : 86.0)) continue;\n"
    "        float x = layerX(fc.x, t, i == 0 ? 0.002 : 0.004, n, pix) + 0.5;\n"
    "        float c = floor(x / W), hc = hash13(vec3(c, float(i), 41.0));\n"
    "        if (hc < 0.35) continue;\n"
    "        int cp = cloudPix(vec2(x - c * W - 0.5 * W - (hc - 0.5) * 16.0, y - (i == 0 ? 62.0 : 30.0) - (i == 0 ? 26.0 : 34.0) * fract(hc * 7.0)), k);\n"
    "        if (cp > 0) col = cp == 1 ? rgb8(255.0, 255.0, 255.0) : cp == 2 ? rgb8(232.0, 240.0, 255.0) : rgb8(188.0, 204.0, 240.0);\n"
    "    }\n"
    "    // birds, far off, flapping slowly as they cross\n"
    "    if (y > 24.0 && y < 74.0)\n"
    "    for (int i = 0; i < 3; i++)\n"
    "    {\n"
    "        float h = hash13(vec3(float(i), 9.0, 44.0)), span = 2.0 * hs.x * L + 40.0;\n"
    "        vec2 bp = vec2(mod(h * span - t * (5.0 + 3.0 * h), span) - 0.5 * span, 28.0 + 40.0 * fract(h * 7.0) + 3.0 * sin(t * 0.5 + h * 9.0));\n"
    "        vec2 d = spritePix(fc, bp, n) - 0.5;\n"
    "        float up = mod(floor(t * 3.0 + h * 10.0), 2.0) < 1.0 ? 1.0 : -1.0;\n"
    "        if (abs(d.x) <= 2.0 && d.y == (abs(d.x) == 2.0 ? up : 0.0)) col = rgb8(44.0, 54.0, 96.0);\n"
    "    }\n"
    "    // mountains far away, pale in the haze\n"
    "    float x = layerX(fc.x, t, 0.006, n, pix) + 0.5;\n"
    "    float fh = -34.0 + 30.0 * (0.6 * (1.0 - abs(2.0 * noise1(x * 0.02 + 70.0) - 1.0)) + 0.4 * noise1(x * 0.07 + 90.0));\n"
    "    if (y < fh) col = y > fh - 1.0 ? rgb8(176.0, 186.0, 236.0) : rgb8(150.0, 162.0, 222.0);\n"
    "    // nearer mountains, cut in faces, lit from the left, snow on the high peaks\n"
    "    x = layerX(fc.x, t, 0.009, n, pix) + 0.5;\n"
    "    float W = 40.0, c = floor(x / W), f = x / W - c;\n"
    "    bool pk0 = mod(c, 2.0) < 0.5;                             // peaks and valleys take turns\n"
    "    float h0 = hash13(vec3(c, 2.0, 41.0)), h1 = hash13(vec3(c + 1.0, 2.0, 41.0));\n"
    "    float hp = 22.0 + 36.0 * (pk0 ? h0 : h1), hv = 6.0 + 8.0 * (pk0 ? h1 : h0);\n"
    "    float mh = -40.0 + mix(pk0 ? hp : hv, pk0 ? hv : hp, f);\n"
    "    if (y < mh)\n"
    "    {\n"
    "        bool litFace = !pk0;                                   // rising toward a peak on the right: faces left\n"
    "        col = litFace ? rgb8(124.0, 132.0, 204.0) : rgb8(92.0, 98.0, 168.0);\n"
    "        if (mod(x - (litFace ? 1.0 : -1.0) * y * 0.8, 11.0) < 1.0 && y < mh - 3.0 && hash13(vec3(floor(x / 11.0), c, 46.0)) > 0.4)\n"
    "            col = litFace ? rgb8(104.0, 112.0, 186.0) : rgb8(78.0, 82.0, 150.0);   // cracks in the rock\n"
    "        float snow = -40.0 + hp - 13.0 - 3.0 * abs(sin(x * 0.7)) - 2.0 * abs(sin(x * 1.9));\n"
    "        if (hp > 38.0 && y > snow) col = litFace ? rgb8(240.0, 244.0, 255.0) : rgb8(196.0, 206.0, 240.0);\n"
    "    }\n"
    "    // hills in stripes, with bushes along their tops\n"
    "    x = layerX(fc.x, t, 0.018, n, pix) + 0.5;\n"
    "    float hh = -52.0 + 9.0 * sin(x * 0.045) + 5.0 * sin(x * 0.11 + 1.3);\n"
    "    if (y < hh) col = y > hh - 2.0 ? rgb8(120.0, 205.0, 95.0) : mod(floor(y / 3.0), 2.0) < 0.5 ? rgb8(62.0, 150.0, 72.0) : rgb8(52.0, 134.0, 64.0);\n"
    "    if (abs(y - hh) < 8.0)\n"
    "    {\n"
    "        float bcell = floor(x / 9.0), hbsh = hash13(vec3(bcell, 6.0, 41.0));\n"
    "        vec2 bd = vec2(x - bcell * 9.0 - 4.5, y - (-52.0 + 9.0 * sin((bcell * 9.0 + 4.5) * 0.045) + 5.0 * sin((bcell * 9.0 + 4.5) * 0.11 + 1.3)));\n"
    "        if (hbsh > 0.55 && length(bd * vec2(1.0, 1.3)) < 3.2 && bd.y > -2.0) col = bd.y > 1.0 && bd.x < 0.0 ? rgb8(88.0, 176.0, 80.0) : rgb8(40.0, 112.0, 56.0);\n"
    "    }\n"
    "    // trees: round ones and pines\n"
    "    x = layerX(fc.x, t, 0.032, n, pix) + 0.5;\n"
    "    float tc = floor(x / 26.0), ht = hash13(vec3(tc, 3.0, 41.0));\n"
    "    if (ht > 0.2)\n"
    "    {\n"
    "        float cy = -66.0 + 6.0 * fract(ht * 7.0);\n"
    "        vec2 d = vec2(x - tc * 26.0 - 13.0 - (ht - 0.5) * 8.0, y - cy);\n"
    "        if (fract(ht * 31.0) < 0.6)\n"
    "        {\n"
    "            float r = 8.0 + 4.0 * fract(ht * 13.0);\n"
    "            if (abs(d.x) < 1.5 && d.y < 0.0 && d.y > -18.0) col = d.x < 0.0 ? rgb8(130.0, 84.0, 44.0) : rgb8(96.0, 60.0, 30.0);\n"
    "            float bl = length(d - vec2(0.0, 0.0)) - r;\n"
    "            if (bl < 0.0)\n"
    "            {\n"
    "                float l = -0.6 * d.x + 0.8 * d.y;\n"
    "                col = l > 0.45 * r ? rgb8(104.0, 184.0, 80.0) : l > -0.2 * r ? rgb8(58.0, 140.0, 62.0) : rgb8(32.0, 98.0, 46.0);\n"
    "                if (hash13(vec3(floor(d / 3.0), tc + 50.0)) > 0.8 && l > -0.2 * r) col = rgb8(104.0, 184.0, 80.0);   // clumps of leaves\n"
    "            }\n"
    "        }\n"
    "        else\n"
    "        {\n"
    "            float H = 26.0 + 10.0 * fract(ht * 13.0), yy = d.y + 18.0;   // a pine: tiers narrowing upward\n"
    "            float w = (H - yy) * 0.36 + 1.5 * mod(yy, 6.0) / 6.0;\n"
    "            if (abs(d.x) < 1.0 && yy > -2.0 && yy < 4.0) col = rgb8(96.0, 60.0, 30.0);\n"
    "            if (yy > 2.0 && yy < H && abs(d.x) < w) col = d.x < -0.3 * w ? rgb8(64.0, 136.0, 86.0) : rgb8(30.0, 92.0, 62.0);\n"
    "        }\n"
    "    }\n"
    "    // grass with tufts and flowers, earth with stones\n"
    "    x = layerX(fc.x, t, 0.05, n, pix) + 0.5;\n"
    "    float hx = hash13(vec3(floor(x), 4.0, 41.0));\n"
    "    float g = -84.0 + (hx > 0.6 ? 1.0 : 0.0) + (hx > 0.88 ? 1.0 : 0.0);\n"
    "    if (y < g)\n"
    "    {\n"
    "        col = y > g - 4.0 ? (y > g - 1.0 && hx > 0.75 ? rgb8(150.0, 220.0, 96.0) : rgb8(96.0, 196.0, 64.0)) : rgb8(150.0, 98.0, 52.0);\n"
    "        if (y < g - 4.0 && y > g - 6.0) col = rgb8(118.0, 76.0, 40.0);                    // the edge of the earth\n"
    "        vec2 sq = vec2(floor(x / 5.0), floor(y / 4.0)), sf = vec2(x - sq.x * 5.0, y - sq.y * 4.0);\n"
    "        if (y < g - 7.0 && hash13(vec3(sq, 42.0)) > 0.8)                                  // stones\n"
    "        {\n"
    "            if (sf.y > 2.0 && sf.x > 1.0 && sf.x < 4.0) col = rgb8(176.0, 150.0, 120.0);\n"
    "            else if (sf.y > 1.0 && sf.y < 2.0 && sf.x > 2.0 && sf.x < 4.0) col = rgb8(112.0, 70.0, 38.0);\n"
    "        }\n"
    "    }\n"
    "    float fl = hash13(vec3(floor(x), 5.0, 43.0));\n"
    "    if (fl > 0.96 && y >= g && y < g + 2.0)\n"
    "        col = y > g + 0.5 ? (fract(fl * 91.0) < 0.4 ? rgb8(255.0, 255.0, 255.0) : fract(fl * 91.0) < 0.7 ? rgb8(255.0, 220.0, 60.0) : rgb8(240.0, 80.0, 80.0))\n"
    "                          : rgb8(60.0, 150.0, 50.0);\n"
    "    return 0.45 * col;\n"
    "}\n"
    "\n"
    "// Night city (10): a skyline at night in three layers moving at their own speeds. A full moon\n"
    "// with a halo, stars, thin clouds drifting past, now and then a plane blinking across; far towers\n"
    "// in the haze, nearer ones with windows lighting up and going dark, rooftops in front with water\n"
    "// tanks, antennas with red lights and a hotel sign, cars passing on the street below. Drawn at\n"
    "// 224 lines. hs: half the screen's size.\n"
    "const uint CITY_FONT[5] = uint[5](0x5BEDu, 0x7B6Fu, 0x7492u, 0x79A7u, 0x4927u);   // H O T E L, 3x5, rows from the top\n"
    "vec3 city(vec2 fc, vec2 hs, float t, float pix)\n"
    "{\n"
    "    float n = pixSize(224.0, pix);\n"
    "    float yi = floor(fc.y / n), y = yi + 0.5, sx = floor(fc.x / n);\n"
    "    vec2 P = vec2(sx, yi);\n"
    "    float L = 1.0 / (n * pix);\n"
    "    bool dt = mod(sx + yi, 2.0) < 1.0;\n"
    "    // the sky: deep blue high up, purple lower, warm near the horizon from the city's lights\n"
    "    vec3 col = mix(rgb8(64.0, 36.0, 96.0), rgb8(6.0, 8.0, 34.0), clamp(floor((y + 40.0) / 19.0 + 0.4 * (bayer4(P) - 0.47)) / 7.0, 0.0, 1.0));\n"
    "    if (y < -20.0 && (y < -30.0 || dt)) col = mix(col, rgb8(110.0, 52.0, 90.0), 0.35);\n"
    "    // stars, fewer low down where the city's light hides them\n"
    "    float hsr = hash13(vec3(sx, yi, 51.0));\n"
    "    if (y > 10.0 && hsr > 0.996 - 0.002 * smoothstep(10.0, 90.0, y)) col = rgb8(200.0, 200.0, 255.0) * (0.7 + 0.3 * sin(t * 2.0 + hsr * 900.0));\n"
    "    // the moon, right of the monitor: shaded toward its edge, darker seas, a faint halo\n"
    "    vec2 m = vec2(sx + 0.5 - 118.0, y - 66.0);\n"
    "    float mr = length(m);\n"
    "    if (mr < 24.0 && (abs(mr - 17.0) < 1.0 || (mr < 23.0 && mr > 14.0 && dt && mr < 19.0))) col = mix(col, rgb8(120.0, 110.0, 150.0), 0.35);\n"
    "    if (mr < 12.0)\n"
    "    {\n"
    "        float sea = valueNoise(m * 0.35 + 3.0) + 0.5 * valueNoise(m * 0.8 + 9.0);\n"
    "        col = sea > 0.95 ? rgb8(200.0, 194.0, 170.0) : rgb8(245.0, 238.0, 205.0);\n"
    "        if (mr > 10.5 && dt) col = rgb8(215.0, 208.0, 180.0);\n"
    "        if (mr > 11.2) col = rgb8(215.0, 208.0, 180.0);\n"
    "    }\n"
    "    // thin clouds drifting past, dark, lit along their tops by the moon\n"
    "    float cx = layerX(fc.x, t, 0.0067, n, pix), cy = y - 40.0;\n"
    "    for (int i = 0; i < 2; i++)\n"
    "    {\n"
    "        float cy2 = cy - float(i) * 34.0 + 10.0;\n"
    "        float cc = floor((cx + float(i) * 73.0) / 120.0), hc = hash13(vec3(cc, float(i), 57.0));\n"
    "        float u = (cx + float(i) * 73.0 - cc * 120.0) / (50.0 + 50.0 * hc);\n"
    "        float th = 3.5 * sqrt(max(1.0 - (2.0 * u - 1.0) * (2.0 * u - 1.0), 0.0)) + 1.5 * sin(u * 9.0 + hc * 5.0);\n"
    "        if (hc > 0.3 && u < 1.0 && abs(cy2 - 3.0 * hc) < th)\n"
    "            col = cy2 - 3.0 * hc > th - 1.0 ? rgb8(100.0, 84.0, 130.0) : rgb8(42.0, 30.0, 70.0);\n"
    "    }\n"
    "    // now and then a plane, high up, its lights blinking\n"
    "    float span = 2.0 * hs.x * L + 60.0, pc = floor(t / 70.0);\n"
    "    vec2 pp = vec2(mix(-0.5 * span, 0.5 * span, fract(t / 70.0)), 0.5 * L - 8.0 - 12.0 * hash13(vec3(pc, 1.0, 58.0)));\n"
    "    vec2 pd = spritePix(fc, pp, n) - 0.5;\n"
    "    if (hash13(vec3(pc, 2.0, 58.0)) > 0.3)\n"
    "    {\n"
    "        if (pd.y == 0.0 && pd.x >= -2.0 && pd.x <= 2.0) col = rgb8(70.0, 70.0, 90.0);\n"
    "        if (pd.y == 0.0 && pd.x == 2.0 && fract(t * 0.9) < 0.15) col = rgb8(255.0, 255.0, 255.0);\n"
    "        if (pd.y == -1.0 && pd.x == 0.0 && fract(t * 0.7 + 0.5) < 0.5) col = rgb8(255.0, 60.0, 50.0);\n"
    "    }\n"
    "    // far towers, in the haze, a few dim windows, some with a spire\n"
    "    float x = layerX(fc.x, t, 0.006, n, pix);\n"
    "    float b = floor(x / 22.0), lx = x - b * 22.0;\n"
    "    float bw = floor(13.0 + 8.0 * hash13(vec3(b, 1.0, 52.0))), top = floor(-20.0 + 55.0 * hash13(vec3(b, 2.0, 52.0)));\n"
    "    if (lx < bw && yi < top)\n"
    "    {\n"
    "        col = mix(rgb8(34.0, 32.0, 70.0), rgb8(60.0, 44.0, 84.0), clamp((-yi - 40.0) / 50.0, 0.0, 1.0));\n"
    "        if (mod(lx, 3.0) == 1.0 && mod(top - yi, 3.0) == 2.0 && hash13(vec3(b * 31.0 + lx, yi, 53.0)) > 0.8) col = rgb8(130.0, 120.0, 80.0);\n"
    "    }\n"
    "    if (hash13(vec3(b, 3.0, 52.0)) > 0.7 && lx == floor(bw * 0.5) && yi >= top && yi < top + 6.0) col = rgb8(40.0, 38.0, 74.0);\n"
    "    // nearer buildings: windows that light up and go dark; flat roofs, steps or a pointed top\n"
    "    x = layerX(fc.x, t, 0.014, n, pix);\n"
    "    b = floor(x / 32.0); lx = x - b * 32.0;\n"
    "    float w = floor(20.0 + 11.0 * hash13(vec3(b, 1.0, 54.0))), hb2 = hash13(vec3(b, 3.0, 54.0));\n"
    "    top = floor(-40.0 + 60.0 * hash13(vec3(b, 2.0, 54.0)));\n"
    "    float roof = top;\n"
    "    if (hb2 > 0.7) roof = top + 3.0 * floor(min(lx, w - 1.0 - lx) / (0.25 * w));          // steps\n"
    "    else if (hb2 > 0.5) roof = top + floor(min(lx, w - 1.0 - lx) * 0.6);                   // a pointed top\n"
    "    if (lx < w && yi < roof)\n"
    "    {\n"
    "        col = lx < 2.0 ? rgb8(26.0, 26.0, 52.0) : rgb8(18.0, 18.0, 40.0);\n"
    "        float wy = top - yi;\n"
    "        if (mod(lx, 4.0) >= 1.0 && mod(lx, 4.0) <= 2.0 && lx < w - 1.0 && mod(wy, 5.0) >= 2.0 && mod(wy, 5.0) <= 3.0 && wy > 1.0)\n"
    "        {\n"
    "            vec3 id = vec3(b * 17.0 + floor(lx / 4.0), floor(wy / 5.0), 55.0);\n"
    "            float h = hash13(id);\n"
    "            if (hash13(id + floor(t / (8.0 + 20.0 * h) + h)) > 0.55)\n"
    "                col = 0.7 * (fract(h * 11.0) > 0.25 ? rgb8(255.0, 214.0, 130.0) : rgb8(150.0, 205.0, 255.0));\n"
    "        }\n"
    "    }\n"
    "    // rooftops in front: walls with lit windows, water tanks, boxes, antennas with red lights,\n"
    "    // and on some a hotel sign, its letters glowing (one of them flickers now and then)\n"
    "    x = layerX(fc.x, t, 0.03, n, pix);\n"
    "    b = floor(x / 44.0); lx = x - b * 44.0;\n"
    "    float hb = hash13(vec3(b, 1.0, 56.0)), hk = hash13(vec3(b, 4.0, 56.0));\n"
    "    float fw = floor(34.0 + 10.0 * hk);\n"
    "    top = floor(-74.0 + 24.0 * hb);\n"
    "    if (lx < fw && yi < top)\n"
    "    {\n"
    "        col = yi > top - 2.0 ? rgb8(40.0, 38.0, 60.0) : rgb8(12.0, 12.0, 24.0);\n"
    "        float wy = top - yi - 4.0;\n"
    "        if (wy > 0.0 && mod(lx, 6.0) >= 2.0 && mod(lx, 6.0) < 4.0 && mod(wy, 7.0) >= 2.0 && mod(wy, 7.0) < 5.0 && lx < fw - 2.0)\n"
    "        {\n"
    "            vec3 id = vec3(b * 13.0 + floor(lx / 6.0), floor(wy / 7.0), 59.0);\n"
    "            float h = hash13(id);\n"
    "            if (hash13(id + floor(t / (12.0 + 30.0 * h) + h)) > 0.6) col = 0.75 * (fract(h * 7.0) > 0.3 ? rgb8(255.0, 200.0, 120.0) : rgb8(170.0, 220.0, 255.0));\n"
    "        }\n"
    "    }\n"
    "    float dyr = yi - top;                                     // above the roof\n"
    "    if (lx < fw && dyr >= 0.0)\n"
    "    {\n"
    "        if (hb > 0.5 && lx == 22.0 && dyr < 12.0) col = rgb8(40.0, 40.0, 52.0);\n"
    "        if (hb > 0.5 && lx == 22.0 && dyr == 12.0 && fract(t * 0.8 + hb * 7.0) < 0.5) col = rgb8(255.0, 40.0, 30.0);\n"
    "        if (hk > 0.45)                                        // a water tank on legs\n"
    "        {\n"
    "            float tx = lx - 6.0 - 6.0 * fract(hk * 9.0);\n"
    "            if ((tx == 0.0 || tx == 6.0) && dyr < 3.0) col = rgb8(30.0, 30.0, 44.0);\n"
    "            if (tx >= 0.0 && tx <= 6.0 && dyr >= 3.0 && dyr < 10.0 - (tx < 1.0 || tx > 5.0 ? 1.0 : 0.0)) col = tx < 2.0 ? rgb8(52.0, 46.0, 66.0) : rgb8(30.0, 28.0, 44.0);\n"
    "            if (tx >= 1.0 && tx <= 5.0 && dyr == 10.0) col = rgb8(30.0, 28.0, 44.0);\n"
    "        }\n"
    "        if (fract(hk * 23.0) > 0.5 && lx > fw - 12.0 && lx < fw - 6.0 && dyr < 3.0) col = dyr > 1.0 ? rgb8(52.0, 52.0, 70.0) : rgb8(30.0, 30.0, 44.0);\n"
    "    }\n"
    "    if (fract(hb * 37.0) < 0.22 && top > -66.0)              // the hotel sign, upright on the wall\n"
    "    {\n"
    "        vec2 q = vec2(lx - fw + 9.0, top - 6.0 - yi);\n"
    "        if (q.x >= 0.0 && q.x < 5.0 && q.y >= 0.0 && q.y < 31.0)\n"
    "        {\n"
    "            col = rgb8(24.0, 14.0, 30.0);\n"
    "            float li = floor((q.y - 1.0) / 6.0), ly = q.y - 1.0 - li * 6.0, lc = q.x - 1.0;\n"
    "            bool on = li != 2.0 || fract(t * 0.05 + hb * 3.0) > 0.06 || fract(t * 7.0) < 0.5;\n"
    "            if (li >= 0.0 && li < 5.0 && ly < 5.0 && lc >= 0.0 && lc < 3.0 && on &&\n"
    "                ((CITY_FONT[int(li)] >> uint((4.0 - ly) * 3.0 + 2.0 - lc)) & 1u) == 1u)\n"
    "                col = rgb8(255.0, 90.0, 140.0);\n"
    "        }\n"
    "        else if (q.x >= -2.0 && q.x < 7.0 && q.y >= -2.0 && q.y < 33.0 && yi < top) col = dt ? mix(rgb8(12.0, 12.0, 24.0), rgb8(255.0, 90.0, 140.0), 0.25) : rgb8(12.0, 12.0, 24.0);\n"
    "    }\n"
    "    // the street at the bottom: cars, white lights going right, red ones going left\n"
    "    if (yi < -0.5 * L + 5.0)\n"
    "    {\n"
    "        col = rgb8(10.0, 10.0, 18.0);\n"
    "        float lane = yi < -0.5 * L + 2.0 ? 0.0 : 1.0;\n"
    "        float cxp = layerX(fc.x, t, lane < 0.5 ? -0.09 : 0.09, n, pix), cc = floor(cxp / 37.0), hc = hash13(vec3(cc, lane, 60.0));\n"
    "        float u = cxp - cc * 37.0;\n"
    "        if (hc > 0.5 && mod(yi, 3.0) < 1.0 && (u == 3.0 || u == 7.0)) col = lane < 0.5 ? rgb8(255.0, 240.0, 200.0) : rgb8(255.0, 40.0, 40.0);\n"
    "    }\n"
    "    return 0.6 * col;\n"
    "}\n"
    "\n"
    "// Arcade carpet (11): neon shapes on black, like the carpets of 90s arcades and bowling alleys,\n"
    "// glowing as under black light, drifting slowly: planets with rings, stars, moons, lightning,\n"
    "// spirals, squiggles and more, some in two colours, with confetti in the pile between them.\n"
    "float sdBox(vec2 p, vec2 b) { vec2 d = abs(p) - b; return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0); }\n"
    "vec3 carpet(vec2 s, float t, float pix)\n"
    "{\n"
    "    const float C = 0.14;                                     // the pattern's cell, in screen heights\n"
    "    const vec3 NEON[6] = vec3[6](vec3(1.0, 0.1, 0.6), vec3(0.1, 0.9, 1.0), vec3(1.0, 0.9, 0.1),\n"
    "                                 vec3(0.45, 1.0, 0.1), vec3(1.0, 0.45, 0.05), vec3(0.65, 0.25, 1.0));\n"
    "    vec2 qd = s + floor(t * vec2(0.012, 0.007) / pix) * pix;   // drifting, in whole screen pixels\n"
    "    vec2 q = qd;\n"
    "    q.x += 0.5 * C * mod(floor(q.y / C), 2.0);\n"
    "    vec2 id = floor(q / C), f = q / C - id - 0.5;\n"
    "    float pc = pix / C;\n"
    "    float h1 = hash13(vec3(id, 21.0)), h2 = hash13(vec3(id, 22.0)), h3 = hash13(vec3(id, 23.0));\n"
    "    float ca = cos(h2 * TAU), sa = sin(h2 * TAU);\n"
    "    vec2 pq = mat2(ca, sa, -sa, ca) * (f - (vec2(h3, fract(h3 * 7.0)) - 0.5) * 0.12);\n"
    "    int kind = int(h1 * 10.0);\n"
    "    float d = 1e9, d2 = 1e9, fill = 0.0, fill2 = 0.0;     // the outline and fill in the first colour, then the second\n"
    "    if (kind == 0)\n"
    "    {\n"
    "        // a planet with a ring, the ring's far side hidden behind the planet\n"
    "        float pl = length(pq) - 0.11;\n"
    "        float rg = abs(length(pq * vec2(1.0, 3.2)) - 0.25) / 2.2;\n"
    "        d = abs(pl);\n"
    "        fill = step(pl, 0.0);\n"
    "        d2 = pl < 0.01 && pq.y > 0.0 ? 1e9 : rg;\n"
    "        if (rg < 0.03 && pq.y < 0.0) d = max(d, 0.03);         // the near side passes in front\n"
    "    }\n"
    "    else if (kind == 1)\n"
    "    {\n"
    "        float st = sdStar5(pq, 0.2, 0.45);                     // a star\n"
    "        d = abs(st);\n"
    "        fill = step(st, 0.0);\n"
    "    }\n"
    "    else if (kind == 2)\n"
    "    {\n"
    "        for (int i = -3; i <= 3; i++)                         // a squiggle: the nearest of a few points on it, then closer\n"
    "        {\n"
    "            float x = clamp(pq.x + 0.03 * float(i), -0.26, 0.26);\n"
    "            d = min(d, length(pq - vec2(x, 0.06 * sin(x * 24.0))));\n"
    "        }\n"
    "    }\n"
    "    else if (kind == 3)\n"
    "    {\n"
    "        d = abs(sdTriangle(pq, 0.17));                        // a triangle with a smaller one inside\n"
    "        d2 = abs(sdTriangle(pq, 0.07));\n"
    "    }\n"
    "    else if (kind == 4)\n"
    "    {\n"
    "        d = abs(length(pq) - 0.17);                            // a ring with a dot\n"
    "        d2 = max(length(pq) - 0.045, 0.0);\n"
    "        fill2 = step(length(pq), 0.045);\n"
    "    }\n"
    "    else if (kind == 5)\n"
    "    {\n"
    "        d = min(min(length(pq - vec2(-0.14, 0.05)), length(pq - vec2(0.12, 0.1))), length(pq - vec2(0.02, -0.13))) - 0.045;\n"
    "        fill = step(d, 0.0);                                   // three dots\n"
    "        d = abs(d);\n"
    "    }\n"
    "    else if (kind == 6)\n"
    "        d = min(min(segPix(pq, vec2(-0.07, 0.21), vec2(0.06, 0.03)), segPix(pq, vec2(0.06, 0.03), vec2(-0.05, 0.01))),\n"
    "                segPix(pq, vec2(-0.05, 0.01), vec2(0.08, -0.2)));   // a flash of lightning\n"
    "    else if (kind == 7)\n"
    "    {\n"
    "        float mo = max(length(pq) - 0.16, -(length(pq - vec2(0.07, 0.05)) - 0.13));   // a crescent moon and a little star\n"
    "        d = abs(mo);\n"
    "        fill = step(mo, 0.0);\n"
    "        float st = sdStar5(pq - vec2(0.1, 0.12), 0.055, 0.45);\n"
    "        d2 = abs(st);\n"
    "        fill2 = step(st, 0.0);\n"
    "    }\n"
    "    else if (kind == 8)\n"
    "        d = abs(min(sdBox(pq, vec2(0.17, 0.04)), sdBox(pq, vec2(0.04, 0.17))));   // a cross\n"
    "    else\n"
    "    {\n"
    "        float r = length(pq), k = (r / 0.03 - atan(pq.y, pq.x)) / TAU;   // a spiral\n"
    "        d = max(abs(fract(k + 0.5) - 0.5) * TAU * 0.03, r - 0.19);\n"
    "    }\n"
    "    int ni = int(fract(h1 * 13.0) * 6.0);\n"
    "    vec3 neon = NEON[ni], neon2 = NEON[int(mod(float(ni) + 2.0 + floor(h3 * 3.0), 6.0))];\n"
    "    float fib = hash13(vec3(floor(qd / (2.0 * pix)), 30.0));  // the carpet's fibres\n"
    "    vec3 col = vec3(0.006, 0.004, 0.012) * (0.6 + 0.8 * fib);\n"
    "    float win = smoothstep(0.5, 0.38, max(abs(f.x), abs(f.y)));   // the glow ends inside the cell\n"
    "    col += neon * (0.55 * smoothstep(0.018 + pc, 0.018 - pc, d) + 0.18 * win * exp(-d / 0.04) + 0.1 * fill) * (0.8 + 0.4 * fib);\n"
    "    col += neon2 * (0.55 * smoothstep(0.016 + pc, 0.016 - pc, d2) + 0.15 * win * exp(-d2 / 0.04) + 0.1 * fill2) * (0.8 + 0.4 * fib);\n"
    "    // confetti in the pile between the shapes: short dashes and little triangles\n"
    "    vec2 cq = qd / 0.045 + 0.37, cid = floor(cq), cf = fract(cq) - 0.5;\n"
    "    float hc = hash13(vec3(cid, 26.0));\n"
    "    if (hc > 0.83 && min(d, d2) > 0.09)\n"
    "    {\n"
    "        float cb = fract(hc * 17.0) * TAU;\n"
    "        vec2 cr = mat2(cos(cb), sin(cb), -sin(cb), cos(cb)) * (cf - (vec2(fract(hc * 3.0), fract(hc * 5.0)) - 0.5) * 0.3);\n"
    "        float cd = fract(hc * 29.0) < 0.6 ? sdBox(cr, vec2(0.2, 0.05)) : sdTriangle(cr, 0.13);\n"
    "        float cp = pix / 0.045;\n"
    "        col += NEON[int(fract(hc * 41.0) * 6.0)] * 0.24 * smoothstep(cp, -cp, cd) * (0.8 + 0.4 * fib);\n"
    "    }\n"
    "    // specks of colour in the pile\n"
    "    float hsp = hash13(vec3(floor(qd / 0.012), 24.0));\n"
    "    if (hsp > 0.985) col += NEON[int(fract(hsp * 31.0) * 6.0)] * 0.25 * smoothstep(0.35, 0.2, length(fract(qd / 0.012) - 0.5));\n"
    "    return col;\n"
    "}\n"
    "\n"
    "// Around the tube 2-11: the scene behind the monitor. hs: half the screen's size in screen heights.\n"
    "vec3 scene(int k, vec2 s, vec2 fc, vec2 hs, float t, float pix)\n"
    "{\n"
    "    if (k == 2) return space(s, t, pix);\n"
    "    if (k == 3) return synthwave(s, hs, t, pix);\n"
    "    if (k == 4) return tiles(fc, t, pix);\n"
    "    if (k == 5) return bounceLines(s, hs, t, pix);\n"
    "    if (k == 6) return underwater(fc, hs, t, pix);\n"
    "    if (k == 7) return copper(fc, hs, t, pix);\n"
    "    if (k == 8) return amigaDemo(fc, hs, t, pix);\n"
    "    if (k == 9) return hills(fc, hs, t, pix);\n"
    "    if (k == 10) return city(fc, hs, t, pix);\n"
    "    return carpet(s, t, pix);\n"
    "}\n"
    "\n"
    "// The colour of the light a scene casts on the casing (Room light sets how much).\n"
    "vec3 sceneLight(int k, float t)\n"
    "{\n"
    "    if (k == 2) return vec3(0.96, 0.98, 1.0);                 // space: white, like sunlight\n"
    "    if (k == 3) return vec3(1.0, 0.72, 0.95);                 // synthwave: pink, like its sun\n"
    "    if (k == 4) return tilesLight(t);\n"
    "    if (k == 5) return vec3(0.85, 0.9, 1.0);\n"
    "    if (k == 6) return vec3(0.7, 0.9, 1.0);                   // underwater: blue-green\n"
    "    if (k == 7) return vec3(1.0, 0.85, 0.9);\n"
    "    if (k == 8) return vec3(0.85, 0.85, 1.0);                 // Amiga demo\n"
    "    if (k == 9) return vec3(1.0, 0.98, 0.92);\n"
    "    if (k == 10) return vec3(0.72, 0.76, 1.0);\n"
    "    return vec3(0.82, 0.6, 1.0);                              // carpet: black light\n"
    "}\n"
    "\n"
    "// What is around the tube (Around the tube), drawn where the glass ends. Linear light, like the\n"
    "// picture. c: tube position (-1..1, after curvature); dist, qq: how far outside the tube edge, in\n"
    "// the same units; tc: position on the tube before curvature (0..1); tubePx: tube size in pixels.\n"
    "// Sizes are in mm (the tube is Monitor size), so the casing is as large as the real one.\n"
    "vec3 backdrop(vec2 c, float dist, vec2 qq, vec2 tc, vec2 tubePx)\n"
    "{\n"
    "    vec2 tube = monTubeMM();\n"
    "    float mmpp = tube.y / tubePx.y;                               // mm per screen pixel\n"
    "    float aa = mmpp;                                              // one screen pixel\n"
    "    vec2 p = (tc - 0.5) * tubePx * mmpp;                          // mm from the tube centre\n"
    "    int scn = int(LR_BACKDROP + 0.5);                      // 1 a room, 2 and up a scene\n"
    "    bool inScene = scn >= 2;\n"
    "    float t = float(LR_FrameCount % 1000000u) / 60.0 * LR_SCENE_SPEED;   // the scenes' clock\n"
    "\n"
    "    // The casing, measured on photos of real monitors.\n"
    "    // Amiga monitor (Commodore M1438S): warm off-white, a thick flat front, a 12.5 mm tunnel with\n"
    "    //   mitred corners down to a thin black mask at the glass, a plain chin, a green light.\n"
    "    // PC monitor (Compaq 151FS): aged cream, a wide front, a raised rim around a shallower\n"
    "    //   recess, a blank plaque on the chin, a control strip below with buttons and a green light.\n"
    "    // TV (after photos of 90s TVs): dark grey plastic, thin sides, the glass almost flush with\n"
    "    //   the front, a tall chin with speaker grilles on both sides of the controls; sized to the\n"
    "    //   tube (Monitor size), since TVs came from 14 to 29 inches.\n"
    "    // Margins from the glass to the outline (side, top, bottom), recess width (with the mask),\n"
    "    // mask width, the shell band around the front, corner radii of the outline and the recess.\n"
    "    bool tv = !inMM(vTiming.x);\n"
    "    bool amiga = !tv && LR_MON_MM > 0.5;\n"
    "    bool pc = !tv && !amiga;\n"
    "    vec3 m = amiga ? vec3(41.0, 41.0, 48.0) : pc ? vec3(44.0, 46.0, 39.0) : vec3(0.11, 0.13, 0.34) * tube.y;\n"
    "    float rw = amiga ? 12.5 : pc ? 12.0 : max(0.03 * tube.y, 5.0), mw = tv ? 1.0 : 1.2, sh = amiga ? 4.0 : 3.0;\n"
    "    float ro = tv ? 0.05 * tube.y : 7.0, rr = amiga ? 2.0 : tv ? 0.04 * tube.y : 6.0;\n"
    "    vec3 albedo = amiga ? vec3(0.60, 0.56, 0.44) : pc ? vec3(0.66, 0.57, 0.33) : vec3(0.07, 0.07, 0.075);\n"
    "\n"
    "    // the light: the room's (Room light: 1 a dim room with warm lamps, 20 daylight, whiter and\n"
    "    // more even), brightest near the monitor. In a scene as much light as Room light gives, even,\n"
    "    // in the scene's colour (white in space, pink in the synthwave scene, like its sun), so the\n"
    "    // monitor shows in front of it.\n"
    "    float day = smoothstep(1.0, 20.0, LR_ROOM);\n"
    "    float near = mix(1.0 / (1.0 + dot(p, p) / (260.0 * 260.0)), 1.0, inScene ? 1.0 : 0.6 * day);\n"
    "    vec3 light = (inScene ? sceneLight(scn, t) : mix(vec3(1.0, 0.93, 0.82), vec3(1.0), day))\n"
    "               * (0.0167 * LR_ROOM * near);\n"
    "\n"
    "    vec2 inner = 0.5 * tube;\n"
    "    float d = dist * mix(1.0, tubePx.x / tubePx.y, smoothstep(-0.05, 0.05, qq.x - qq.y)) * 0.5 * tube.y;   // mm from the glass\n"
    "    vec2 hs = inner + vec2(m.x, 0.5 * (m.y + m.z));               // half size of the outline\n"
    "    vec2 at = p - vec2(0.0, 0.5 * (m.y - m.z));                   // from the centre of the outline\n"
    "    float s = roundBox(at, hs, ro);                               // < 0 on the casing\n"
    "    float u = -roundBox(p, inner + rw, rr);                       // > 0 in the recess\n"
    "    float rec = smoothstep(-aa, aa, u);\n"
    "\n"
    "    // Which way the surface faces. Away from the glass: rounded corners, mitred on the Amiga.\n"
    "    vec2 nIn = boxOut(p, inner, 6.0);\n"
    "    if (amiga)\n"
    "    {\n"
    "        vec2 e = abs(p) - inner;\n"
    "        nIn = normalize(mix(vec2(0.0, sign(p.y)), vec2(sign(p.x), 0.0), smoothstep(-aa, aa, e.x - e.y)));\n"
    "    }\n"
    "    float phi;                                                    // < 0 toward the glass, > 0 outward\n"
    "    vec2 dir = nIn;\n"
    "    if (u > -5.0)\n"
    "    {\n"
    "        // a rounded lip, then the walls down to the glass: steep on the Amiga monitor (55 degrees),\n"
    "        // shallower on the PC monitor (45 degrees) and the TV (40 degrees, a narrow chamfer)\n"
    "        phi = (amiga ? -0.96 : pc ? -0.79 : -0.70) * smoothstep(-0.6, 1.2, u);\n"
    "    }\n"
    "    else\n"
    "    {\n"
    "        // the front's edge rolls over to a seam, then the casing's shell rolls away\n"
    "        dir = boxOut(at, hs, ro);\n"
    "        phi = s < -sh ? 0.87 * smoothstep(-sh - 2.0, -sh, s) : mix(0.44, 1.4, smoothstep(-1.5, 0.0, s));\n"
    "    }\n"
    "    vec3 n = tilt(dir, phi);\n"
    "    if (pc)              // the top of the front slopes back a little\n"
    "        n = normalize(n + vec3(0.0, 0.25 * smoothstep(inner.y + rw + 12.0, inner.y + m.y - sh, p.y), 0.0));\n"
    "\n"
    "    // less of the room's light gets into the recess, least near the glass; the seam is dark;\n"
    "    // the mask next to the glass is black\n"
    "    float occ = (1.0 - rec * (0.05 + 0.15 * smoothstep(0.0, rw, u)))\n"
    "              * (1.0 - 0.6 * exp(-0.5 * (s + sh) * (s + sh) / max(0.16, aa * aa)));\n"
    "    vec3 alb = albedo * mix(1.0, 0.92, rec);\n"
    "    if (!tv)             // the plastic has aged a little unevenly\n"
    "        alb *= 1.0 - 0.03 * valueNoise(p / 30.0 + 7.0);\n"
    "    float gloss = tv ? 0.6 : 0.5;\n"
    "    alb = mix(alb, vec3(0.02), 1.0 - smoothstep(mw - aa, mw + aa, d));\n"
    "\n"
    "    vec3 lamp = vec3(0.0);                                        // the power light\n"
    "    vec3 stripCol = vec3(0.0);\n"
    "    float strip = 0.0;\n"
    "    float yb = -inner.y - m.z;                                    // bottom of the outline\n"
    "    if (pc)\n"
    "    {\n"
    "        // a blank pill-shaped plaque on the chin, left: a grey raised rim around a light face\n"
    "        vec2 pq = p - vec2(-0.406 * tube.x, -inner.y - rw - 12.0);\n"
    "        float pd = pill(pq, 20.5, 7.5);\n"
    "        if (pd < 1.5)\n"
    "        {\n"
    "            vec2 pdir = normalize(vec2(sign(pq.x) * max(abs(pq.x) - 20.5, 0.0), pq.y) + 1e-4);\n"
    "            float on = 1.0 - smoothstep(-aa, aa, pd);\n"
    "            float rim = on * smoothstep(-1.5 - aa, -1.5 + aa, pd);\n"
    "            n = normalize(mix(n, tilt(pdir, 0.6), rim));\n"
    "            alb = mix(alb, mix(vec3(0.86, 0.84, 0.79), vec3(0.55, 0.55, 0.56), rim), on);\n"
    "            gloss = mix(gloss, min(gloss + 0.3, 1.0), on);   // the plaque is glossier\n"
    "            occ *= 1.0 - 0.35 * (1.0 - on) * (1.0 - smoothstep(0.0, 1.5, pd)) * max(-pdir.y, 0.0);   // its shadow below\n"
    "        }\n"
    "\n"
    "        // the control strip, a separate part under the front: a recessed panel in the middle,\n"
    "        // the power light and two buttons on the right, seams between the parts\n"
    "        vec2 sp = p - vec2(0.0, yb - 6.0);\n"
    "        strip = 1.0 - smoothstep(-aa, aa, roundBox(sp, vec2(110.5, 7.0), 2.0));\n"
    "        if (strip > 0.0)\n"
    "        {\n"
    "            float sphi = 0.0;\n"
    "            vec2 sdir = vec2(0.0, 1.0);\n"
    "            float pan = roundBox(sp - vec2(8.5, -0.5), vec2(50.5, 4.5), 1.0);\n"
    "            if (pan < 0.0)\n"
    "            {\n"
    "                sdir = boxOut(sp - vec2(8.5, -0.5), vec2(50.5, 4.5), 1.0);\n"
    "                sphi = -0.8 * smoothstep(-1.0, 0.0, pan);         // its walls face inward\n"
    "            }\n"
    "            for (int k = 0; k < 2; k++)\n"
    "            {\n"
    "                vec2 bc = vec2(k == 0 ? 85.5 : 102.25, -0.5);\n"
    "                vec2 bh = vec2(k == 0 ? 7.5 : 7.25, 4.5);\n"
    "                float bd = roundBox(sp - bc, bh, 0.8);\n"
    "                if (bd < 0.0)\n"
    "                {\n"
    "                    sdir = boxOut(sp - bc, bh, 0.8);\n"
    "                    sphi = 0.6 * smoothstep(-0.8, 0.0, bd);        // bevelled buttons\n"
    "                }\n"
    "            }\n"
    "            float seam = 0.0;\n"
    "            for (int k = 0; k < 4; k++)\n"
    "            {\n"
    "                float x0 = k == 0 ? -42.0 : k == 1 ? 59.0 : k == 2 ? 77.0 : 94.0;\n"
    "                seam = max(seam, exp(-0.5 * (sp.x - x0) * (sp.x - x0) / max(0.09, aa * aa)));\n"
    "            }\n"
    "            float socc = mix(0.7, 1.0, smoothstep(5.0, 2.5, sp.y))    // in the shadow of the front above\n"
    "                       * (1.0 - 0.6 * seam);\n"
    "            stripCol = plastic(albedo * 0.97, tilt(sdir, sphi), vec3(p, 0.0), light, socc, 0.5);\n"
    "            float ld = roundBox(sp - vec2(70.0, -0.5), vec2(1.2, 0.6), 0.3);\n"
    "            lamp += vec3(0.12, 1.0, 0.2) * (0.6 * (1.0 - smoothstep(-aa, aa, ld)) + 0.03 * exp(-0.5 * max(ld, 0.0) * max(ld, 0.0) / 9.0)) * strip;\n"
    "        }\n"
    "    }\n"
    "    else if (tv)\n"
    "    {\n"
    "        // The TV's chin: a band set a little into the front, with a speaker grille on each side\n"
    "        // and the controls between them: the power switch, the red light, four small buttons.\n"
    "        float h = tube.y;\n"
    "        float top = -inner.y - rw - 0.07 * h, bot = yb + 0.035 * h;\n"
    "        vec2 bc = vec2(0.0, 0.5 * (top + bot)), bh = vec2(hs.x - 0.04 * h, 0.5 * (top - bot));\n"
    "        float bd = roundBox(p - bc, bh, 2.0);\n"
    "        float band = 1.0 - smoothstep(-aa, aa, bd);\n"
    "        float panel = 0.36 * hs.x;                                // half width of the controls\n"
    "        occ *= (1.0 - 0.6 * exp(-0.5 * bd * bd / max(0.2, aa * aa)))                       // its seam\n"
    "             * (1.0 - 0.3 * band * (1.0 - smoothstep(0.0, 2.5, bh.y - (p.y - bc.y))))     // shadow at its top\n"
    "             * (1.0 - 0.5 * band * exp(-0.5 * (abs(p.x) - panel) * (abs(p.x) - panel) / max(0.2, aa * aa)));\n"
    "        alb *= mix(1.0, 0.85, band);\n"
    "        // the grilles: holes 1.2 mm wide, 2.2 mm apart (seen as an even darker grey when they are\n"
    "        // smaller than a pixel)\n"
    "        float grill = (1.0 - smoothstep(-2.0 - aa, -2.0 + aa, bd)) * smoothstep(panel + 2.0 - aa, panel + 2.0 + aa, abs(p.x));\n"
    "        if (grill > 0.0)\n"
    "        {\n"
    "            vec2 per = vec2(2.2, 3.81);\n"
    "            float hd = min(length(mod(p, per) - 0.5 * per), length(mod(p + 0.5 * per, per) - 0.5 * per));\n"
    "            float hole = mix(clamp((0.6 - hd) / aa + 0.5, 0.0, 1.0), 0.27, smoothstep(1.1, 2.2, aa));\n"
    "            alb = mix(alb, vec3(0.006), hole * grill);\n"
    "        }\n"
    "        // the buttons: round, domed, in a dark ring\n"
    "        for (int k = 0; k < 5; k++)\n"
    "        {\n"
    "            vec2 bp = p - vec2(k == 0 ? -0.6 * panel : panel * (0.04 + 0.16 * float(k)), bc.y);\n"
    "            float br = (k == 0 ? 0.026 : 0.011) * h, bl = length(bp);\n"
    "            if (bl < br + 2.0)\n"
    "            {\n"
    "                float on = 1.0 - smoothstep(br - aa, br + aa, bl);\n"
    "                occ *= 1.0 - 0.6 * (1.0 - on) * exp(-0.5 * (bl - br) * (bl - br) / max(0.15, aa * aa));\n"
    "                n = normalize(mix(n, tilt(bp / max(bl, 1e-3), 0.9 * bl / br), on));\n"
    "            }\n"
    "        }\n"
    "        float ld = length(p - vec2(-0.3 * panel, bc.y));\n"
    "        lamp += vec3(1.0, 0.06, 0.03) * (0.6 * (1.0 - smoothstep(1.0 - aa, 1.0 + aa, ld)) + 0.03 * exp(-0.5 * ld * ld / 9.0));\n"
    "    }\n"
    "    else\n"
    "    {\n"
    "        // the Amiga monitor's power light, under the front, right of the middle\n"
    "        float ld = roundBox(p - vec2(0.356 * tube.x, yb + 2.2), vec2(1.3, 0.6), 0.4);\n"
    "        lamp += vec3(0.12, 1.0, 0.2) * (0.6 * (1.0 - smoothstep(-aa, aa, ld)) + 0.03 * exp(-0.5 * max(ld, 0.0) * max(ld, 0.0) / 9.0));\n"
    "    }\n"
    "\n"
    "    // The screen lights the walls of the recess, which face the picture beside them, so they\n"
    "    // change with it (Screen light on the casing). A point on a wall z mm in front of the phosphor\n"
    "    // (which sits about 10 mm behind the front of the glass) sees the picture from about 0.7 z to\n"
    "    // 3 z beyond the edge; a Lambert screen of luminance L gives it 0.67 L (the Amiga's 55-degree\n"
    "    // walls) or 0.46 L (45 degrees) of illuminance, so the wall shines at 0.21 or 0.15 of L times\n"
    "    // its albedo. On these slanted paths the tinted glass lets about 30% out, and the dot mask\n"
    "    // and the lines leave about 70% of the picture's light: 0.045 and 0.03. Plastic scatters it,\n"
    "    // it does not mirror the picture. Six samples of the glowing picture over that region.\n"
    "    vec3 pic = vec3(0.0);\n"
    "    float facing = smoothstep(-0.6, 1.2, u) * LR_SPILL;\n"
    "    if (facing > 0.0)\n"
    "    {\n"
    "        vec2 ov = monShown();\n"
    "        vec2 edge = clamp(c * 0.5 * ov + 0.5, 0.0, 1.0);          // the tube's edge on the picture\n"
    "        vec2 nt = boxOut((tc - 0.5) * tube, inner, 15.0);         // outward, in texture orientation\n"
    "        vec2 inward = -nt / tube * ov, side = vec2(-nt.y, nt.x) / tube * ov;   // per mm\n"
    "        float z = (amiga ? 1.43 : pc ? 1.0 : 0.84) * max(d - mw, 0.0) + 10.0;\n"
    "        vec3 gl = vec3(0.0);\n"
    "        for (int i = 0; i < 2; i++)\n"
    "            for (int j = -1; j <= 1; j++)\n"
    "            {\n"
    "                vec2 q = edge + inward * ((i == 0 ? 0.9 : 2.4) * z) + side * (1.3 * float(j) * z);\n"
    "                gl += (j == 0 ? 0.25 : 0.125) * textureLod(LR_Glow, clamp(q, 0.0, 1.0), 0.0).rgb;\n"
    "            }\n"
    "        pic = gl * vWhite * (amiga ? 0.045 : pc ? 0.03 : 0.026) * facing;\n"
    "    }\n"
    "\n"
    "    vec3 casing = plastic(alb, n, vec3(p, 0.0), light, occ, gloss) + alb * pic;\n"
    "    vec2 sc = (vTexCoord - 0.5) * LR_OutputSize.xy * LR_OutputSize.w;   // screen heights\n"
    "    vec2 fc = floor(vTexCoord * LR_OutputSize.xy) - floor(0.5 * LR_OutputSize.xy);   // screen pixel\n"
    "    vec3 behind = inScene ? scene(scn, sc, fc, 0.5 * LR_OutputSize.xy * LR_OutputSize.w, t, LR_OutputSize.w)\n"
    "                : vec3(0.20, 0.195, 0.18) * light;               // the wall, further from the light\n"
    "    if (scn == 3)        // the casing's edge, turned away from the viewer, catches the sunset's light\n"
    "        casing += behind * 0.2 * smoothstep(-sh - 1.0, 0.0, s);\n"
    "    behind = mix(behind, stripCol, strip);\n"
    "    return mix(behind, casing, 1.0 - smoothstep(-aa, aa, s)) + lamp;\n"
    "}\n"
    "\n"
    "void lr_main()\n"
    "{\n"
    "    float scan = vTiming.x, pal = vTiming.y, interlace = vTiming.z;\n"
    "\n"
    "    // tube geometry: barrel curvature and rounded corners\n"
    "    vec2 tc = vTexCoord;\n"
    "    vec2 tubePx = LR_OutputSize.xy;                   // size of the tube face in screen pixels\n"
    "    float px = 2.0 * LR_OutputSize.z;\n"
    "    float va = LR_OutputSize.x * LR_OutputSize.w;\n"
    "    {\n"
    "        // the picture area may be any shape: the 4:3 tube sits in its middle\n"
    "        vec2 fit = va > 4.0 / 3.0 ? vec2(4.0 / 3.0 / va, 1.0) : vec2(1.0, 0.75 * va);\n"
    "        tc = (tc - 0.5) / fit + 0.5;\n"
    "        tubePx *= fit;\n"
    "        px /= fit.x;\n"
    "    }\n"
    "    // real size: the tube as large as the monitor it describes (Monitor size), on a screen whose\n"
    "    // height is given; the picture area must be as tall as the screen (full screen)\n"
    "    if (LR_SCREEN_H > 0.0)\n"
    "    {\n"
    "        float screenMM = LR_SCREEN_H * (LR_SCREEN_UNIT > 0.5 ? 25.4 : 10.0);\n"
    "        float s = min(LR_OutputSize.y * monTubeMM().y / (screenMM * tubePx.y), 1.0);\n"
    "        tc = (tc - 0.5) / s + 0.5;\n"
    "        tubePx *= s;\n"
    "        px /= s;\n"
    "    }\n"
    "    vec2 c = tc * 2.0 - 1.0;\n"
    "    // The glass bulges: seen from the front, its edges bow outwards and the corners are rounded.\n"
    "    // The raster on it does not follow the glass: the deflection was corrected so that the\n"
    "    // picture looks nearly rectangular from the front (a well adjusted set kept the bow of its\n"
    "    // lines to about 1% of the height), and the curved edges of the glass crop its corners.\n"
    "    // Raster bend is the share of the glass curvature the picture still follows: 0 a perfectly\n"
    "    // corrected raster, 1 a picture bent as much as the glass.\n"
    "    vec2 cs = c;                                          // straight position on the screen\n"
    "    vec2 curv = vec2(LR_CURV_X, LR_CURV_Y);\n"
    "    c *= 1.0 + curv * (c.yx * c.yx);                      // position on the glass\n"
    "    vec2 cr = cs * (1.0 + LR_BEND * curv * (cs.yx * cs.yx));   // position in the raster\n"
    "    float corner = LR_CORNER;\n"
    "    vec2 qq = abs(c) - 1.0 + corner;\n"
    "    float dist = length(max(qq, 0.0)) + min(max(qq.x, qq.y), 0.0) - corner;\n"
    "    float inside = 1.0 - smoothstep(-px, px, dist);\n"
    "\n"
    "    vec3 col = vec3(0.0);\n"
    "    if (inside > 0.0)\n"
    "    {\n"
    "        vec2 ut = c * 0.5 + 0.5;                          // on the glass: mask, damper wires\n"
    "        vec2 up = cr * 0.5 + 0.5;                         // the picture's place on the tube\n"
    "        vec2 ua = (up - 0.5) * monShown() + 0.5;          // ... and in the scan\n"
    "        // linearity errors of the deflection: one side of the picture squeezed, the other stretched\n"
    "        vec2 lin = vec2(LR_LIN_X, LR_LIN_Y);\n"
    "        lin.y = -lin.y;                                   // rows run bottom-up: keep + for the top\n"
    "        ua += lin * ua * (1.0 - ua);\n"
    "        float srcH = LR_OriginalSize.y / vTiming.w;   // native lines\n"
    "        float rpl = 1.0, ph = 0.0;                         // beam rows per line, row of line 0\n"
    "        // Amiga emulators draw every line twice (720x568 for a 256-line game) and weave the\n"
    "        // two fields of an interlaced screen into the same rows. Identical row pairs are one\n"
    "        // line: the gaps between lines stay, as on the real monitor. (0.5/255: 8-bit frames.)\n"
    "        if (interlace > 0.5 && vAmiga > 0.5)\n"
    "        {\n"
    "            vec2 fd = texelFetch(LR_Fields, ivec2(0, 0), 0).rg;   // largest pair difference, both pairings\n"
    "            if (min(fd.x, fd.y) < 0.5 / 255.0)\n"
    "            {\n"
    "                interlace = 0.0;\n"
    "                rpl = 2.0;\n"
    "                ph = fd.x < 0.5 / 255.0 ? 0.0 : 1.0;\n"
    "                srcH = floor((srcH - ph) * 0.5);\n"
    "            }\n"
    "        }\n"
    "\n"
    "        // raster: TV modes sit in a 240/288-line field, VGA and 24 kHz arcade fill the screen\n"
    "        bool vga = scan > 0.5 && scan < 1.5;\n"
    "        bool mm = inMM(scan);                              // tube described in mm (PC monitor, 1084S)\n"
    "        // position along the source line: a 15 kHz monitor in mm shows the whole active line,\n"
    "        // so a source shorter than the line leaves side borders\n"
    "        float xs = (ua.x - 0.5) / vShare + 0.5;\n"
    "        // TV show: the studio's frame synchronizer made a standard interlaced picture out of\n"
    "        // the console's 240p/288p frames, so every console line is drawn in both fields, half\n"
    "        // a line apart, and the dark gaps between the lines are filled\n"
    "        bool show = isShow(LR_CABLE) && scan < 0.5;\n"
    "        bool prog = interlace < 0.5;                       // the console's own picture: 240p/288p\n"
    "        if (show) interlace = 1.0;\n"
    "        float dbl = (vga && srcH <= 300.0) ? 2.0 : 1.0;\n"
    "        float BH = srcH * dbl;\n"
    "        // the TV's field: 240 or 288 lines (480 or 576 interlaced); a frame with fewer lines leaves a\n"
    "        // border, as on the real set. Picture height 1 lets the core's lines fill the height\n"
    "        // instead, for cores that crop lines and set the aspect ratio from the lines they keep\n"
    "        // (the picture is then a zoom of the same tube: lines and beam keep their look).\n"
    "        float visField = scan > 0.5 ? BH : (pal > 0.5 ? 288.0 : 240.0) * (interlace > 0.5 ? 2.0 : 1.0);\n"
    "        float visLines = (LR_FILL > 0.5 && scan < 0.5 && !show) ? BH : visField;\n"
    "        bool il = interlace > 0.5 && LR_STEADY < 0.5;\n"
    "        float stepL = il ? 2.0 : 1.0;\n"
    "        float offL = il ? float(LR_FrameCount % 2u) : 0.0;\n"
    "        float sgk = (interlace > 0.5 && LR_STEADY > 0.5) ? 2.0 : 1.0;\n"
    "\n"
    "        // TV show: raster line i shows programme line floor(i / rps) (rps: 2 for a 240p/288p\n"
    "        // console, whose line is in both fields). A game in the other TV standard (an NTSC game\n"
    "        // on a PAL programme, or the other way round) went through the studio's standards\n"
    "        // converter, which scaled the console's picture to the programme's (see showLines).\n"
    "        // The tv-show-broadcast preset's extra pass already made one beam row per programme\n"
    "        // line; without it (Cable 4 in another preset) the conversion is done here, per pixel:\n"
    "        // beam row = programme line * scv + sco.\n"
    "        vec4 smap = vec4(1.0, 1.0, 0.0, 0.0);\n"
    "        float rps = 1.0, scv = 1.0, sco = 0.0, beamLines = srcH;\n"
    "        if (show)\n"
    "        {\n"
    "            smap = showLines(pal, prog ? 0.0 : 1.0, srcH);\n"
    "            rps = smap.x;\n"
    "            if (textureSize(LR_Beam, 0).y == int(SHOW_LINES_ROWS))\n"
    "                beamLines = smap.w;\n"
    "            else\n"
    "            {\n"
    "                scv = smap.y;\n"
    "                sco = smap.z;\n"
    "            }\n"
    "            BH = visLines;                                          // borders come from the console's frame\n"
    "        }\n"
    "\n"
    "        float Lf = ua.y * visLines - (visLines - BH) * 0.5;\n"
    "        float u = (Lf - offL - 0.5) / stepL;\n"
    "        float j0 = floor(u);\n"
    "\n"
    "        // vertical convergence error grows toward the edges (the horizontal one is in the beam pass)\n"
    "        float convV = LR_CONV * 0.5 * (0.3 + 0.7 * c.y * abs(c.y));\n"
    "        // spot height in lines: TV in line units; a tube in mm from its line pitch, so the same\n"
    "        // spot covers more lines in 768-line modes than in 400-line ones, and NTSC lines (fewer,\n"
    "        // further apart) show more than PAL lines\n"
    "        vec2 sig = vec2(LR_SIG_LO, max(LR_SIG_LO, LR_SIG_HI)) * sgk;\n"
    "        if (mm)\n"
    "            sig = vec2(LR_MON_SPOT_LO, max(LR_MON_SPOT_LO, LR_MON_SPOT_HI))\n"
    "                * (FWHM_TO_SIGMA * monCornerGrowth(c) * visField / monScanMM().y);\n"
    "\n"
    "        // every line within 3.5 spot widths: the lines left out are at least kn + 1 away\n"
    "        // (4 lines for 240p TV, more for wide spots: merged fields, 1024x768 on a PC monitor)\n"
    "        int kn = int(clamp(ceil(3.5 * sig.y - 1.0), 1.0, 6.0));\n"
    "        float lastRow = -1e6;                                // TV show: the programme line read last\n"
    "        vec4 bb = vec4(0.0);\n"
    "        for (int k = -kn; k <= kn + 1; k++)\n"
    "        {\n"
    "            float j = j0 + float(k);\n"
    "            float i = j * stepL + offL;\n"
    "            if (show)\n"
    "            {\n"
    "                // both raster lines of a programme line (merged fields) use the same beam: read it once\n"
    "                float r = floor(i / rps);\n"
    "                if (r != lastRow)\n"
    "                {\n"
    "                    bb = showBeam(r * scv + sco, xs, beamLines);\n"
    "                    lastRow = r;\n"
    "                }\n"
    "            }\n"
    "            else\n"
    "                bb = beamAt(floor(i / dbl) * rpl + ph, xs, srcH * rpl + ph);\n"
    "            vec3 b = bb.rgb;\n"
    "            vec3 lc = b * b;                                      // linear brightness\n"
    "            // beam height: TV from the local brightness per gun; PC from the spot that made the light\n"
    "            vec3 isg = 1.0 / mix(vec3(sig.x), vec3(sig.y), mm ? vec3(bb.a) : b);\n"
    "            vec3 d = vec3(u - j) + vec3(convV, 0.0, -convV);\n"
    "            col += lc * exp(-0.5 * d * d * isg * isg) * isg * 0.39894228;\n"
    "        }\n"
    "        col *= smoothstep(-0.002, 0.002, xs) * smoothstep(1.002, 0.998, xs);\n"
    "\n"
    "        // phosphor mask\n"
    "        float mt = LR_MASK_TYPE;\n"
    "        float triads = LR_MASK_TRIADS;\n"
    "        // tube in mm: from the mask pitch (a dot mask's pitch is diagonal, 0.866 of it horizontal)\n"
    "        if (mm) triads = monTubeMM().y / (LR_MON_PITCH * (mt > 2.5 && mt < 3.5 ? 0.866 : 1.0));\n"
    "        float pitchPx = tubePx.y / triads;\n"
    "        float str = LR_MASK_STR * smoothstep(1.6, 2.6, pitchPx);\n"
    "        if (mt > 0.5 && str > 0.0)\n"
    "        {\n"
    "            vec2 mp = ut * tubePx / pitchPx;\n"
    "            float dp = 0.25 / pitchPx;\n"
    "            vec3 m = maskAvg(mp - dp, mp + dp, mt);\n"
    "            float avg = mt < 1.5 ? 0.367 : (mt < 2.5 ? 0.31 : (mt < 3.5 ? 0.19 : 0.84));\n"
    "            col *= mix(vec3(1.0 - str), vec3(1.0), m) / mix(1.0 - str, 1.0, avg);\n"
    "        }\n"
    "        if (mt > 0.5 && mt < 1.5)\n"
    "        {\n"
    "            // aperture grille: the two horizontal damper wires\n"
    "            float hp = tubePx.y;\n"
    "            float sw = max(0.45, hp / 4000.0);\n"
    "            float d1 = (ut.y - 1.0 / 3.0) * hp, d2 = (ut.y - 2.0 / 3.0) * hp;\n"
    "            col *= 1.0 - 0.2 * (exp(-0.5 * d1 * d1 / (sw * sw)) + exp(-0.5 * d2 * d2 / (sw * sw)));\n"
    "        }\n"
    "\n"
    "        col *= vWhite;\n"
    "\n"
    "        // halation: light diffused in the glass (energy-conserving)\n"
    "        float gy = show ? ((Lf / rps - 0.5) * smap.y + smap.z + 0.5) / srcH : Lf / BH;\n"
    "        float gin = smoothstep(-0.03, 0.03, gy) * smoothstep(1.03, 0.97, gy) * smoothstep(-0.03, 0.03, xs) * smoothstep(1.03, 0.97, xs);\n"
    "        col = mix(col, textureLod(LR_Glow, vec2(xs, gy), 0.0).rgb * vWhite, LR_GLOW * gin);\n"
    "\n"
    "        // the tube's phosphors are not exactly the display's primaries; colours outside\n"
    "        // the display gamut are clipped in SDR and kept in HDR\n"
    "        if (vPhos > 1.5) col = phosphorMatrix(vPhos) * col;\n"
    "\n"
    "        col = shoulder(col);\n"
    "        float r2 = clamp(dot(c, c) * 0.5, 0.0, 1.0);\n"
    "        col *= 1.0 - LR_VIGNETTE * pow(r2, 1.6);\n"
    "        col += LR_AMBIENT * LR_ROOM * vec3(0.80, 0.92, 0.87);\n"
    "        col *= inside;\n"
    "    }\n"
    "    if (LR_BACKDROP > 0.5 && inside < 1.0)\n"
    "        col += (1.0 - inside) * backdrop(c, max(dist, 0.0), qq, tc, tubePx);\n"
    "\n"
    "    FragColor = vec4(col, 1.0);\n"
    "}\n"
    "\n"
    "flat in vec4 lrParams[8];\n"
    "\n"
    "void main()\n"
    "{\n"
    "    LR_NORM = lrParams[0].x;\n"
    "    LR_STEADY = lrParams[0].y;\n"
    "    LR_CONV = lrParams[0].z;\n"
    "    LR_MASK_TYPE = lrParams[0].w;\n"
    "    LR_MASK_STR = lrParams[1].x;\n"
    "    LR_WHITE = lrParams[1].y;\n"
    "    LR_PHOS = lrParams[1].z;\n"
    "    LR_CURV_X = lrParams[1].w;\n"
    "    LR_CURV_Y = lrParams[2].x;\n"
    "    LR_BEND = lrParams[2].y;\n"
    "    LR_CORNER = lrParams[2].z;\n"
    "    LR_GLOW = lrParams[2].w;\n"
    "    LR_VIGNETTE = lrParams[3].x;\n"
    "    LR_OVERSCAN = lrParams[3].y;\n"
    "    LR_OVERSCAN_V = lrParams[3].z;\n"
    "    LR_LIN_X = lrParams[3].w;\n"
    "    LR_LIN_Y = lrParams[4].x;\n"
    "    LR_AMBIENT = lrParams[4].y;\n"
    "    LR_MON_SIZE = lrParams[4].z;\n"
    "    LR_MON_PITCH = lrParams[4].w;\n"
    "    LR_MON_SPOT_LO = lrParams[5].x;\n"
    "    LR_MON_SPOT_HI = lrParams[5].y;\n"
    "    LR_MON_CORNER = lrParams[5].z;\n"
    "    LR_SCREEN_H = lrParams[5].w;\n"
    "    LR_SCREEN_UNIT = lrParams[6].x;\n"
    "    LR_BACKDROP = lrParams[6].y;\n"
    "    LR_ROOM = lrParams[6].z;\n"
    "    LR_SPILL = lrParams[6].w;\n"
    "    LR_SCENE_SPEED = lrParams[7].x;\n"
    "    lr_main();\n"
    "}\n"
    "#endif\n"
    "\n";

/* shaders/present.glsl */
static const char LOLA_SRC7[] =
    "#version 330 core\n"
    "// Lola Retro - present pass for Amiberry (Commodore 1084S).\n"
    "// Generated by tools/make_glsl.py from shaders/lola-retro/shaders/present.slang. Do not edit.\n"
    "\n"
    "#define LR_FIELDS\n"
    "#define LR_NO_FEEDBACK\n"
    "#define LR_FIT_43\n"
    "#define LR_ROWS_UP\n"
    "\n"
    "uniform vec2 TextureSize;       // Source: the previous pass (the frame for the first pass)\n"
    "uniform vec2 OrigTextureSize;   // Original: the emulator's frame\n"
    "uniform vec2 OutputSize;        // this pass\n"
    "uniform int FrameCount;\n"
    "#define LR_SourceSize vec4(TextureSize, 1.0 / TextureSize)\n"
    "#define LR_OriginalSize vec4(OrigTextureSize, 1.0 / OrigTextureSize)\n"
    "#define LR_OutputSize vec4(OutputSize, 1.0 / OutputSize)\n"
    "#define LR_FrameCount uint(FrameCount)\n"
    "\n"
    "// fixed by the preset\n"
    "const float LR_CABLE = 3.0;\n"
    "const float LR_CONSOLE = 6.0;\n"
    "const float LR_DEMOD = 0.0;\n"
    "const float LR_GHOST = 0.03;\n"
    "const float LR_MON_MM = 1.0;\n"
    "const float LR_TAPE = 2.0;\n"
    "\n"
    "// adjustable values, read from the first pass's output in main()\n"
    "float LR_NORM;\n"
    "float LR_STEADY;\n"
    "float LR_PHOS;\n"
    "float LR_OVERSCAN;\n"
    "float LR_OVERSCAN_V;\n"
    "float LR_MON_SIZE;\n"
    "float LR_MON_CORNER;\n"
    "\n"
    "// Lola Retro - pass 7: linear light -> display, with a dither against banding.\n"
    "\n"
    "// Lola Retro - shared parameters, uniforms and helpers for every pass.\n"
    "//\n"
    "// The chain simulates the whole analog path:\n"
    "//   console encoder -> cable -> TV decoder -> electron beam -> phosphor mask -> glass.\n"
    "// Console timing (pixel clock, subcarrier cycles per line) decides how composite\n"
    "// artefacts look, so it is part of the model.\n"
    "\n"
    "const float TAU = 6.28318530718;\n"
    "\n"
    "// Dither blend (RGB and S-Video, off by default): composite blended 1-pixel dither\n"
    "// patterns into new colours or transparency; on RGB they stay visible as stripes.\n"
    "// The blend finds the part of the picture that alternates from one console pixel to\n"
    "// the next (a Gaussian window of 1.25 pixels with alternating signs, a narrow notch at\n"
    "// half the pixel clock) and takes it out. Flat areas, gradients and wider detail are\n"
    "// left alone. Weights for offsets 0..4 and the normalisation 4 * (w1 + w3):\n"
    "const float DBW[5] = float[5](1.0, 0.726149, 0.278037, 0.056135, 0.005976);\n"
    "const float DBN = 3.129136;\n"
    "float dbSign(int k) { return (abs(k) & 1) == 1 ? -1.0 : 1.0; }\n"
    "\n"
    "// RF: the echo (multipath ghost) added by the antenna path\n"
    "const float RF_ECHO = 0.12;      // strength\n"
    "const float RF_ECHO_US = 0.8;    // delay in microseconds\n"
    "\n"
    "// TV show (cable 4): the game seen on a TV programme. The console's RGB goes into the studio,\n"
    "// where a frame synchronizer turns its 240p/288p frames into a standard interlaced picture\n"
    "// (each console frame becomes one field, the next one lands half a line lower; the CRT pass\n"
    "// draws every console line in both fields), onto Betacam SP tape (LR_TAPE copies), through\n"
    "// the station's colour encoder and the transmitter, and from a roof antenna into an ordinary\n"
    "// TV, which decodes it like composite. Bandwidths in MHz at -3 dB.\n"
    "// Sony BVW-75P: Y 5.5 MHz -3 dB, colour 1.5 MHz -1.5 dB (about 2.1 MHz at -3 dB);\n"
    "// ITU-R BT.470: PAL U and V less than 3 dB down at 1.3 MHz. The transmitter's 5 MHz limit\n"
    "// (PAL B/G) is sharper than anything the TV's composite decoder passes, so it changes nothing.\n"
    "const float SHOW_TAPE_Y = 5.5;   // Betacam SP luma, one copy\n"
    "const float SHOW_TAPE_C = 2.1;   // Betacam SP colour difference signals, one copy\n"
    "const float SHOW_ENC_C = 1.3;    // the station's colour encoder (U and V)\n"
    "const float SHOW_GHOST_US = 1.2; // delay of the antenna ghost: a reflection about 360 m longer\n"
    "\n"
    "bool isShow(float cable) { return cable > 3.5; }\n"
    "\n"
    "// Echo on the antenna path: x = strength, y = delay in microseconds\n"
    "vec2 rfEcho(float cable)\n"
    "{\n"
    "    if (cable < 0.5) return vec2(RF_ECHO, RF_ECHO_US);\n"
    "    if (isShow(cable)) return vec2(LR_GHOST, SHOW_GHOST_US);\n"
    "    return vec2(0.0, 1.0);\n"
    "}\n"
    "\n"
    "// TV show: how the programme's lines map to the console's. x: raster lines per console line\n"
    "// (2 for a 240p/288p console, whose line is drawn in both fields), y: console lines per\n"
    "// programme line (1 unless the studio's standards converter scaled the picture to the other\n"
    "// TV standard), z: the console line of programme line 0 (a shorter frame sits in the middle),\n"
    "// w: the programme's lines (one field for a 240p/288p console, the whole frame for an\n"
    "// interlaced one). lines: the console's native lines.\n"
    "vec4 showLines(float pal, float interlace, float lines)\n"
    "{\n"
    "    bool prog = interlace < 0.5;\n"
    "    float field = pal > 0.5 ? 288.0 : 240.0;\n"
    "    float plines = prog ? field : 2.0 * field;\n"
    "    // the console's own standard by the same rule as TV standard auto (getTiming)\n"
    "    float own = ((prog ? lines : lines * 0.5) > 240.5 ? 288.0 : 240.0) * (prog ? 1.0 : 2.0);\n"
    "    float scv = own / plines;\n"
    "    return vec4(prog ? 2.0 : 1.0, scv, 0.5 * scv - 0.5 - floor(0.5 * (own - lines)), plines);\n"
    "}\n"
    "\n"
    "// The TV presets run the encoder and decoder at a fixed 1280 samples per line (about 27 MHz,\n"
    "// 4 per pixel of a 320-wide console), whatever the frame's width: the signal needs no more,\n"
    "// and an upscaled frame (internal resolution) then costs no more than a native one. A frame\n"
    "// wider than that is averaged down to it in the native pass. (The PC and Amiga presets keep\n"
    "// 4 samples per frame pixel: their beam reads every pixel exactly.)\n"
    "const float ENC_SAMPLES = 1280.0;\n"
    "\n"
    "// The tv-show-broadcast preset has one more pass (show-lines.slang) that makes one beam row\n"
    "// per programme line, so the CRT pass does not interpolate at every screen pixel. Its output\n"
    "// is this many rows high: more than any programme has, and a height the beam pass of the other\n"
    "// presets never has, so the CRT pass can tell which rows it gets.\n"
    "const float SHOW_LINES_ROWS = 577.0;\n"
    "\n"
    "float hash13(vec3 p3)\n"
    "{\n"
    "    p3 = fract(p3 * 0.1031);\n"
    "    p3 += dot(p3, p3.zyx + 31.32);\n"
    "    return fract((p3.x + p3.y) * p3.z);\n"
    "}\n"
    "\n"
    "// ---------------------------------------------------------------------------\n"
    "// Console timing\n"
    "// ---------------------------------------------------------------------------\n"
    "// Console ids: 1 SNES/NES, 2 Mega Drive H40, 3 Mega Drive H32 and Master System, 4 PlayStation,\n"
    "// 5 PlayStation 2, 6 Amiga, 7 PC VGA (also the PC-98's 640x400), 8 Arcade 15 kHz, 9 Arcade 24 kHz.\n"
    "// Other systems use the id with their timing (PC Engine, Saturn, N64: 4).\n"
    "\n"
    "float autoConsole(vec2 s)\n"
    "{\n"
    "    float w = s.x, h = s.y;\n"
    "    bool mon15 = LR_MON_MM > 0.5;    // a 15 kHz monitor cannot show 31 kHz VGA\n"
    "    // 640x400 is VGA's 400 lines and the PC-98's: on a computer monitor the same picture\n"
    "    if (!mon15 && ((w == 320.0 && h == 200.0) || (w == 640.0 && (h == 350.0 || h == 400.0)))) return 7.0;\n"
    "    if (h == 256.0 || h == 512.0 || (w == 640.0 && h == 200.0)) return 6.0;\n"
    "    if (mon15 && (h == 200.0 || h == 400.0) && (w == 320.0 || w == 640.0)) return 6.0;\n"
    "    // PUAE's default frames: the whole overscan area, 360, 720 or 1440 wide (PAL 287 or 574 rows, NTSC 242 or 484)\n"
    "    if ((w == 360.0 || w == 720.0 || w == 1440.0) && (h == 287.0 || h == 574.0 || h == 242.0 || h == 484.0)) return 6.0;\n"
    "    if (h >= 336.0 && h <= 400.0 && w >= 400.0) return 9.0;\n"
    "    if (h > 300.0) return 5.0;\n"
    "    if (w > 420.0) return 4.0;\n"
    "    // 192 lines: the Master System (and MSX, ColecoVision), 228 cycles per line like the Mega Drive\n"
    "    if (w == 256.0 && h == 192.0) return 3.0;\n"
    "    if (w <= 300.0) return 1.0;\n"
    "    if (h >= 232.0) return 4.0;\n"
    "    return 2.0;\n"
    "}\n"
    "\n"
    "// a: pixel clock NTSC, pixel clock PAL (MHz), nominal width, scan mode (0 TV, 1 VGA, 2 fill)\n"
    "// b: subcarrier phase step per line (NTSC, PAL), per field (NTSC, PAL)\n"
    "// c: x = 1 when the PAL line count per field is odd (V-switch flips every field)\n"
    "void consoleTable(float id, out vec4 a, out vec4 b, out float c)\n"
    "{\n"
    "    if (id < 1.5)      { a = vec4(5.369318, 5.320342, 256.0, 0.0); b = vec4(1.0 / 3.0, 1.0 / 6.0, 1.0 / 3.0, 0.0);  c = 0.0; }\n"
    "    else if (id < 2.5) { a = vec4(6.711647, 6.650428, 320.0, 0.0); b = vec4(0.0, 0.0, 0.0, 0.0);                    c = 1.0; }\n"
    "    else if (id < 3.5) { a = vec4(5.369318, 5.320342, 256.0, 0.0); b = vec4(0.0, 0.0, 0.0, 0.0);                    c = 1.0; }\n"
    "    else if (id < 4.5) { a = vec4(6.711647, 6.652800, 320.0, 0.0); b = vec4(0.5, 0.75, 0.5, 0.5);                  c = 0.0; }\n"
    "    else if (id < 5.5) { a = vec4(13.5, 13.5, 640.0, 0.0);        b = vec4(0.5, 0.75, 0.75, 0.875);                c = 0.0; }\n"
    "    else if (id < 6.5) { a = vec4(7.15909, 7.09379, 320.0, 0.0);  b = vec4(0.5, 0.75, 0.75, 0.875);                c = 0.0; }\n"
    "    else if (id < 7.5) { a = vec4(12.5875, 12.5875, 320.0, 1.0);  b = vec4(0.5, 0.75, 0.75, 0.875);                c = 0.0; }\n"
    "    else if (id < 8.5) { a = vec4(6.711647, 6.711647, 320.0, 0.0); b = vec4(0.5, 0.75, 0.5, 0.5);                  c = 0.0; }\n"
    "    else               { a = vec4(16.0, 16.0, 496.0, 2.0);        b = vec4(0.5, 0.75, 0.75, 0.875);                c = 0.0; }\n"
    "}\n"
    "\n"
    "// Internal resolution: an upscaled frame (more than 576 lines, or a console set by hand\n"
    "// whose native mode is smaller) is read as k x k blocks of one native pixel.\n"
    "// Returns k (1 for native frames).\n"
    "float upscaleOf(vec2 orig)\n"
    "{\n"
    "    float id = LR_CONSOLE;\n"
    "    bool tv = id < 5.5 || (id > 7.5 && id < 8.5);       // VGA, Amiga and 24 kHz modes are never scaled\n"
    "    float base = (id > 4.5 && id < 5.5) ? 480.0 : 240.0; // PS2 by hand: 480i class, otherwise 240p class\n"
    "    bool scaled = id < 0.5 ? orig.y > 576.0 : (tv && orig.y > base * 1.5);\n"
    "    if (!scaled) return 1.0;\n"
    "    for (float k = 2.0; k <= 16.0; k += 1.0)\n"
    "    {\n"
    "        float lines = orig.y / k;\n"
    "        if (lines == floor(lines) && lines >= base * 0.83 && lines <= base * 1.21) return k;\n"
    "    }\n"
    "    return max(1.0, floor(orig.y / base + 0.5));\n"
    "}\n"
    "\n"
    "struct Timing\n"
    "{\n"
    "    float pclk;        // pixel clock for this source width (MHz)\n"
    "    float fsc;         // colour subcarrier (MHz)\n"
    "    float lineFrac;    // subcarrier phase advance per line (cycles)\n"
    "    float fieldStep;   // phase advance per field (cycles)\n"
    "    float framePhase;  // phase offset of the current field (cycles)\n"
    "    float altStep;     // > 0: the phase only alternates between 0 and this from frame to frame (NES, SNES)\n"
    "    float vsw;         // PAL V-switch offset for this field\n"
    "    float vswStep;     // change of the V-switch offset per field (1 when the line count per field is odd)\n"
    "    float pal;         // 1 = PAL\n"
    "    float scan;        // 0 TV raster, 1 VGA line doubling, 2 fill (24 kHz arcade)\n"
    "    float interlace;   // 1 = 480i/576i source\n"
    "    float scale;       // internal resolution factor of the core (1 = native)\n"
    "    float id;          // console timing id (see consoleTable)\n"
    "    float hres;        // frame pixels per console pixel (Amiga: 1 lores, 2 hires, 4 superhires)\n"
    "};\n"
    "\n"
    "bool isAmiga(Timing t) { return t.id > 5.5 && t.id < 6.5; }\n"
    "\n"
    "Timing getTiming(vec2 orig, uint frameCount)\n"
    "{\n"
    "    Timing t;\n"
    "    t.scale = upscaleOf(orig);\n"
    "    vec2 nat = orig / t.scale;                          // the console's native mode\n"
    "    float id = LR_CONSOLE < 0.5 ? autoConsole(nat) : LR_CONSOLE;\n"
    "    vec4 a; vec4 b; float c;\n"
    "    consoleTable(id, a, b, c);\n"
    "    t.id = id;\n"
    "    if (id > 4.5 && id < 5.5 && nat.x > 700.0) a.z = 720.0;   // PS2 720-wide modes keep 13.5 MHz\n"
    "    t.scan = a.w;\n"
    "    t.interlace = (t.scan < 0.5 && nat.y > 300.0) ? 1.0 : 0.0;\n"
    "    bool amiga = id > 5.5 && id < 6.5;\n"
    "    if (LR_NORM > 1.5) t.pal = 1.0;\n"
    "    else if (LR_NORM > 0.5) t.pal = 0.0;\n"
    "    else\n"
    "    {\n"
    "        float lines = t.interlace > 0.5 ? nat.y * 0.5 : nat.y;\n"
    "        // an Amiga NTSC frame with its overscan border has up to 243 lines, a PAL one 256 or more\n"
    "        t.pal = (t.scan < 0.5 && lines > (amiga ? 249.5 : 240.5)) ? 1.0 : 0.0;\n"
    "    }\n"
    "    // full source width: a wider (upscaled) line still takes the same time\n"
    "    float base = mix(a.x, a.y, t.pal);\n"
    "    t.pclk = base * orig.x / a.z;\n"
    "    // Amiga: the width tells lores, hires or superhires. Emulators often send the whole\n"
    "    // overscan area (PUAE and Amiberry: 720 wide in hires), so a wider frame is a longer\n"
    "    // line at the same pixel clock, not faster pixels.\n"
    "    float cls = orig.x < 480.0 ? 1.0 : (orig.x < 960.0 ? 2.0 : 4.0);\n"
    "    if (amiga) t.pclk = base * (320.0 * cls) / a.z;\n"
    "    // SVGA modes run faster lines: VESA 75 Hz clocks (800x600 49.5 MHz, 1024x768 78.75 MHz)\n"
    "    if (t.scan > 0.5 && t.scan < 1.5 && orig.x > 720.0) t.pclk = 78.75 * orig.x * orig.y / (1024.0 * 768.0);\n"
    "    t.hres = amiga ? cls : orig.x / a.z;\n"
    "    t.fsc = t.pal > 0.5 ? 4.433619 : 3.579545;\n"
    "    // TV show: the station's encoder makes the subcarrier of a standard interlaced broadcast,\n"
    "    // so its rhythm is the standard's (the PlayStation 2 row), not the console's\n"
    "    if (isShow(LR_CABLE)) { b = vec4(0.5, 0.75, 0.75, 0.875); c = 0.0; }\n"
    "    t.lineFrac = mix(b.x, b.y, t.pal);\n"
    "    t.fieldStep = mix(b.z, b.w, t.pal);\n"
    "    // 24 is a multiple of every field cycle above (1, 2, 3, 4, 8), so the phase never drifts\n"
    "    float fc = LR_STEADY > 0.5 ? 0.0 : float(frameCount % 24u);\n"
    "    // NES and SNES (NTSC, not interlaced): 1364 master clocks per line, 227 1/3 cycles, so a\n"
    "    // 262-line frame moves the phase by 1/3 cycle. But every other frame is 4 clocks short (the\n"
    "    // NES skips a dot, the SNES shortens one line), which moves it by 2/3 instead, so the phase\n"
    "    // only alternates between two values, 2/3 cycle apart: the dots jitter instead of crawling.\n"
    "    // (A 3-frame crawl only happens in the few NES games that blank the start of the frame.)\n"
    "    t.altStep = (id < 1.5 && t.pal < 0.5 && t.interlace < 0.5) ? 2.0 / 3.0 : 0.0;\n"
    "    t.framePhase = t.altStep > 0.0 ? t.altStep * mod(fc, 2.0) : fract(fc * t.fieldStep);\n"
    "    t.vsw = mod(fc * c, 2.0);\n"
    "    t.vswStep = c;\n"
    "    return t;\n"
    "}\n"
    "\n"
    "// Frame pixels and rows per console pixel and line, for effects sized on the glass (glow,\n"
    "// misconvergence). Only the Amiga needs it: its emulators send hires frames (2 pixels per lores\n"
    "// pixel) and draw every line twice or weave two fields. Other consoles keep (1, 1).\n"
    "vec2 consoleUnit(Timing t) { return isAmiga(t) ? vec2(t.hres, t.interlace > 0.5 ? 2.0 : 1.0) : vec2(1.0); }\n"
    "\n"
    "// y is a source row; rows of one upscaled block belong to the same native line\n"
    "float nativeLine(float y, Timing t) { return floor(y / t.scale); }\n"
    "float physLine(float y, Timing t) { float l = nativeLine(y, t); return t.interlace > 0.5 ? floor(l * 0.5) : l; }\n"
    "bool oddField(float y, Timing t) { return t.interlace > 0.5 && mod(nativeLine(y, t), 2.0) > 0.5; }\n"
    "\n"
    "// Subcarrier phase at time tUs (microseconds from the start of the active line) on line y,\n"
    "// off cycles later in the frame sequence (see steadyFrames)\n"
    "float phaseAtOff(float tUs, float y, Timing t, float off)\n"
    "{\n"
    "    float fo = oddField(y, t) ? t.fieldStep : 0.0;\n"
    "    return TAU * fract(fract(t.fsc * tUs) + fract(t.lineFrac * physLine(y, t)) + fo + t.framePhase + off);\n"
    "}\n"
    "float phaseAt(float tUs, float y, Timing t) { return phaseAtOff(tUs, y, t, 0.0); }\n"
    "\n"
    "// PAL alternates the sign of V on every line; vsw: the V-switch offset of the frame\n"
    "float vSignW(float y, Timing t, float vsw)\n"
    "{\n"
    "    if (t.pal < 0.5) return 1.0;\n"
    "    float pl = physLine(y, t) + vsw + (oddField(y, t) ? 1.0 : 0.0);\n"
    "    return mod(pl, 2.0) < 0.5 ? 1.0 : -1.0;\n"
    "}\n"
    "float vSign(float y, Timing t) { return vSignW(y, t, t.vsw); }\n"
    "\n"
    "// No flicker: the frames the eye blends together.\n"
    "// Most consoles shift the colour subcarrier from one frame to the next (a 2-frame cycle on the\n"
    "// PlayStation, up to 8 in PAL), so the cross-colour and the dots along coloured edges move. At\n"
    "// 50 or 60 frames a second the eye sees their average, in which they largely cancel. A single\n"
    "// frozen frame would show all of them at full strength, more than anyone ever saw. So with No\n"
    "// flicker on, the encoder makes the signal for two or three frames of the cycle and the decoder\n"
    "// averages what they show: the three frames of a 3-frame cycle, otherwise the first frame and\n"
    "// the one half a subcarrier cycle on (every 2, 4 and 8-frame cycle reaches it), which cancels the\n"
    "// same artefacts. The NES and SNES alternate between two phases 2/3 cycle apart: their average\n"
    "// only halves the artefacts, as on the real console. With No flicker off, one frame: the moving\n"
    "// original.\n"
    "// Returns the number of frames (1 to 3); off: their phase offsets (cycles), vsw: their PAL\n"
    "// V-switch offsets.\n"
    "int steadyFrames(Timing t, out vec3 off, out vec3 vsw)\n"
    "{\n"
    "    off = vec3(0.0);\n"
    "    vsw = vec3(t.vsw, 0.0, 0.0);\n"
    "    if (LR_STEADY < 0.5) return 1;\n"
    "    if (t.altStep > 0.0)\n"
    "    {\n"
    "        off.y = t.altStep;\n"
    "        return 2;\n"
    "    }\n"
    "    float s = t.fieldStep;\n"
    "    if (abs(s - 1.0 / 3.0) < 0.01 || abs(s - 2.0 / 3.0) < 0.01)\n"
    "    {\n"
    "        off = vec3(0.0, fract(s), fract(2.0 * s));\n"
    "        vsw = vec3(0.0, mod(t.vswStep, 2.0), mod(2.0 * t.vswStep, 2.0));\n"
    "        return 3;\n"
    "    }\n"
    "    for (float k = 1.0; k <= 8.0; k += 1.0)\n"
    "    {\n"
    "        if (abs(fract(k * s) - 0.5) < 0.01)\n"
    "        {\n"
    "            off.y = 0.5;\n"
    "            vsw.y = mod(k * t.vswStep, 2.0);\n"
    "            return 2;\n"
    "        }\n"
    "    }\n"
    "    // no phase change, but a PAL V-switch that flips every frame (odd line count per field)\n"
    "    if (t.pal > 0.5 && t.vswStep > 0.5)\n"
    "    {\n"
    "        vsw.y = 1.0;\n"
    "        return 2;\n"
    "    }\n"
    "    return 1;\n"
    "}\n"
    "\n"
    "// ---------------------------------------------------------------------------\n"
    "// Monitor in millimetres: PC monitors (31 kHz modes) always, and 15 kHz monitors such as\n"
    "// the Commodore 1084S when \"15 kHz monitor in mm\" is on. The tube is described like on its\n"
    "// spec sheet (size, mask pitch, beam spot on dark and on white), so every video mode follows\n"
    "// from the same tube: 320x200 doubled to 400 lines or 1024x768 on a PC monitor, PAL or NTSC\n"
    "// on the 1084S (NTSC lines sit further apart, so they show more).\n"
    "// Typical mid-90s 15-inch PC monitor: 13.8-14 inch viewable, 0.28 mm dot pitch, a spot of\n"
    "// about 0.45 mm on white (sharp at 800x600, soft at 1024x768), dynamic focus keeping the\n"
    "// corners below 1.5 x the centre spot.\n"
    "// ---------------------------------------------------------------------------\n"
    "\n"
    "const float FWHM_TO_SIGMA = 0.4246609;   // Gaussian: sigma = FWHM / (2 sqrt(2 ln 2))\n"
    "\n"
    "bool isPC(float scan) { return scan > 0.5 && scan < 1.5; }\n"
    "\n"
    "// the tube is described in mm\n"
    "bool inMM(float scan) { return isPC(scan) || (scan < 0.5 && LR_MON_MM > 0.5); }\n"
    "\n"
    "// Viewable tube face in mm: one inch less than the nominal size, 4:3\n"
    "vec2 monTubeMM()\n"
    "{\n"
    "    float d = (LR_MON_SIZE - 1.0) * 25.4;\n"
    "    return vec2(0.8 * d, 0.6 * d);\n"
    "}\n"
    "\n"
    "// The share of the scan that shows on the tube, across and down: less than 1 when overscan is\n"
    "// positive (the picture runs past the edges), more when it is negative (a black border).\n"
    "// Overscan sets both; Overscan height is added to it for the height alone.\n"
    "vec2 monShown() { return vec2(1.0 - LR_OVERSCAN, 1.0 - LR_OVERSCAN - LR_OVERSCAN_V); }\n"
    "\n"
    "// The full scan (active line x active lines) in mm: smaller than the tube face when\n"
    "// overscan is negative (black border), larger when it is positive\n"
    "vec2 monScanMM() { return monTubeMM() / monShown(); }\n"
    "\n"
    "// The spot grows toward the corners (deflection defocus); c is the position on the tube, -1..1\n"
    "float monCornerGrowth(vec2 c) { return 1.0 + (LR_MON_CORNER - 1.0) * 0.5 * dot(c, c); }\n"
    "\n"
    "// Share of the active line that the source covers. A 15 kHz monitor in mm shows the whole\n"
    "// active line (52.6 us NTSC, 52 us PAL), so a 320-pixel Amiga line (45 us) leaves side\n"
    "// borders, like the real 1084S. PC monitors and the TV model fill the width.\n"
    "float activeShare(Timing t, vec2 orig)\n"
    "{\n"
    "    if (!(t.scan < 0.5 && LR_MON_MM > 0.5)) return 1.0;\n"
    "    return min(orig.x / t.pclk / (t.pal > 0.5 ? 52.0 : 52.6), 1.0);\n"
    "}\n"
    "\n"
    "// Standard normal density and cumulative distribution\n"
    "// (erf after Abramowitz & Stegun 7.1.26, error below 1.5e-7)\n"
    "vec3 gaussPdf(vec3 z) { return 0.39894228 * exp(-0.5 * z * z); }\n"
    "vec3 gaussCdf(vec3 z)\n"
    "{\n"
    "    vec3 x = abs(z) * 0.70710678;\n"
    "    vec3 t = 1.0 / (1.0 + 0.3275911 * x);\n"
    "    vec3 p = ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t;\n"
    "    return 0.5 + 0.5 * sign(z) * (1.0 - p * exp(-x * x));\n"
    "}\n"
    "\n"
    "// ---------------------------------------------------------------------------\n"
    "// Colour of the TV: its chroma decoder and its phosphors\n"
    "// ---------------------------------------------------------------------------\n"
    "\n"
    "// Chroma decoder: 1 = by the standard. American and Japanese TVs demodulated R-Y and G-Y\n"
    "// on shifted axes with their own gains (\"red push\", warmer skin tones). PAL TVs, broadcast\n"
    "// monitors and RGB inputs use the standard axes. A TV show reaches the TV as composite.\n"
    "float decoderType(Timing t, float cable)\n"
    "{\n"
    "    if (LR_DEMOD > 0.5) return LR_DEMOD;\n"
    "    return (t.pal < 0.5 && (cable < 2.5 || isShow(cable))) ? 2.0 : 1.0;\n"
    "}\n"
    "\n"
    "// R, G, B from Y and the demodulated U, V (U = 0.492 (B-Y), V = 0.877 (R-Y)).\n"
    "// Consumer axes and gains from the Sony CXA2025AS datasheet, relative to B-Y:\n"
    "// US mode R-Y 112 deg x0.83, G-Y 252 deg x0.30; Japanese mode R-Y 95 deg x0.78, G-Y 240 deg x0.30.\n"
    "vec3 decodeRGB(float Y, vec2 uv, float dec)\n"
    "{\n"
    "    if (dec < 1.5)\n"
    "        return vec3(Y + 1.13983 * uv.y, Y - 0.39465 * uv.x - 0.58060 * uv.y, Y + 2.03211 * uv.x);\n"
    "    bool us = dec < 2.5;\n"
    "    float ar = radians(us ? 112.0 : 95.0), gr = us ? 0.83 : 0.78;\n"
    "    float ag = radians(us ? 252.0 : 240.0), gg = 0.30;\n"
    "    float ry = (uv.x * cos(ar) + uv.y * sin(ar)) * gr / 0.492;\n"
    "    float gy = (uv.x * cos(ag) + uv.y * sin(ag)) * gg / 0.492;\n"
    "    return vec3(Y + ry, Y + gy, Y + uv.x / 0.492);\n"
    "}\n"
    "\n"
    "// Phosphors: 1 sRGB / Rec.709, 2 SMPTE-C (NTSC sets), 3 EBU (PAL sets, broadcast monitors),\n"
    "// 4 Japanese P22 (Sony Trinitron and Japanese sets, arcade monitors).\n"
    "float phosphorSet(Timing t)\n"
    "{\n"
    "    if (LR_PHOS > 0.5) return LR_PHOS;\n"
    "    if (t.scan > 0.5 && t.scan < 1.5) return 1.0;   // PC monitors: sRGB was defined from them\n"
    "    if (t.id > 7.5) return 4.0;                       // arcade monitors\n"
    "    return t.pal > 0.5 ? 3.0 : 2.0;\n"
    "}\n"
    "\n"
    "// Linear phosphor RGB -> linear Rec.709 RGB, white (D65) kept. Primaries (x, y):\n"
    "// SMPTE-C R .630 .340 G .310 .595 B .155 .070; EBU R .640 .330 G .290 .600 B .150 .060;\n"
    "// Japanese P22 R .625 .350 G .280 .605 B .152 .062 (Sony KV-20M20 and others, via Dogway's grade).\n"
    "mat3 phosphorMatrix(float p)\n"
    "{\n"
    "    if (p < 2.5) return mat3(0.939542, 0.017772, -0.001622, 0.050181, 0.965793, -0.004370, 0.010277, 0.016435, 1.005991);\n"
    "    if (p < 3.5) return mat3(1.044043, 0.0, 0.0, -0.044043, 1.0, 0.011793, 0.0, 0.0, 0.988207);\n"
    "    return mat3(1.081942, 0.038032, -0.007481, -0.088427, 0.959991, 0.015170, 0.006485, 0.001977, 0.992311);\n"
    "}\n"
    "\n"
    "#if defined(VERTEX)\n"
    "uniform mat4 MVPMatrix;\n"
    "in vec4 VertexCoord;\n"
    "in vec2 TexCoord;\n"
    "out vec2 vTexCoord;\n"
    "\n"
    "void lr_main()\n"
    "{\n"
    "    gl_Position = MVPMatrix * VertexCoord;\n"
    "    vTexCoord = TexCoord;\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    lr_main();\n"
    "}\n"
    "\n"
    "#elif defined(FRAGMENT)\n"
    "in vec2 vTexCoord;\n"
    "out vec4 FragColor;\n"
    "uniform sampler2D Source;\n"
    "\n"
    "// Dither to the 8-bit output in linear light: each channel takes the code just below or just\n"
    "// above its value, the upper one with the chance that makes their average in linear light the\n"
    "// value itself (noise added to the gamma-encoded value would brighten dark gradients a little).\n"
    "// The noise is interleaved gradient noise: high frequency, no clumps, the same for the three\n"
    "// channels so it adds no colour noise.\n"
    "void lr_main()\n"
    "{\n"
    "    vec3 lin = clamp(textureLod(Source, vTexCoord, 0.0).rgb, 0.0, 1.0);\n"
    "    vec3 code = min(floor(pow(lin, vec3(1.0 / 2.2)) * 255.0), 254.0);\n"
    "    vec3 lo = pow(code / 255.0, vec3(2.2)), hi = pow((code + 1.0) / 255.0, vec3(2.2));\n"
    "    vec3 up = clamp((lin - lo) / (hi - lo), 0.0, 1.0);\n"
    "    vec2 fc = floor(vTexCoord * LR_OutputSize.xy);\n"
    "    float n = fract(52.9829189 * fract(dot(fc, vec2(0.06711056, 0.00583715))));\n"
    "    FragColor = vec4((code + vec3(greaterThan(up, vec3(n)))) / 255.0, 1.0);\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    lr_main();\n"
    "}\n"
    "#endif\n"
    "\n";

